css:
@property --ded-enrol-n { syntax: '<integer>'; inherits: false; initial-value: 0; }
@property --ded-enrol-p { syntax: '<number>'; inherits: true; initial-value: 0; }

@keyframes ded-enrol-in { from { opacity: 0; translate: 0 10px; } }
@keyframes ded-enrol-wipe { from { clip-path: inset(0 100% 0 0); } to { clip-path: inset(0 0 0 0); } }
@keyframes ded-enrol-pop { from { opacity: 0; scale: 0.2; } }
@keyframes ded-enrol-seatview { from { clip-path: inset(0 100% 0 0); opacity: 0.2; } to { clip-path: inset(0 0 0 0); opacity: 1; } }

.ded-enrol {
  /* re-theme with these four */
  --ded-enrol-paper: oklch(0.975 0.009 85);
  --ded-enrol-ink: oklch(0.25 0.03 255);
  --ded-enrol-accent: oklch(0.57 0.15 40);
  --ded-enrol-warn: oklch(0.56 0.19 22);
  /* derived */
  --ded-enrol-card: color-mix(in oklch, var(--ded-enrol-paper), white 70%);
  --ded-enrol-sunk: color-mix(in oklch, var(--ded-enrol-paper), var(--ded-enrol-ink) 4%);
  --ded-enrol-line: color-mix(in oklch, var(--ded-enrol-ink) 11%, transparent);
  --ded-enrol-line2: color-mix(in oklch, var(--ded-enrol-ink) 24%, transparent);
  --ded-enrol-muted: color-mix(in oklch, var(--ded-enrol-ink) 64%, var(--ded-enrol-paper));
  --ded-enrol-faint: color-mix(in oklch, var(--ded-enrol-ink) 42%, var(--ded-enrol-paper));
  --ded-enrol-tint: color-mix(in oklch, var(--ded-enrol-accent) 12%, var(--ded-enrol-card));
  --ded-enrol-good: oklch(0.52 0.1 165);
  --ded-enrol-amber: oklch(0.66 0.14 70);
  --ded-enrol-ease: cubic-bezier(0.2, 0.8, 0.2, 1);
  --ded-enrol-spring: linear(0, 0.04, 0.16 6%, 0.6 16%, 0.95 25%, 1.06 32%, 1.07 37%, 1.02 48%, 0.995 60%, 1);
  --ded-enrol-mono: ui-monospace, Menlo, Consolas, monospace;

  width: 100%;
  height: var(--ded-enrol-h, 680px);
  container-type: inline-size;
  position: relative;
  overflow: hidden;
  box-sizing: border-box;
  border-radius: 16px;
  background: var(--ded-enrol-paper);
  color: var(--ded-enrol-ink);
  font: 400 13px/1.45 system-ui, -apple-system, "Segoe UI", Roboto, sans-serif;
  accent-color: var(--ded-enrol-accent);
  box-shadow: inset 0 0 0 1px var(--ded-enrol-line);

  & *, & *::before, & *::after { box-sizing: border-box; }
  & button { font: inherit; color: inherit; background: none; border: 0; padding: 0; margin: 0; cursor: pointer; text-align: inherit; }
  & button:disabled { cursor: not-allowed; }
  & :focus-visible { outline: 2px solid var(--ded-enrol-accent); outline-offset: 2px; border-radius: 6px; }
  & h2, & h3, & h4 { margin: 0; text-wrap: balance; }
  & p { margin: 0; text-wrap: pretty; }
  & ol, & ul, & dl, & dd { margin: 0; padding: 0; list-style: none; }
  & svg { display: block; }
  & [hidden] { display: none !important; }
  & .ded-enrol-sr { position: absolute; width: 1px; height: 1px; overflow: hidden; clip-path: inset(50%); white-space: nowrap; }

  .ded-enrol-eyebrow, .ded-enrol-label, .ded-enrol-kl {
    font-size: 10.5px; font-weight: 650; letter-spacing: 0.11em; text-transform: uppercase; color: var(--ded-enrol-muted);
  }

  .ded-enrol-app {
    display: grid; height: 100%;
    grid-template-columns: 228px minmax(0, 1fr);
    grid-template-areas: "side main";
  }

  /* ---------------- side ---------------- */
  .ded-enrol-side {
    grid-area: side; min-height: 0; overflow: auto; display: flex; flex-direction: column; gap: 20px;
    padding: 18px 14px; background: var(--ded-enrol-sunk); border-right: 1px solid var(--ded-enrol-line);
    scrollbar-width: thin; scrollbar-color: var(--ded-enrol-line2) transparent;
  }
  .ded-enrol-brand { display: flex; align-items: center; gap: 10px; padding: 0 4px; }
  .ded-enrol-brand svg { flex: none; width: 34px; height: 34px; padding: 6px; border-radius: 10px; background: var(--ded-enrol-ink); fill: none; stroke: var(--ded-enrol-paper); stroke-width: 1.7; stroke-linecap: round; stroke-linejoin: round; }
  .ded-enrol-brand span { display: grid; line-height: 1.2; min-width: 0; }
  .ded-enrol-brand b { font-size: 14px; font-weight: 700; letter-spacing: -0.01em; }
  .ded-enrol-brand small { font-size: 11px; color: var(--ded-enrol-muted); }

  .ded-enrol-nav { display: grid; gap: 2px; }
  .ded-enrol-nav .ded-enrol-label, .ded-enrol-levels .ded-enrol-label { padding: 0 8px 6px; }
  .ded-enrol-nav button {
    display: grid; grid-template-columns: 18px minmax(0, 1fr) auto; align-items: center; gap: 10px;
    padding: 8px 10px; border-radius: 9px; font-weight: 550; color: var(--ded-enrol-muted);
    transition: background-color 160ms, color 160ms;
  }
  .ded-enrol-nav button svg { width: 18px; height: 18px; fill: none; stroke: currentColor; stroke-width: 1.7; stroke-linecap: round; stroke-linejoin: round; }
  .ded-enrol-nav button:hover { background: var(--ded-enrol-line); color: var(--ded-enrol-ink); }
  .ded-enrol-nav button[aria-current="true"] { background: var(--ded-enrol-card); color: var(--ded-enrol-ink); box-shadow: inset 0 0 0 1px var(--ded-enrol-line), 0 1px 2px var(--ded-enrol-line); }
  .ded-enrol-nav em { font: 600 11px var(--ded-enrol-mono); font-style: normal; color: var(--ded-enrol-faint); font-variant-numeric: tabular-nums; }
  .ded-enrol-nav button[aria-current="true"] em { color: var(--ded-enrol-accent); }

  .ded-enrol-seg { display: inline-flex; padding: 3px; gap: 2px; border-radius: 10px; background: var(--ded-enrol-line); }
  .ded-enrol-seg button {
    display: inline-flex; align-items: center; gap: 6px; padding: 5px 11px; border-radius: 7px;
    font-size: 12.5px; font-weight: 600; color: var(--ded-enrol-muted); transition: background-color 160ms, color 160ms, box-shadow 160ms;
  }
  .ded-enrol-seg button svg { width: 14px; height: 14px; fill: none; stroke: currentColor; stroke-width: 1.8; stroke-linecap: round; }
  .ded-enrol-seg button:hover { color: var(--ded-enrol-ink); }
  .ded-enrol-seg button[aria-checked="true"] { background: var(--ded-enrol-card); color: var(--ded-enrol-ink); box-shadow: 0 1px 2px color-mix(in oklch, var(--ded-enrol-ink) 18%, transparent); }
  .ded-enrol-levels .ded-enrol-seg { display: flex; }
  .ded-enrol-levels .ded-enrol-seg button { flex: 1; justify-content: center; }

  .ded-enrol-legend { display: grid; gap: 7px; padding: 12px; border-radius: 12px; background: var(--ded-enrol-card); box-shadow: inset 0 0 0 1px var(--ded-enrol-line); }
  .ded-enrol-legend div { display: flex; align-items: center; gap: 9px; font-size: 12px; }
  .ded-enrol-foot { margin-top: auto; font-size: 11.5px; color: var(--ded-enrol-muted); padding: 0 4px; }
  .ded-enrol-foot b { color: var(--ded-enrol-ink); font-variant-numeric: tabular-nums; }

  /* seat swatches (legend + seats share them) */
  .ded-enrol-sw, .ded-enrol-seats i, .ded-enrol-over i {
    display: block; width: 10px; height: 10px; border-radius: 3px;
    background-color: transparent; background-image: none;
    box-shadow: inset 0 0 0 1px var(--ded-enrol-line2);
  }
  [data-s="e"]:is(.ded-enrol-sw, i) { background-color: var(--ded-enrol-ink); box-shadow: inset 0 0 0 1px var(--ded-enrol-ink); }
  [data-s="o"]:is(.ded-enrol-sw, i) {
    background-color: color-mix(in oklch, var(--ded-enrol-accent) 22%, var(--ded-enrol-card));
    background-image: repeating-linear-gradient(135deg, var(--ded-enrol-accent) 0 1.6px, transparent 1.6px 3.6px);
    box-shadow: inset 0 0 0 1px var(--ded-enrol-accent);
  }
  [data-s="x"]:is(.ded-enrol-sw, i) {
    background-color: color-mix(in oklch, var(--ded-enrol-warn) 14%, var(--ded-enrol-card));
    background-image: repeating-linear-gradient(45deg, var(--ded-enrol-warn) 0 1.6px, transparent 1.6px 3.6px);
    box-shadow: inset 0 0 0 1px var(--ded-enrol-warn);
  }

  /* ---------------- main ---------------- */
  .ded-enrol-main { grid-area: main; min-width: 0; min-height: 0; display: grid; grid-template-rows: auto auto minmax(0, 1fr); gap: 14px; padding: 16px 18px 16px; }
  .ded-enrol-head { display: flex; flex-wrap: wrap; align-items: flex-end; justify-content: space-between; gap: 12px 18px; }
  .ded-enrol-title { display: grid; gap: 2px; min-width: 0; }
  .ded-enrol-title h2 { font-size: clamp(17px, 1.2rem + 0.5cqi, 23px); font-weight: 720; letter-spacing: -0.022em; line-height: 1.15; }
  .ded-enrol-title p { font-size: 12.5px; color: var(--ded-enrol-muted); font-variant-numeric: tabular-nums; }
  .ded-enrol-ctrls { display: flex; flex-wrap: wrap; align-items: center; gap: 10px; }
  .ded-enrol-scrub {
    display: flex; align-items: center; gap: 10px; height: 36px; padding: 0 12px 0 4px; border-radius: 11px;
    background: var(--ded-enrol-card); box-shadow: inset 0 0 0 1px var(--ded-enrol-line);
  }
  .ded-enrol-scrub input { width: clamp(110px, 15cqi, 190px); margin: 0; }
  .ded-enrol-scrub output { min-width: 4.6em; font: 600 12px var(--ded-enrol-mono); font-variant-numeric: tabular-nums; }
  .ded-enrol-play { display: grid; place-items: center; width: 28px; height: 28px; border-radius: 8px; background: var(--ded-enrol-ink); color: var(--ded-enrol-paper); transition: scale 200ms var(--ded-enrol-spring); }
  .ded-enrol-play:active { scale: 0.9; }
  .ded-enrol-play svg { width: 15px; height: 15px; fill: currentColor; stroke: currentColor; stroke-width: 2.4; stroke-linecap: round; stroke-linejoin: round; }
  .ded-enrol-i-pause { display: none !important; }
  .ded-enrol-play[aria-pressed="true"] .ded-enrol-i-pause { display: block !important; }
  .ded-enrol-play[aria-pressed="true"] .ded-enrol-i-play { display: none !important; }

  /* KPIs */
  .ded-enrol-kpis { display: grid; grid-template-columns: repeat(4, minmax(0, 1fr)); gap: 10px; }
  .ded-enrol-kpi {
    position: relative; display: grid; align-content: start; gap: 1px; padding: 12px 14px; border-radius: 13px;
    background: var(--ded-enrol-card); box-shadow: inset 0 0 0 1px var(--ded-enrol-line);
    animation: ded-enrol-in 560ms var(--ded-enrol-ease) both; animation-delay: calc(var(--i) * 60ms);
  }
  .ded-enrol-kpi small { font-size: 11.5px; color: var(--ded-enrol-muted); font-variant-numeric: tabular-nums; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
  .ded-enrol-kpi small b { font-weight: 650; }
  .ded-enrol-kpi small .ded-enrol-up { color: var(--ded-enrol-good); }
  .ded-enrol-kpi small .ded-enrol-dn { color: var(--ded-enrol-warn); }
  .ded-enrol-num {
    --ded-enrol-n: var(--ded-enrol-v, 0);
    counter-reset: ded-enrol-n var(--ded-enrol-n);
    font-size: clamp(22px, 1rem + 1.4cqi, 30px); font-weight: 720; letter-spacing: -0.03em; line-height: 1.1;
    font-variant-numeric: tabular-nums;
    transition: --ded-enrol-n 650ms var(--ded-enrol-ease);
  }
  .ded-enrol-num::after { content: counter(ded-enrol-n); }
  @starting-style { .ded-enrol-num { --ded-enrol-n: 0; } }
  .ded-enrol-kpi-ring { padding-right: 70px; }
  .ded-enrol-ring {
    --ded-enrol-p: var(--ded-enrol-pv, 0);
    position: absolute; right: 14px; top: 50%; translate: 0 -50%; width: 46px; height: 46px; border-radius: 50%;
    background:
      conic-gradient(from 0deg, transparent calc(95% - 0.6%), var(--ded-enrol-ink) calc(95% - 0.6%) calc(95% + 0.6%), transparent 0),
      conic-gradient(var(--ded-enrol-accent) calc(var(--ded-enrol-p) * 1%), var(--ded-enrol-line) 0);
    transition: --ded-enrol-p 1100ms var(--ded-enrol-ease);
  }
  @starting-style { .ded-enrol-ring { --ded-enrol-p: 0; } }
  .ded-enrol-ring span { position: absolute; inset: 6px; border-radius: 50%; background: var(--ded-enrol-card); }

  /* body */
  .ded-enrol-body {
    min-height: 0; display: grid; gap: 14px;
    grid-template-columns: minmax(0, 1fr) clamp(280px, 31cqi, 370px);
    grid-template-areas: "pane aside";
  }
  .ded-enrol-panel { grid-area: pane; min-height: 0; overflow: auto; scrollbar-width: thin; scrollbar-color: var(--ded-enrol-line2) transparent; }
  .ded-enrol-cards { display: grid; grid-template-columns: repeat(auto-fill, minmax(236px, 1fr)); gap: 10px; align-content: start; padding: 2px; }

  .ded-enrol-prog {
    position: relative; display: grid; gap: 5px; align-content: start; padding: 12px 13px 12px; border-radius: 13px;
    background: var(--ded-enrol-card); box-shadow: inset 0 0 0 1px var(--ded-enrol-line);
    transition: box-shadow 200ms, translate 260ms var(--ded-enrol-spring);
    animation: ded-enrol-in 520ms var(--ded-enrol-ease) both; animation-delay: calc(120ms + var(--i) * 38ms);
  }
  .ded-enrol-prog:hover { translate: 0 -2px; box-shadow: inset 0 0 0 1px var(--ded-enrol-line2), 0 10px 24px -16px color-mix(in oklch, var(--ded-enrol-ink) 60%, transparent); }
  .ded-enrol-prog[aria-expanded="true"] { box-shadow: inset 0 0 0 2px var(--ded-enrol-accent), 0 10px 24px -16px color-mix(in oklch, var(--ded-enrol-accent) 70%, transparent); }
  .ded-enrol-ph { display: flex; align-items: center; justify-content: space-between; gap: 8px; }
  .ded-enrol-code { font: 600 11px var(--ded-enrol-mono); letter-spacing: 0.02em; color: var(--ded-enrol-muted); }
  .ded-enrol-badge {
    font-size: 10.5px; font-weight: 700; letter-spacing: 0.04em; text-transform: uppercase; padding: 2px 7px; border-radius: 99px;
    --ded-enrol-b: var(--ded-enrol-good);
    color: color-mix(in oklch, var(--ded-enrol-b), var(--ded-enrol-ink) 25%);
    background: color-mix(in oklch, var(--ded-enrol-b) 15%, var(--ded-enrol-card));
    transition: background-color 300ms, color 300ms;
  }
  .ded-enrol-badge[data-s="full"] { --ded-enrol-b: var(--ded-enrol-ink); color: var(--ded-enrol-paper); background: var(--ded-enrol-ink); }
  .ded-enrol-badge[data-s="watch"] { --ded-enrol-b: var(--ded-enrol-amber); }
  .ded-enrol-badge[data-s="risk"] { --ded-enrol-b: var(--ded-enrol-warn); }
  .ded-enrol-pn { font-size: 14px; font-weight: 650; letter-spacing: -0.01em; line-height: 1.25; }
  .ded-enrol-pm { font-size: 11.5px; color: var(--ded-enrol-muted); }
  .ded-enrol-seatrow { display: flex; align-items: flex-start; gap: 6px; margin: 5px 0 3px; }
  .ded-enrol-seats { flex: 1; display: grid; grid-template-columns: repeat(auto-fill, 10px); gap: 3px; }
  .ded-enrol-seats i, .ded-enrol-over i {
    transition: background-color 360ms var(--ded-enrol-ease), box-shadow 360ms var(--ded-enrol-ease), background-image 360ms allow-discrete;
    transition-delay: calc(var(--i, 0) * 6ms);
  }
  .ded-enrol-over { display: grid; grid-template-columns: repeat(2, 10px); gap: 3px; padding-left: 6px; border-left: 1.5px dashed var(--ded-enrol-warn); }
  .ded-enrol-over:empty { display: none; }
  .ded-enrol-pf { display: flex; align-items: baseline; justify-content: space-between; gap: 8px; font-size: 11.5px; color: var(--ded-enrol-muted); font-variant-numeric: tabular-nums; }
  .ded-enrol-pf b { color: var(--ded-enrol-ink); font-weight: 650; }
  .ded-enrol-pf strong { font: 650 12px var(--ded-enrol-mono); color: var(--ded-enrol-ink); }
  .ded-enrol-empty { grid-column: 1 / -1; padding: 40px 16px; text-align: center; color: var(--ded-enrol-muted); }

  @supports (animation-timeline: view()) {
    .ded-enrol-seats { animation: ded-enrol-seatview linear both; animation-timeline: view(); animation-range: entry 0% entry 90%; }
  }

  /* table */
  .ded-enrol-tablewrap { container-type: inline-size; border-radius: 13px; background: var(--ded-enrol-card); box-shadow: inset 0 0 0 1px var(--ded-enrol-line); }
  .ded-enrol-table { width: 100%; border-collapse: separate; border-spacing: 0; font-variant-numeric: tabular-nums; }
  .ded-enrol-table th { position: sticky; top: 0; z-index: 1; background: var(--ded-enrol-card); text-align: left; padding: 0; border-bottom: 1px solid var(--ded-enrol-line2); }
  .ded-enrol-table th button { display: flex; align-items: center; gap: 4px; width: 100%; padding: 10px 9px; font-size: 10.5px; font-weight: 650; letter-spacing: 0.04em; text-transform: uppercase; color: var(--ded-enrol-muted); }
  .ded-enrol-table th button { position: relative; }
  .ded-enrol-table th button::after { content: ""; position: absolute; right: 1px; top: 50%; margin-top: -4px; width: 6px; height: 6px; border: solid currentColor; border-width: 0 1.6px 1.6px 0; rotate: 45deg; translate: 0 -2px; opacity: 0; transition: rotate 220ms var(--ded-enrol-ease), opacity 150ms; }
  .ded-enrol-table th:not(.ded-enrol-n) button::after { position: static; margin: -3px 0 0 6px; }
  .ded-enrol-table th[aria-sort="ascending"] button::after { opacity: 1; rotate: 225deg; translate: 0 2px; }
  .ded-enrol-table th[aria-sort="descending"] button::after { opacity: 1; }
  .ded-enrol-table th:not([aria-sort="none"]) button { color: var(--ded-enrol-ink); }
  .ded-enrol-table .ded-enrol-n, .ded-enrol-table .ded-enrol-n button { text-align: right; justify-content: flex-end; }
  .ded-enrol-table td { padding: 9px 9px; border-bottom: 1px solid var(--ded-enrol-line); white-space: nowrap; }
  .ded-enrol-table td:first-child { white-space: normal; min-width: 140px; }
  .ded-enrol-table tbody tr { cursor: pointer; transition: background-color 140ms; }
  .ded-enrol-table tbody tr:hover { background: var(--ded-enrol-sunk); }
  .ded-enrol-table tbody tr[aria-selected="true"] { background: var(--ded-enrol-tint); }
  .ded-enrol-table td b { font-weight: 650; }
  .ded-enrol-table td small { display: block; font-size: 11px; color: var(--ded-enrol-muted); }
  .ded-enrol-table tfoot td { position: sticky; bottom: 0; background: var(--ded-enrol-sunk); font-weight: 700; border-top: 1px solid var(--ded-enrol-line2); border-bottom: 0; }
  .ded-enrol-bar { display: inline-block; vertical-align: middle; width: 40px; height: 6px; margin-right: 7px; border-radius: 9px; background: var(--ded-enrol-line); overflow: hidden; }
  @container (max-width: 600px) { .ded-enrol-bar { display: none; } }
  .ded-enrol-bar i { display: block; height: 100%; border-radius: inherit; background: var(--ded-enrol-accent); transform-origin: left; }

  /* aside */
  .ded-enrol-aside { grid-area: aside; min-height: 0; display: grid; grid-template-rows: minmax(0, 1.3fr) minmax(0, 1fr); gap: 12px; }
  .ded-enrol-card { min-height: 0; display: grid; grid-template-rows: auto minmax(0, 1fr); gap: 8px; padding: 12px 14px 12px; border-radius: 13px; background: var(--ded-enrol-card); box-shadow: inset 0 0 0 1px var(--ded-enrol-line); }
  .ded-enrol-card > header { display: flex; align-items: baseline; justify-content: space-between; gap: 8px; flex-wrap: wrap; }
  .ded-enrol-card h3 { font-size: 13px; font-weight: 700; letter-spacing: -0.005em; }
  .ded-enrol-card > header > span { font-size: 11.5px; color: var(--ded-enrol-muted); }
  .ded-enrol-key { display: flex; gap: 10px; font-size: 11px; color: var(--ded-enrol-muted); }
  .ded-enrol-key li { display: flex; align-items: center; gap: 5px; }
  .ded-enrol-key i { width: 14px; height: 0; border-top: 2.25px solid var(--ded-enrol-accent); }
  .ded-enrol-key i[data-s="ly"] { border-top: 1.6px dashed var(--ded-enrol-muted); }
  .ded-enrol-key i[data-s="tg"] { border-top: 1.4px dotted var(--ded-enrol-good); }

  .ded-enrol-chart { position: relative; min-height: 150px; }
  .ded-enrol-chart svg { position: absolute; inset: 0; width: 100%; height: 100%; overflow: visible; cursor: crosshair; touch-action: pan-y; }
  .ded-enrol-chart .ded-enrol-g line { stroke: var(--ded-enrol-line); }
  .ded-enrol-chart text { fill: var(--ded-enrol-faint); font: 10.5px var(--ded-enrol-mono); font-variant-numeric: tabular-nums; }
  .ded-enrol-plot { animation: ded-enrol-wipe 1100ms var(--ded-enrol-ease) both 200ms; }
  .ded-enrol-area { fill: color-mix(in oklch, var(--ded-enrol-accent) 12%, transparent); transition: d 520ms var(--ded-enrol-ease); }
  .ded-enrol-ty { fill: none; stroke: var(--ded-enrol-accent); stroke-width: 2.25; stroke-linejoin: round; transition: d 520ms var(--ded-enrol-ease); }
  .ded-enrol-ly { fill: none; stroke: var(--ded-enrol-muted); stroke-width: 1.5; stroke-dasharray: 4 4; transition: d 520ms var(--ded-enrol-ease); }
  .ded-enrol-tg { stroke: var(--ded-enrol-good); stroke-width: 1.4; stroke-dasharray: 1.5 3.5; stroke-linecap: round; }
  .ded-enrol-tgl { fill: var(--ded-enrol-good) !important; font-weight: 600; }
  .ded-enrol-mark { stroke: var(--ded-enrol-ink); stroke-width: 1; transition: translate 380ms var(--ded-enrol-ease); }
  .ded-enrol-dot { fill: var(--ded-enrol-card); stroke: var(--ded-enrol-accent); stroke-width: 2.25; transition: translate 380ms var(--ded-enrol-ease); animation: ded-enrol-pop 420ms var(--ded-enrol-spring) both 1100ms; transform-box: fill-box; transform-origin: center; }
  .ded-enrol-hair { stroke: var(--ded-enrol-line2); stroke-dasharray: 2 3; opacity: 0; transition: opacity 120ms; }
