const $ = (s, el = root) => el.querySelector(s);
const $$ = (s, el = root) => Array.from(el.querySelectorAll(s));
const reduce = matchMedia('(prefers-reduced-motion: reduce)').matches;
const uid = Math.random().toString(36).slice(2, 7);
$$('[id]').forEach(el => { el.id += '-' + uid; });
$$('[aria-labelledby]').forEach(el => el.setAttribute('aria-labelledby', el.getAttribute('aria-labelledby') + '-' + uid));
const NS = 'http://www.w3.org/2000/svg';
const mk = (tag, attrs, parent) => { const e = document.createElementNS(NS, tag); for (const k in attrs) e.setAttribute(k, attrs[k]); if (parent) parent.appendChild(e); return e; };
const esc = s => String(s).replace(/[&<>"]/g, c => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;' }[c]));

/* ---------------- data: 16 weekly snapshots, 1 Jun to 14 Sep 2026 ---------------- */
const MON = ['Jan', 'Feb', 'Mar', 'Apr', 'May', 'Jun', 'Jul', 'Aug', 'Sep', 'Oct', 'Nov', 'Dec'];
const WEEKS = 16, LAST = WEEKS - 1;
const CENSUS = new Date(2026, 8, 18);
const wkDate = w => new Date(2026, 5, 1 + 7 * w);
const fmtD = d => d.getDate() + ' ' + MON[d.getMonth()];
const CONV = 0.62, TARGET = 0.95;
const CAMPUS = { riv: 'Riverside', nor: 'Northfield', onl: 'Online' };
const LEVEL = { L2: 'Level 2', L3: 'Level 3', HE: 'Higher education' };

const P = [
  { code: 'ENG-L3', name: 'Engineering Technology', campus: 'riv', level: 'L3', cap: 48, E: 44, O: 6, W: 5, LY: 45, mid: 6.2, k: 2.1, lead: 'Dr Ifeoma Raines' },
  { code: 'HSC-L3', name: 'Health & Social Care', campus: 'riv', level: 'L3', cap: 60, E: 58, O: 4, W: 11, LY: 55, mid: 5.4, k: 2.0, lead: 'Marguerite Dunleavy' },
  { code: 'CMP-L3', name: 'Computing & Digital', campus: 'riv', level: 'L3', cap: 40, E: 40, O: 3, W: 9, LY: 38, mid: 5.0, k: 1.8, lead: 'Tomasz Achebe-Wren' },
  { code: 'ART-L3', name: 'Art & Design Foundation', campus: 'riv', level: 'L3', cap: 36, E: 22, O: 7, W: 0, LY: 30, mid: 8.0, k: 2.6, lead: 'Saoirse Lindqvist' },
  { code: 'BLD-L2', name: 'Construction Trades', campus: 'riv', level: 'L2', cap: 32, E: 28, O: 2, W: 3, LY: 29, mid: 7.4, k: 2.3, lead: 'Declan Oyelaran' },
  { code: 'MVT-L2', name: 'Motor Vehicle Maintenance', campus: 'nor', level: 'L2', cap: 24, E: 23, O: 1, W: 6, LY: 24, mid: 6.0, k: 1.9, lead: 'Priya Castellanos' },
  { code: 'HBT-L2', name: 'Hair & Beauty Therapy', campus: 'nor', level: 'L2', cap: 30, E: 17, O: 5, W: 0, LY: 26, mid: 8.6, k: 2.4, lead: 'Bronagh Feeney' },
  { code: 'CAT-L2', name: 'Professional Cookery', campus: 'nor', level: 'L2', cap: 24, E: 19, O: 3, W: 0, LY: 21, mid: 7.8, k: 2.2, lead: 'Anselm Kowalczyk' },
  { code: 'SPT-L3', name: 'Sport & Exercise Science', campus: 'nor', level: 'L3', cap: 42, E: 39, O: 5, W: 2, LY: 36, mid: 6.6, k: 2.0, lead: 'Keziah Morrow' },
  { code: 'ACC-HE', name: 'Accounting HNC', campus: 'onl', level: 'HE', cap: 30, E: 18, O: 8, W: 0, LY: 22, mid: 9.8, k: 2.5, lead: 'Olumide Hartigan' },
  { code: 'DAT-HE', name: 'Data Analytics HNC', campus: 'onl', level: 'HE', cap: 36, E: 33, O: 6, W: 4, LY: 27, mid: 8.8, k: 2.2, lead: 'Ingrid Achterberg' },
  { code: 'EYE-HE', name: 'Early Years Foundation Degree', campus: 'onl', level: 'HE', cap: 28, E: 12, O: 6, W: 0, LY: 19, mid: 10.4, k: 2.7, lead: 'Fenella Nakamura' }
];
const sig = (w, mid, k) => 1 / (1 + Math.exp(-(w - mid) / k));
const curve = (mid, k) => { const a = sig(-3, mid, k), b = sig(LAST, mid, k); return w => (sig(w, mid, k) - a) / (b - a); };
P.forEach((p, i) => {
  p.i = i;
  const f = curve(p.mid, p.k), fl = curve(p.mid + 0.7, p.k * 1.05);
  p.e = []; p.o = []; p.wl = []; p.ly = [];
  for (let w = 0; w < WEEKS; w++) {
    p.e[w] = Math.round(p.E * f(w));
    p.o[w] = p.O + Math.round((p.E - p.e[w]) * 0.85);
    p.wl[w] = Math.round(p.W * f(w));
    p.ly[w] = Math.round(p.LY * fl(w));
  }
  p.rel = [];
  p.log = [];
  for (let w = LAST - 2; w <= LAST; w++) {
    const d = p.e[w] - p.e[w - 1];
    if (d > 0) p.log.unshift({ t: 'w/c ' + fmtD(wkDate(w)), msg: `${d} enrolled at induction ${d === 1 ? 'session' : 'sessions'}` });
  }
  if (!p.log.length) p.log.push({ t: 'w/c ' + fmtD(wkDate(LAST)), msg: 'No new enrolments this week' });
});

/* one programme as at week w — everything on screen derives from this */
const at = (p, w) => {
  let rel = 0;
  p.rel.forEach(r => { if (r.w <= w) rel += r.n; });
  const e = p.e[w], o = p.o[w] + rel, wl = Math.max(0, p.wl[w] - rel);
  const raw = e + Math.round(o * CONV);
  const proj = Math.min(p.cap, raw), pf = raw / p.cap;
  const s = e >= p.cap ? 'full' : pf >= 0.9 ? 'ok' : pf >= 0.7 ? 'watch' : 'risk';
  return { e, o, wl, proj, pf, s, ly: p.ly[w], vac: Math.max(0, p.cap - e - o), over: Math.max(0, e + o - p.cap) };
};
const STATUS = { full: 'Full', ok: 'On track', watch: 'Watch', risk: 'At risk' };

const S = { w: LAST, campus: 'all', level: 'all', view: 'seats', sort: 'pf', dir: 1, open: null };
const inFilter = p => (S.campus === 'all' || p.campus === S.campus) && (S.level === 'all' || p.level === S.level);
const shown = () => P.filter(inFilter);

/* ---------------- helpers ---------------- */
const toastEl = $('.ded-enrol-toast');
let toastT = 0;
const toast = msg => { toastEl.textContent = msg; toastEl.classList.add('is-on'); clearTimeout(toastT); toastT = setTimeout(() => toastEl.classList.remove('is-on'), 2600); };
const setNum = (el, v) => {
  el.style.setProperty('--ded-enrol-v', v);
  let sr = el.nextElementSibling;
  if (!sr || !sr.classList.contains('ded-enrol-sr')) { sr = document.createElement('span'); sr.className = 'ded-enrol-sr'; el.after(sr); el.setAttribute('aria-hidden', 'true'); }
  sr.textContent = v.toLocaleString('en-GB');
};
const signed = n => (n > 0 ? '+' : n < 0 ? '−' : '±') + Math.abs(n);
const niceMax = v => { const p = Math.pow(10, Math.floor(Math.log10(v))); const m = v / p; return (m <= 1 ? 1 : m <= 2 ? 2 : m <= 2.5 ? 2.5 : m <= 5 ? 5 : 10) * p; };

/* ---------------- programme cards: built once, updated in place ---------------- */
const cardsEl = $('.ded-enrol-cards');
P.forEach(p => {
  const b = document.createElement('button');
  b.type = 'button'; b.className = 'ded-enrol-prog'; b.dataset.i = p.i; b.setAttribute('aria-expanded', 'false');
  b.innerHTML = `<span class="ded-enrol-ph"><span class="ded-enrol-code">${p.code}</span><span class="ded-enrol-badge"></span></span>
    <span class="ded-enrol-pn">${esc(p.name)}</span>
    <span class="ded-enrol-pm">${CAMPUS[p.campus]} · ${LEVEL[p.level]} · ${p.cap} seats</span>
    <span class="ded-enrol-seatrow" aria-hidden="true"><span class="ded-enrol-seats">${Array.from({ length: p.cap }, (_, k) => `<i style="--i:${k}"></i>`).join('')}</span><span class="ded-enrol-over"></span></span>
    <span class="ded-enrol-pf"><span><b data-f="e"></b> enrolled · <b data-f="o"></b> offers · <b data-f="w"></b> waitlist</span><strong data-f="pf"></strong></span>`;
  p.card = b; p.seats = Array.from(b.querySelectorAll('.ded-enrol-seats i')); p.overEl = b.querySelector('.ded-enrol-over');
  cardsEl.appendChild(b);
});
const emptyEl = document.createElement('p');
emptyEl.className = 'ded-enrol-empty'; emptyEl.textContent = 'No programmes match this campus and level.';
cardsEl.appendChild(emptyEl);

function paintCards() {
  let n = 0;
  P.forEach(p => {
    const on = inFilter(p);
    p.card.hidden = !on;
    if (!on) return;
    p.card.style.setProperty('--i', n++);
    const a = at(p, S.w);
    p.seats.forEach((el, k) => { const s = k < a.e ? 'e' : k < a.e + a.o ? 'o' : 'v'; if (el.dataset.s !== s) el.dataset.s = s; });
    const overN = p.overEl.children.length;
    if (overN !== a.over) {
      if (a.over > overN) for (let k = overN; k < a.over; k++) { const i = document.createElement('i'); i.dataset.s = 'x'; i.style.setProperty('--i', k); p.overEl.appendChild(i); }
      else while (p.overEl.children.length > a.over) p.overEl.lastElementChild.remove();
    }
    const badge = p.card.querySelector('.ded-enrol-badge');
    badge.dataset.s = a.s; badge.textContent = STATUS[a.s];
    p.card.querySelector('[data-f="e"]').textContent = a.e;
    p.card.querySelector('[data-f="o"]').textContent = a.o;
    p.card.querySelector('[data-f="w"]').textContent = a.wl;
    p.card.querySelector('[data-f="pf"]').textContent = Math.round(a.proj / p.cap * 100) + '%';
    p.card.setAttribute('aria-label', `${p.name}, ${CAMPUS[p.campus]}. ${a.e} of ${p.cap} seats enrolled, ${a.o} offers held${a.over ? ', ' + a.over + ' over capacity' : ''}, ${a.wl} on the waitlist. ${STATUS[a.s]}.`);
  });
  emptyEl.hidden = n > 0;
}

/* ---------------- KPIs, headings, nav counts ---------------- */
function paintTotals() {
  const list = shown();
  const t = list.reduce((s, p) => { const a = at(p, S.w); s.cap += p.cap; s.e += a.e; s.o += a.o; s.proj += a.proj; s.ly += a.ly; s.vac += a.vac; s.over += a.over; return s; }, { cap: 0, e: 0, o: 0, proj: 0, ly: 0, vac: 0, over: 0 });
  setNum($('[data-k="cap"]'), t.cap);
  setNum($('[data-k="enr"]'), t.e);
  setNum($('[data-k="off"]'), t.o);
  setNum($('[data-k="proj"]'), t.proj);
  const camps = new Set(list.map(p => p.campus)).size;
  $('[data-k="capn"]').textContent = `${list.length} programme${list.length === 1 ? '' : 's'} · ${camps} campus${camps === 1 ? '' : 'es'}`;
  const d = t.e - t.ly, pct = t.cap ? Math.round(t.e / t.cap * 100) : 0;
  $('[data-k="enrn"]').innerHTML = `${pct}% of seats · <b class="${d >= 0 ? 'ded-enrol-up' : 'ded-enrol-dn'}">${signed(d)}</b> vs 2025`;
  $('[data-k="offn"]').innerHTML = t.over ? `<b class="ded-enrol-dn">${t.over}</b> over capacity · ${t.vac} unoffered` : `${t.vac} seats not yet offered`;
  const pp = t.cap ? t.proj / t.cap * 100 : 0, tgt = Math.round(t.cap * TARGET);
  $('[data-k="projn"]').innerHTML = `${Math.round(pp)}% · target <b>${tgt}</b>`;
  $('.ded-enrol-ring').style.setProperty('--ded-enrol-pv', pp.toFixed(1));
  const dt = wkDate(S.w), days = Math.round((CENSUS - dt) / 864e5);
  $('[data-k="asof"]').textContent = `As at Mon ${fmtD(dt)} 2026 · ${days} days to census on Fri 18 Sep`;
  $('[data-k="wk"]').textContent = fmtD(dt);
  const rng = $('.ded-enrol-scrub input');
  rng.value = S.w; rng.setAttribute('aria-valuetext', 'Week of ' + fmtD(dt));
  ['all', 'riv', 'nor', 'onl'].forEach(c => {
    const seats = P.filter(p => (c === 'all' || p.campus === c) && (S.level === 'all' || p.level === S.level)).reduce((s, p) => s + p.cap, 0);
    $(`[data-n="${c}"]`).textContent = seats;
  });
}

/* ---------------- table ---------------- */
const tbody = $('.ded-enrol-table tbody'), trs = new Map();
function paintTable() {
  const key = S.sort, dir = S.dir;
  const rows = shown().map(p => ({ p, a: at(p, S.w) }));
  const val = r => key === 'name' ? r.p.name : key === 'cap' ? r.p.cap : key === 'e' ? r.a.e : key === 'o' ? r.a.o : key === 'w' ? r.a.wl : r.a.proj / r.p.cap;
  rows.sort((x, y) => { const a = val(x), b = val(y); return (typeof a === 'string' ? a.localeCompare(b) : a - b) * dir || x.p.i - y.p.i; });
  /* rows are keyed per programme and reused, so a replay tick never swaps a row out from under a click */
  const keep = new Set(rows.map(r => r.p.i));
  trs.forEach((tr, i) => { if (!keep.has(i)) tr.remove(); });
  rows.forEach(({ p, a }, idx) => {
    let tr = trs.get(p.i);
    if (!tr) { tr = document.createElement('tr'); tr.dataset.i = p.i; trs.set(p.i, tr); }
    tr.tabIndex = -1;
    tr.setAttribute('aria-selected', S.open === p ? 'true' : 'false');
    tr.innerHTML = `<td><b>${esc(p.name)}</b><small>${p.code} · ${CAMPUS[p.campus]} · ${p.level}</small></td>
    <td class="ded-enrol-n">${p.cap}</td><td class="ded-enrol-n">${a.e}</td><td class="ded-enrol-n">${a.o}${a.over ? ` <small>${a.over} over</small>` : ''}</td><td class="ded-enrol-n">${a.wl}</td>
    <td class="ded-enrol-n"><span class="ded-enrol-bar"><i style="transform:scaleX(${Math.min(1, a.proj / p.cap).toFixed(3)})"></i></span>${Math.round(a.proj / p.cap * 100)}%</td>`;
    if (tbody.children[idx] !== tr) tbody.insertBefore(tr, tbody.children[idx] || null);
  });
  const first = tbody.querySelector('tr'); if (first) first.tabIndex = 0;
  const t = rows.reduce((s, { p, a }) => { s.cap += p.cap; s.e += a.e; s.o += a.o; s.wl += a.wl; s.proj += a.proj; return s; }, { cap: 0, e: 0, o: 0, wl: 0, proj: 0 });
  $('.ded-enrol-table tfoot tr').innerHTML = `<td>Total · ${rows.length} programme${rows.length === 1 ? '' : 's'}</td><td class="ded-enrol-n">${t.cap}</td><td class="ded-enrol-n">${t.e}</td><td class="ded-enrol-n">${t.o}</td><td class="ded-enrol-n">${t.wl}</td><td class="ded-enrol-n">${t.cap ? Math.round(t.proj / t.cap * 100) : 0}%</td>`;
  $$('.ded-enrol-table th').forEach(th => { const k = th.querySelector('button').dataset.sort; th.setAttribute('aria-sort', k === key ? (dir > 0 ? 'ascending' : 'descending') : 'none'); });
}

/* ---------------- watch list ---------------- */
function paintWatch() {
  const list = shown().map(p => ({ p, a: at(p, S.w) })).filter(r => r.a.s === 'risk' || r.a.s === 'watch').sort((x, y) => x.a.pf - y.a.pf);
  $('[data-k="watchn"]').textContent = list.length ? `${list.length} below 90% projected` : '';
  const ol = $('.ded-enrol-watch ol');
  ol.innerHTML = list.length ? list.map(({ p, a }) => `<li><button type="button" data-i="${p.i}" aria-label="${esc(p.name)}: ${Math.round(a.pf * 100)}% projected. Open details">
      <span class="ded-enrol-wn">${esc(p.name)}</span><span class="ded-enrol-wp" data-s="${a.s}">${Math.round(a.pf * 100)}%</span>
      <span class="ded-enrol-wb"><u style="width:${Math.min(100, a.pf * 100).toFixed(1)}%"></u><i style="width:${(a.e / p.cap * 100).toFixed(1)}%"></i></span></button></li>`).join('')
    : '<li class="ded-enrol-ok">Every programme in view is on track or full for this week.</li>';
}

/* ---------------- chart ---------------- */
const chartWrap = $('.ded-enrol-chart'), svg = chartWrap.querySelector('svg'), tip = $('.ded-enrol-tip');
const gGrid = mk('g', { class: 'ded-enrol-g' }, svg);
const gX = mk('g', {}, svg);
const gPlot = mk('g', { class: 'ded-enrol-plot' }, svg);
const pArea = mk('path', { class: 'ded-enrol-area' }, gPlot);
const pLy = mk('path', { class: 'ded-enrol-ly' }, gPlot);
const pTy = mk('path', { class: 'ded-enrol-ty' }, gPlot);
const lTg = mk('line', { class: 'ded-enrol-tg' }, svg);
const tTg = mk('text', { class: 'ded-enrol-tgl', 'text-anchor': 'end' }, svg);
const lMark = mk('line', { class: 'ded-enrol-mark' }, svg);
const lHair = mk('line', { class: 'ded-enrol-hair' }, svg);
const cDot = mk('circle', { class: 'ded-enrol-dot', r: 4.5, cx: 0, cy: 0 }, svg);
let geo = null, drawnOnce = false;
const series = () => {
  const list = shown();
  const ty = [], ly = [];
  for (let w = 0; w < WEEKS; w++) { ty[w] = list.reduce((s, p) => s + at(p, w).e, 0); ly[w] = list.reduce((s, p) => s + p.ly[w], 0); }
  return { ty, ly, tgt: Math.round(list.reduce((s, p) => s + p.cap, 0) * TARGET) };
};
function paintChart() {
  const W = chartWrap.clientWidth, H = chartWrap.clientHeight;
  if (W < 40 || H < 40) return;
  svg.setAttribute('viewBox', `0 0 ${W} ${H}`);
  const m = { l: 34, r: 8, t: 10, b: 20 };
  const { ty, ly, tgt } = series();
  const ymax = niceMax(Math.max(tgt, ...ty, ...ly, 10) * 1.06);
  const x = w => m.l + w / LAST * (W - m.l - m.r), y = v => H - m.b - v / ymax * (H - m.t - m.b);
  geo = { x, y, m, W, H, ty, ly, tgt };
  gGrid.innerHTML = '';
  for (let k = 0; k <= 4; k++) { const v = ymax / 4 * k, yy = y(v); mk('line', { x1: m.l, x2: W - m.r, y1: yy, y2: yy }, gGrid); const t = mk('text', { x: m.l - 6, y: yy + 3.5, 'text-anchor': 'end' }, gGrid); t.textContent = Math.round(v); }
  gX.innerHTML = '';
  for (let w = 0; w < WEEKS; w += 3) { const t = mk('text', { x: x(w), y: H - 4, 'text-anchor': w === 0 ? 'start' : 'middle' }, gX); t.textContent = fmtD(wkDate(w)); }
  const line = arr => arr.map((v, w) => (w ? 'L' : 'M') + x(w).toFixed(1) + ' ' + y(v).toFixed(1)).join(' ');
  const dTy = line(ty), dLy = line(ly), dA = dTy + ` L${x(LAST).toFixed(1)} ${y(0).toFixed(1)} L${x(0).toFixed(1)} ${y(0).toFixed(1)} Z`;
  if (!drawnOnce || reduce) { pTy.setAttribute('d', dTy); pLy.setAttribute('d', dLy); pArea.setAttribute('d', dA); pTy.style.d = pLy.style.d = pArea.style.d = ''; }
  else { pTy.style.d = `path("${dTy}")`; pLy.style.d = `path("${dLy}")`; pArea.style.d = `path("${dA}")`; }
  drawnOnce = true;
  lTg.setAttribute('x1', m.l); lTg.setAttribute('x2', W - m.r); lTg.setAttribute('y1', y(tgt)); lTg.setAttribute('y2', y(tgt));
  tTg.setAttribute('x', W - m.r); tTg.setAttribute('y', y(tgt) - 5); tTg.textContent = 'Target ' + tgt;
  lMark.setAttribute('x1', 0); lMark.setAttribute('x2', 0); lMark.setAttribute('y1', m.t); lMark.setAttribute('y2', H - m.b);
  lMark.style.translate = x(S.w) + 'px 0';
  cDot.style.translate = `${x(S.w)}px ${y(ty[S.w])}px`;
  lHair.setAttribute('y1', m.t); lHair.setAttribute('y2', H - m.b);
}
const wAt = ev => { const r = svg.getBoundingClientRect(); return Math.max(0, Math.min(LAST, Math.round((ev.clientX - r.left - geo.m.l) / (geo.W - geo.m.l - geo.m.r) * LAST))); };
svg.addEventListener('pointermove', ev => {
  if (!geo) return;
  const w = wAt(ev), xx = geo.x(w);
  lHair.setAttribute('x1', xx); lHair.setAttribute('x2', xx);
  const d = geo.ty[w] - geo.ly[w];
  tip.innerHTML = `<b>Week of ${fmtD(wkDate(w))}</b><span><i>2026</i><strong>${geo.ty[w]}</strong></span><span><i>2025</i><strong>${geo.ly[w]}</strong></span><span><i>Difference</i><strong>${signed(d)}</strong></span>`;
  const tw = tip.offsetWidth, left = xx + 12 + tw > geo.W ? xx - 12 - tw : xx + 12;
  tip.style.setProperty('--ded-enrol-tx', left + 'px');
  tip.style.setProperty('--ded-enrol-ty', Math.max(0, geo.y(geo.ty[w]) - 30) + 'px');
  tip.classList.add('is-on');
});
svg.addEventListener('pointerleave', () => tip.classList.remove('is-on'));
svg.addEventListener('click', ev => { if (geo) { stopPlay(); setWeek(wAt(ev)); } });
new ResizeObserver(() => { if (root.isConnected) { paintChart(); if (S.open) paintDrawer(); } }).observe(chartWrap);

/* ---------------- drawer ---------------- */
const drawer = $('.ded-enrol-drawer');
let opener = null;
function paintDrawer() {
  const p = S.open; if (!p) return;
  const a = at(p, S.w);
  $('[data-k="dcode"]').textContent = `${p.code} · ${CAMPUS[p.campus]}`;
  $('[data-k="dname"]').textContent = p.name;
  $('[data-k="dmeta"]').textContent = `${LEVEL[p.level]} · course lead ${p.lead} · as at ${fmtD(wkDate(S.w))}`;
  $('.ded-enrol-dstats').innerHTML = [['Seats', p.cap], ['Enrolled', a.e], ['Offers', a.o], ['Waitlist', a.wl]].map(([k, v]) => `<div><span>${k}</span><b>${v}</b></div>`).join('');
  const box = $('.ded-enrol-dchart'), dsv = box.querySelector('svg');
  const W = box.clientWidth, H = box.clientHeight;
  if (W > 40 && H > 40) {
    dsv.setAttribute('viewBox', `0 0 ${W} ${H}`); dsv.innerHTML = '';
    const m = { l: 26, r: 6, t: 8, b: 16 }, ymax = niceMax(Math.max(p.cap, ...p.ly) * 1.08);
    const x = w => m.l + w / LAST * (W - m.l - m.r), y = v => H - m.b - v / ymax * (H - m.t - m.b);
    const g = mk('g', { class: 'ded-enrol-g' }, dsv);
    for (let k = 0; k <= 2; k++) { const v = ymax / 2 * k; mk('line', { x1: m.l, x2: W - m.r, y1: y(v), y2: y(v) }, g); mk('text', { x: m.l - 5, y: y(v) + 3, 'text-anchor': 'end' }, g).textContent = Math.round(v); }
    mk('line', { class: 'ded-enrol-capl', x1: m.l, x2: W - m.r, y1: y(p.cap), y2: y(p.cap) }, dsv);
    mk('text', { x: W - m.r, y: y(p.cap) - 4, 'text-anchor': 'end' }, dsv).textContent = p.cap + ' seats';
    const ln = arr => arr.map((v, w) => (w ? 'L' : 'M') + x(w).toFixed(1) + ' ' + y(v).toFixed(1)).join(' ');
    mk('path', { class: 'ded-enrol-ly', d: ln(p.ly) }, dsv);
    const tyv = []; for (let w = 0; w < WEEKS; w++) tyv[w] = at(p, w).e;
    mk('path', { class: 'ded-enrol-ty', d: ln(tyv) }, dsv);
    mk('line', { class: 'ded-enrol-mark', x1: x(S.w), x2: x(S.w), y1: m.t, y2: H - m.b }, dsv);
    mk('circle', { r: 3.5, cx: x(S.w), cy: y(tyv[S.w]), fill: 'currentColor' }, dsv);
    mk('text', { x: m.l, y: H - 3 }, dsv).textContent = fmtD(wkDate(0));
    mk('text', { x: W - m.r, y: H - 3, 'text-anchor': 'end' }, dsv).textContent = fmtD(wkDate(LAST));
  }
  const rel = $('[data-act="release"]'), rem = $('[data-act="remind"]');
  const n = Math.min(a.wl, a.vac);
  rel.textContent = n ? `Release ${n} waitlist offer${n === 1 ? '' : 's'}` : 'Release waitlist offers';
  rel.disabled = !n;
  rel.title = n ? `Offer the next ${n} applicant${n === 1 ? '' : 's'} on the waitlist a seat` : !a.wl ? 'No one is on the waitlist this week' : 'Every seat is enrolled or already offered';
  rem.textContent = a.o ? `Remind ${a.o} offer holder${a.o === 1 ? '' : 's'}` : 'Remind offer holders';
  rem.disabled = !a.o;
  rem.title = a.o ? 'Email everyone holding an offer a reminder to enrol' : 'No offers are outstanding this week';
  $('.ded-enrol-log').innerHTML = p.log.map(l => `<li class="${l.fresh ? 'is-new' : ''}"><span>${esc(l.msg)}<time>${esc(l.t)}</time></span></li>`).join('');
  $$('.ded-enrol-table tbody tr').forEach(tr => tr.setAttribute('aria-selected', String(+tr.dataset.i === p.i)));
}
function openDrawer(p, from) {
  if (S.open && S.open !== p) S.open.card.setAttribute('aria-expanded', 'false');
  S.open = p; opener = from || p.card;
  p.card.setAttribute('aria-expanded', 'true');
  drawer.inert = false; drawer.classList.add('is-open');
  paintDrawer();
  $('.ded-enrol-x').focus({ preventScroll: true });
}
function closeDrawer() {
  if (!S.open) return;
  S.open.card.setAttribute('aria-expanded', 'false');
  S.open = null; drawer.classList.remove('is-open'); drawer.inert = true;
  $$('.ded-enrol-table tbody tr[aria-selected="true"]').forEach(tr => tr.setAttribute('aria-selected', 'false'));
  if (opener && opener.isConnected) opener.focus({ preventScroll: true });
}
$('.ded-enrol-x').addEventListener('click', closeDrawer);
$('[data-act="release"]').addEventListener('click', () => {
  const p = S.open; if (!p) return;
  const a = at(p, S.w), n = Math.min(a.wl, a.vac); if (!n) return;
  p.rel.push({ w: S.w, n });
  p.log.forEach(l => { l.fresh = false; });
  p.log.unshift({ t: 'Just now · as at ' + fmtD(wkDate(S.w)), msg: `Released ${n} waitlist offer${n === 1 ? '' : 's'}`, fresh: true });
  renderAll();
  toast(`${n} offer${n === 1 ? '' : 's'} released for ${p.name}`);
});
$('[data-act="remind"]').addEventListener('click', () => {
  const p = S.open; if (!p) return;
  const a = at(p, S.w); if (!a.o) return;
  p.log.forEach(l => { l.fresh = false; });
  p.log.unshift({ t: 'Just now', msg: `Enrolment reminder emailed to ${a.o} offer holder${a.o === 1 ? '' : 's'}`, fresh: true });
  paintDrawer();
  toast(`Reminder queued for ${a.o} ${p.code} offer holder${a.o === 1 ? '' : 's'}`);
});

/* ---------------- render + controls ---------------- */
function renderAll() {
  paintCards(); paintTotals(); paintWatch(); paintChart();
  if (S.view === 'table') paintTable();
  if (S.open) { if (!inFilter(S.open)) closeDrawer(); else paintDrawer(); }
}
function setWeek(w) { if (w === S.w) return; S.w = w; renderAll(); }

cardsEl.addEventListener('click', ev => { const b = ev.target.closest('.ded-enrol-prog'); if (b) { const p = P[+b.dataset.i]; S.open === p ? closeDrawer() : openDrawer(p, b); } });
cardsEl.addEventListener('keydown', ev => {
  const b = ev.target.closest('.ded-enrol-prog'); if (!b) return;
  const vis = P.filter(inFilter).map(p => p.card), i = vis.indexOf(b);
  let j = -1;
  if (ev.key === 'ArrowRight' || ev.key === 'ArrowDown') j = Math.min(vis.length - 1, i + 1);
  if (ev.key === 'ArrowLeft' || ev.key === 'ArrowUp') j = Math.max(0, i - 1);
  if (ev.key === 'Home') j = 0;
  if (ev.key === 'End') j = vis.length - 1;
  if (j > -1) { ev.preventDefault(); vis[j].focus(); }
});
$('.ded-enrol-watch').addEventListener('click', ev => { const b = ev.target.closest('button[data-i]'); if (b) openDrawer(P[+b.dataset.i], b); });
tbody.addEventListener('click', ev => { const tr = ev.target.closest('tr[data-i]'); if (!tr) return; const p = P[+tr.dataset.i]; S.open === p ? closeDrawer() : openDrawer(p, tr); });
tbody.addEventListener('keydown', ev => {
  const tr = ev.target.closest('tr[data-i]'); if (!tr) return;
  if (ev.key === 'Enter' || ev.key === ' ') { ev.preventDefault(); openDrawer(P[+tr.dataset.i], tr); }
  const sib = ev.key === 'ArrowDown' ? tr.nextElementSibling : ev.key === 'ArrowUp' ? tr.previousElementSibling : null;
  if (sib) { ev.preventDefault(); tr.tabIndex = -1; sib.tabIndex = 0; sib.focus(); }
});
$('.ded-enrol-table thead').addEventListener('click', ev => {
  const b = ev.target.closest('button[data-sort]'); if (!b) return;
  const k = b.dataset.sort;
  if (S.sort === k) S.dir = -S.dir; else { S.sort = k; S.dir = k === 'name' ? 1 : -1; }
  paintTable();
});

$('.ded-enrol-nav').addEventListener('click', ev => {
  const b = ev.target.closest('button[data-campus]'); if (!b) return;
  S.campus = b.dataset.campus;
  $$('.ded-enrol-nav button').forEach(x => x === b ? x.setAttribute('aria-current', 'true') : x.removeAttribute('aria-current'));
  renderAll();
});
function radioGroup(group, attr, apply) {
  const btns = $$(`button[${attr}]`, group);
  const pick = b => { btns.forEach(x => { const on = x === b; x.setAttribute('aria-checked', on); x.tabIndex = on ? 0 : -1; }); apply(b.getAttribute(attr)); };
  group.addEventListener('click', ev => { const b = ev.target.closest(`button[${attr}]`); if (b && b.getAttribute('aria-checked') !== 'true') pick(b); });
  group.addEventListener('keydown', ev => {
    const i = btns.indexOf(document.activeElement); if (i < 0) return;
    const d = ev.key === 'ArrowRight' || ev.key === 'ArrowDown' ? 1 : ev.key === 'ArrowLeft' || ev.key === 'ArrowUp' ? -1 : 0;
    if (!d) return; ev.preventDefault();
    const b = btns[(i + d + btns.length) % btns.length]; b.focus(); pick(b);
  });
}
radioGroup($('.ded-enrol-levels .ded-enrol-seg'), 'data-level', v => { S.level = v; renderAll(); });
radioGroup($('.ded-enrol-ctrls .ded-enrol-seg'), 'data-view', v => {
  S.view = v;
  $$('[data-pane]').forEach(el => { el.hidden = el.dataset.pane !== v; });
  if (v === 'table') paintTable();
});

const range = $('.ded-enrol-scrub input');
range.addEventListener('input', () => { stopPlay(); setWeek(+range.value); });

/* replay: one week every 420 ms; skipped while off screen or the tab is hidden */
const playBtn = $('.ded-enrol-play');
let timer = 0, onScreen = true;
new IntersectionObserver(es => { onScreen = es[es.length - 1].isIntersecting; }).observe(root);
function stopPlay() { if (!timer) return; clearInterval(timer); timer = 0; playBtn.setAttribute('aria-pressed', 'false'); playBtn.setAttribute('aria-label', 'Replay the intake week by week'); }
playBtn.addEventListener('click', () => {
  if (timer) { stopPlay(); return; }
  playBtn.setAttribute('aria-pressed', 'true'); playBtn.setAttribute('aria-label', 'Pause the replay');
  if (S.w >= LAST) setWeek(0); else setWeek(S.w + 1);
  timer = setInterval(() => {
    if (!root.isConnected) return void clearInterval(timer);
    if (!onScreen || document.hidden) return;
    if (S.w >= LAST) { stopPlay(); toast('Replay finished: as at ' + fmtD(wkDate(LAST))); return; }
    setWeek(S.w + 1);
  }, reduce ? 900 : 420);
});

root.addEventListener('keydown', ev => { if (ev.key === 'Escape' && S.open) { ev.preventDefault(); closeDrawer(); } });

renderAll();

css:
@keyframes ded-attend-in { from { opacity: 0; translate: 0 8px; } }
@keyframes ded-attend-draw { from { stroke-dashoffset: 1; } to { stroke-dashoffset: 0; } }
@keyframes ded-attend-grow { from { scale: 1 0; } }
@keyframes ded-attend-rowin { from { opacity: 0; translate: -6px 0; } }

.ded-attend {
  /* re-theme with these four */
  --ded-attend-bg: oklch(0.205 0.008 65);
  --ded-attend-ink: oklch(0.94 0.012 85);
  --ded-attend-accent: oklch(0.83 0.14 80);
  --ded-attend-alert: oklch(0.69 0.18 38);
  /* derived */
  --ded-attend-cool: color-mix(in oklch, oklch(0.68 0.04 245), var(--ded-attend-bg) 8%);
  --ded-attend-panel: color-mix(in oklch, var(--ded-attend-bg), var(--ded-attend-ink) 4%);
  --ded-attend-panel2: color-mix(in oklch, var(--ded-attend-bg), var(--ded-attend-ink) 8%);
  --ded-attend-line: color-mix(in oklch, var(--ded-attend-ink) 9%, transparent);
  --ded-attend-line2: color-mix(in oklch, var(--ded-attend-ink) 18%, transparent);
  --ded-attend-muted: color-mix(in oklch, var(--ded-attend-ink) 62%, var(--ded-attend-bg));
  --ded-attend-faint: color-mix(in oklch, var(--ded-attend-ink) 40%, var(--ded-attend-bg));
  --ded-attend-zonec: color-mix(in oklch, var(--ded-attend-alert) 11%, transparent);
  --ded-attend-ease: cubic-bezier(0.22, 0.9, 0.24, 1);
  --ded-attend-spring: linear(0, 0.05, 0.2 7%, 0.64 17%, 0.97 26%, 1.07 33%, 1.06 39%, 1.01 50%, 0.995 62%, 1);
  --ded-attend-mono: ui-monospace, Menlo, Consolas, monospace;

  width: 100%;
  height: var(--ded-attend-h, 680px);
  container-type: inline-size;
  position: relative;
  overflow: hidden;
  box-sizing: border-box;
  display: grid;
  grid-template-rows: auto minmax(0, 1fr);
  grid-template-areas: "top" "main";
  border-radius: 16px;
  background: var(--ded-attend-bg);
  color: var(--ded-attend-ink);
  font: 400 13px/1.45 system-ui, -apple-system, "Segoe UI", Roboto, sans-serif;
  color-scheme: dark;
  accent-color: var(--ded-attend-accent);

  & *, & *::before, & *::after { box-sizing: border-box; }
  & button { font: inherit; color: inherit; background: none; border: 0; padding: 0; margin: 0; cursor: pointer; text-align: inherit; }
  & button:disabled, & button[aria-disabled="true"] { cursor: not-allowed; }
  & :focus-visible { outline: 2px solid var(--ded-attend-accent); outline-offset: 2px; border-radius: 6px; }
  & h3 { margin: 0; font-size: 13px; font-weight: 680; letter-spacing: -0.005em; text-wrap: balance; }
  & p { margin: 0; text-wrap: pretty; }
  & ol, & ul { margin: 0; padding: 0; list-style: none; }
  & svg { display: block; }
  & [hidden] { display: none !important; }
  & .ded-attend-sr { position: absolute; width: 1px; height: 1px; overflow: hidden; clip-path: inset(50%); white-space: nowrap; }
  & .ded-attend-eyebrow { font-size: 10.5px; font-weight: 650; letter-spacing: 0.11em; text-transform: uppercase; color: var(--ded-attend-muted); }

  /* ---------- top bar ---------- */
  .ded-attend-top {
    grid-area: top; display: flex; align-items: center; gap: 16px; flex-wrap: wrap;
    padding: 12px 16px; border-bottom: 1px solid var(--ded-attend-line);
  }
  .ded-attend-main { grid-area: main; min-height: 0; display: grid; grid-template-rows: auto minmax(0, 1fr); gap: 12px; padding: 12px 16px 16px; scrollbar-width: thin; scrollbar-color: var(--ded-attend-line2) transparent; }
  .ded-attend-brand { display: flex; align-items: center; gap: 10px; margin-right: auto; min-width: 0; }
  .ded-attend-brand svg { flex: none; width: 34px; height: 34px; padding: 7px; border-radius: 10px; background: var(--ded-attend-accent); fill: none; stroke: var(--ded-attend-bg); stroke-width: 1.8; stroke-linecap: round; stroke-linejoin: round; }
  .ded-attend-brand span { display: grid; line-height: 1.2; }
  .ded-attend-brand b { font-size: 14px; font-weight: 700; letter-spacing: -0.01em; white-space: nowrap; }
  .ded-attend-brand small { font-size: 11px; color: var(--ded-attend-muted); }
  .ded-attend-tabs { display: flex; gap: 2px; }
  .ded-attend-tabs button {
    position: relative; display: inline-flex; align-items: center; gap: 7px; padding: 8px 12px; border-radius: 9px;
    font-weight: 600; color: var(--ded-attend-muted); transition: color 160ms, background-color 160ms;
  }
  .ded-attend-tabs button svg { width: 16px; height: 16px; fill: none; stroke: currentColor; stroke-width: 1.8; stroke-linecap: round; }
  .ded-attend-tabs button:nth-child(1) svg { fill: currentColor; stroke: none; }
  .ded-attend-tabs button:hover { color: var(--ded-attend-ink); background: var(--ded-attend-line); }
  .ded-attend-tabs button[aria-selected="true"] { color: var(--ded-attend-ink); background: var(--ded-attend-panel2); }
  .ded-attend-tabs button::after { content: ""; position: absolute; left: 12px; right: 12px; bottom: -13px; height: 2px; border-radius: 2px; background: var(--ded-attend-accent); scale: 0 1; transition: scale 320ms var(--ded-attend-ease); }
  .ded-attend-tabs button[aria-selected="true"]::after { scale: 1 1; }
  .ded-attend-tabs em { font: 600 10.5px var(--ded-attend-mono); font-style: normal; padding: 1px 6px; border-radius: 99px; background: color-mix(in oklch, var(--ded-attend-alert) 22%, transparent); color: color-mix(in oklch, var(--ded-attend-alert), white 25%); font-variant-numeric: tabular-nums; }
  .ded-attend-terms { display: inline-flex; padding: 3px; gap: 2px; border-radius: 10px; background: var(--ded-attend-panel); box-shadow: inset 0 0 0 1px var(--ded-attend-line); }
  .ded-attend-terms button { padding: 5px 11px; border-radius: 7px; font-size: 12.5px; font-weight: 600; color: var(--ded-attend-muted); transition: background-color 160ms, color 160ms; }
  .ded-attend-terms button:hover { color: var(--ded-attend-ink); }
  .ded-attend-terms button[aria-checked="true"] { background: var(--ded-attend-ink); color: var(--ded-attend-bg); }

  /* ---------- KPIs ---------- */
  .ded-attend-kpis { display: grid; grid-template-columns: repeat(4, minmax(0, 1fr)); gap: 10px; }
  .ded-attend-kpi {
    display: grid; gap: 1px; padding: 11px 14px; border-radius: 12px; background: var(--ded-attend-panel); box-shadow: inset 0 0 0 1px var(--ded-attend-line);
    animation: ded-attend-in 520ms var(--ded-attend-ease) both; animation-delay: calc(var(--i) * 55ms);
  }
  .ded-attend-kpi > span { font-size: 10.5px; font-weight: 650; letter-spacing: 0.1em; text-transform: uppercase; color: var(--ded-attend-muted); }
  .ded-attend-kpi b { font-size: clamp(21px, 0.9rem + 1.3cqi, 28px); font-weight: 700; letter-spacing: -0.03em; line-height: 1.12; font-variant-numeric: tabular-nums; }
  .ded-attend-kpi b small { font-size: 0.55em; font-weight: 600; color: var(--ded-attend-muted); margin-left: 2px; letter-spacing: 0; }
  .ded-attend-kpi > small { font-size: 11.5px; color: var(--ded-attend-muted); font-variant-numeric: tabular-nums; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
  .ded-attend-kpi > small b { font-size: inherit; letter-spacing: 0; font-weight: 650; color: var(--ded-attend-ink); }
  .ded-attend-kpi-pa { box-shadow: inset 0 0 0 1px color-mix(in oklch, var(--ded-attend-alert) 40%, transparent); background: color-mix(in oklch, var(--ded-attend-alert) 8%, var(--ded-attend-panel)); }
  .ded-attend-kpi-pa b { color: color-mix(in oklch, var(--ded-attend-alert), white 18%); }

  /* ---------- views ---------- */
  .ded-attend-views { min-height: 0; display: grid; }
  .ded-attend-view { min-height: 0; }
  .ded-attend-ov {
    display: grid; gap: 12px;
    grid-template-columns: minmax(0, 1fr) clamp(250px, 27cqi, 320px);
    grid-template-rows: minmax(0, 1.5fr) minmax(0, 1fr);
    grid-template-areas: "swarm alerts" "trend alerts";
  }
  .ded-attend-panel {
    min-height: 0; display: grid; grid-template-rows: auto minmax(0, 1fr); gap: 8px; padding: 12px 14px;
    border-radius: 13px; background: var(--ded-attend-panel); box-shadow: inset 0 0 0 1px var(--ded-attend-line);
  }
  .ded-attend-panel > header { display: flex; align-items: center; justify-content: space-between; gap: 8px 12px; flex-wrap: wrap; min-width: 0; }
  .ded-attend-panel > header p, .ded-attend-panel > header > span { font-size: 11.5px; color: var(--ded-attend-muted); font-variant-numeric: tabular-nums; }
  .ded-attend-swarmp { grid-area: swarm; }
  .ded-attend-trendp { grid-area: trend; }
  .ded-attend-alerts { grid-area: alerts; grid-template-rows: auto minmax(0, 1fr) auto; }

  .ded-attend-years { display: flex; gap: 4px; }
  .ded-attend-years button {
    padding: 4px 9px; border-radius: 99px; font: 600 11.5px var(--ded-attend-mono); color: var(--ded-attend-muted);
    box-shadow: inset 0 0 0 1px var(--ded-attend-line2); transition: background-color 160ms, color 160ms, box-shadow 160ms;
  }
  .ded-attend-years button:hover { color: var(--ded-attend-ink); }
  .ded-attend-years button[aria-pressed="true"] { background: var(--ded-attend-panel2); color: var(--ded-attend-ink); box-shadow: inset 0 0 0 1px var(--ded-attend-line2); }
  .ded-attend-years button[aria-pressed="false"] { text-decoration: line-through; text-decoration-thickness: 1px; opacity: 0.7; }
  .ded-attend-years button[aria-disabled="true"] { opacity: 0.55; }

  .ded-attend-swarm { position: relative; min-height: 160px; }
  .ded-attend-swarm canvas { position: absolute; inset: 0; width: 100%; height: 100%; }
  .ded-attend-handle {
    position: absolute; z-index: 2; top: 0; bottom: 20px; left: 0; width: 22px; margin-left: -11px;
    translate: var(--ded-attend-hx, 0) 0; cursor: ew-resize; touch-action: none; border-radius: 0;
    transition: translate 120ms linear;
  }
  .ded-attend-handle.is-drag { transition: none; }
  .ded-attend-handle::before { content: ""; position: absolute; left: 10px; top: 14px; bottom: 0; width: 2px; border-radius: 2px; background: var(--ded-attend-alert); box-shadow: 0 0 0 3px color-mix(in oklch, var(--ded-attend-alert) 18%, transparent); }
  .ded-attend-grip {
    position: absolute; left: 50%; top: 0; translate: -50% 0; display: flex; align-items: center; gap: 4px; padding: 2px 8px; border-radius: 99px;
    background: var(--ded-attend-alert); color: var(--ded-attend-bg); white-space: nowrap; transition: scale 220ms var(--ded-attend-spring);
  }
  .ded-attend-grip::before, .ded-attend-grip::after { content: ""; width: 0; height: 0; border: 3.5px solid transparent; }
  .ded-attend-grip::before { border-right-color: currentColor; margin-left: -4px; }
  .ded-attend-grip::after { border-left-color: currentColor; margin-right: -4px; }
  .ded-attend-grip b { font: 700 11px var(--ded-attend-mono); font-variant-numeric: tabular-nums; }
  .ded-attend-handle:hover .ded-attend-grip, .ded-attend-handle.is-drag .ded-attend-grip, .ded-attend-handle:focus-visible .ded-attend-grip { scale: 1.08; }
  .ded-attend-handle:focus-visible { outline: none; }
  .ded-attend-handle:focus-visible .ded-attend-grip { box-shadow: 0 0 0 2px var(--ded-attend-bg), 0 0 0 4px var(--ded-attend-accent); }

  .ded-attend-tip {
    position: absolute; z-index: 3; top: 0; left: 0; pointer-events: none; min-width: 150px; max-width: 240px; padding: 8px 10px; border-radius: 10px;
    background: color-mix(in oklch, var(--ded-attend-ink) 94%, var(--ded-attend-bg)); color: var(--ded-attend-bg); font-size: 11.5px; line-height: 1.4;
    font-variant-numeric: tabular-nums; opacity: 0; translate: var(--ded-attend-tx, 0) var(--ded-attend-ty, 0); transition: opacity 120ms;
    box-shadow: 0 10px 24px -10px oklch(0 0 0 / 0.6);
  }
  .ded-attend-tip.is-on { opacity: 1; }
  .ded-attend-tip b { display: block; font-size: 12.5px; }
  .ded-attend-tip small { display: block; opacity: 0.7; }
  .ded-attend-tip span { display: flex; justify-content: space-between; gap: 12px; }
  .ded-attend-tip i { font-style: normal; opacity: 0.7; }

  .ded-attend-key { display: flex; flex-wrap: wrap; gap: 4px 12px; font-size: 11px; color: var(--ded-attend-muted); }
  .ded-attend-key li { display: flex; align-items: center; gap: 6px; }
  .ded-attend-key i { width: 14px; border-top: 2.2px solid var(--ded-attend-accent); }
  .ded-attend-key i[data-s="yr"] { border-top: 1.2px solid var(--ded-attend-cool); }
  .ded-attend-key i[data-s="la"] { border-top: 1.4px dashed var(--ded-attend-faint); }
  .ded-attend-trend { position: relative; min-height: 100px; }
  .ded-attend-trend svg { position: absolute; inset: 0; width: 100%; height: 100%; overflow: visible; cursor: crosshair; }
  .ded-attend-trend text { fill: var(--ded-attend-faint); font: 10px var(--ded-attend-mono); font-variant-numeric: tabular-nums; }
  .ded-attend-trend .ded-attend-g line { stroke: var(--ded-attend-line); }
  .ded-attend-yl { fill: none; stroke: var(--ded-attend-cool); stroke-width: 1; opacity: 0.4; }
  .ded-attend-sl { fill: none; stroke: var(--ded-attend-accent); stroke-width: 2.3; stroke-linejoin: round; }
  .ded-attend-draw { stroke-dasharray: 1; animation: ded-attend-draw 1200ms var(--ded-attend-ease) both 250ms; }
  .ded-attend-la { stroke: var(--ded-attend-faint); stroke-dasharray: 4 4; }
  .ded-attend-hair { stroke: var(--ded-attend-line2); opacity: 0; }
  .ded-attend-trend:hover .ded-attend-hair { opacity: 1; }
  .ded-attend-hdot { fill: var(--ded-attend-accent); stroke: var(--ded-attend-panel); stroke-width: 2; opacity: 0; }
  .ded-attend-trend:hover .ded-attend-hdot { opacity: 1; }

  /* alerts */
  .ded-attend-alerts > header > span { font: 600 11.5px var(--ded-attend-mono); color: color-mix(in oklch, var(--ded-attend-alert), white 20%); }
  .ded-attend-alist { min-height: 0; overflow: auto; margin: 0 -8px; padding: 0 2px; scrollbar-width: thin; scrollbar-color: var(--ded-attend-line2) transparent; }
  .ded-attend-alist li { animation: ded-attend-rowin 380ms var(--ded-attend-ease) both; animation-delay: calc(var(--i, 0) * 22ms); }
  .ded-attend-alist button {
    display: grid; grid-template-columns: minmax(0, 1fr) auto; grid-template-areas: "n p" "r r"; gap: 3px 8px; width: 100%;
    padding: 7px 8px; border-radius: 9px; transition: background-color 140ms;
  }
  .ded-attend-alist button:hover { background: var(--ded-attend-line); }
  .ded-attend-alist button[aria-current="true"] { background: color-mix(in oklch, var(--ded-attend-accent) 14%, transparent); box-shadow: inset 2px 0 0 var(--ded-attend-accent); }
  .ded-attend-an { grid-area: n; min-width: 0; font-weight: 600; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
  .ded-attend-an small { font-weight: 500; color: var(--ded-attend-muted); margin-left: 6px; font-family: var(--ded-attend-mono); font-size: 11px; }
  .ded-attend-ap { grid-area: p; font: 650 12px var(--ded-attend-mono); color: color-mix(in oklch, var(--ded-attend-alert), white 22%); font-variant-numeric: tabular-nums; }
  .ded-attend-chips { grid-area: r; display: flex; flex-wrap: wrap; gap: 4px; }
  .ded-attend-chip { font-size: 10.5px; font-weight: 600; padding: 1px 7px; border-radius: 99px; background: var(--ded-attend-line); color: var(--ded-attend-muted); white-space: nowrap; }
  .ded-attend-chip[data-r="severe"] { background: color-mix(in oklch, var(--ded-attend-alert) 30%, transparent); color: var(--ded-attend-ink); }
  .ded-attend-chip[data-r="monfri"] { background: color-mix(in oklch, var(--ded-attend-accent) 18%, transparent); color: color-mix(in oklch, var(--ded-attend-accent), white 30%); }
  .ded-attend-more { justify-self: start; font-size: 12px; font-weight: 600; color: var(--ded-attend-accent); padding: 4px 2px; }
  .ded-attend-more:hover { text-decoration: underline; text-underline-offset: 3px; }
  .ded-attend-none { padding: 18px 8px; color: var(--ded-attend-muted); font-size: 12px; }

  /* tables */
  .ded-attend-pv, .ded-attend-yv { display: grid; min-height: 0; }
  .ded-attend-scroll { min-height: 0; overflow: auto; margin: 0 -14px -12px; scrollbar-width: thin; scrollbar-color: var(--ded-attend-line2) transparent; }
  .ded-attend-table { width: 100%; border-collapse: separate; border-spacing: 0; font-variant-numeric: tabular-nums; }
  .ded-attend-table th { position: sticky; top: 0; z-index: 1; padding: 9px 12px; background: var(--ded-attend-panel); text-align: left; font-size: 10.5px; font-weight: 650; letter-spacing: 0.08em; text-transform: uppercase; color: var(--ded-attend-muted); border-bottom: 1px solid var(--ded-attend-line2); white-space: nowrap; }
  .ded-attend-table th:has(button) { padding: 0; }
  .ded-attend-table th button { position: relative; display: block; width: 100%; padding: 9px 12px; text-transform: inherit; letter-spacing: inherit; font-weight: inherit; text-align: inherit; }
  .ded-attend-table th[aria-sort="ascending"] button, .ded-attend-table th[aria-sort="descending"] button { color: var(--ded-attend-ink); }
  .ded-attend-table th[aria-sort="ascending"] button::after { content: " ↑"; }
  .ded-attend-table th[aria-sort="descending"] button::after { content: " ↓"; }
  .ded-attend-table .ded-attend-n { text-align: right; }
  .ded-attend-table td { padding: 8px 12px; border-bottom: 1px solid var(--ded-attend-line); white-space: nowrap; }
  .ded-attend-table td small { color: var(--ded-attend-muted); font-family: var(--ded-attend-mono); margin-left: 6px; }
  .ded-attend-ptable tbody tr { cursor: pointer; content-visibility: auto; contain-intrinsic-size: auto 37px; transition: background-color 120ms; }
  .ded-attend-ptable tbody tr:hover { background: var(--ded-attend-line); }
  .ded-attend-ptable tbody tr[aria-selected="true"] { background: color-mix(in oklch, var(--ded-attend-accent) 13%, transparent); }
  .ded-attend-low { color: color-mix(in oklch, var(--ded-attend-alert), white 22%); font-weight: 650; }
  .ded-attend-switch { display: flex; align-items: center; gap: 8px; font-size: 12px; font-weight: 600; cursor: pointer; }
  .ded-attend-switch input { appearance: none; position: relative; width: 30px; height: 18px; margin: 0; border-radius: 99px; background: var(--ded-attend-line2); cursor: pointer; transition: background-color 180ms; }
  .ded-attend-switch input::after { content: ""; position: absolute; top: 2px; left: 2px; width: 14px; height: 14px; border-radius: 50%; background: var(--ded-attend-ink); transition: translate 280ms var(--ded-attend-spring); }
  .ded-attend-switch input:checked { background: var(--ded-attend-alert); }
  .ded-attend-switch input:checked::after { translate: 12px 0; }
  .ded-attend-rate { position: relative; display: block; width: clamp(80px, 16cqi, 180px); height: 8px; border-radius: 9px; background: var(--ded-attend-line); }
  .ded-attend-rate i { position: absolute; inset: 0 auto 0 0; border-radius: inherit; background: var(--ded-attend-alert); transform-origin: left; animation: ded-attend-grow 700ms var(--ded-attend-ease) both; }
  .ded-attend-rate u { position: absolute; top: -4px; bottom: -4px; width: 2px; background: var(--ded-attend-ink); text-decoration: none; }
  .ded-attend-ratec { display: flex; align-items: center; gap: 10px; }
  .ded-attend-ratec b { font: 600 12px var(--ded-attend-mono); }
  .ded-attend-ytable td button { padding: 5px 10px; border-radius: 8px; font-size: 12px; font-weight: 600; box-shadow: inset 0 0 0 1px var(--ded-attend-line2); transition: background-color 140ms; }
  .ded-attend-ytable td button:hover { background: var(--ded-attend-line); }
  .ded-attend-ytable tfoot td { font-weight: 700; background: var(--ded-attend-panel2); border-bottom: 0; }

  /* drawer */
  .ded-attend-drawer {
    position: absolute; z-index: 6; top: 12px; right: 12px; bottom: 12px; width: min(360px, calc(100% - 24px));
    display: grid; grid-template-rows: auto auto auto auto auto minmax(0, 1fr); gap: 12px; padding: 16px;
    border-radius: 16px; background: var(--ded-attend-panel2); overflow: auto;
    box-shadow: 0 0 0 1px var(--ded-attend-line2), 0 30px 60px -20px oklch(0 0 0 / 0.7);
    opacity: 0; translate: 26px 0; visibility: hidden;
    transition: opacity 200ms var(--ded-attend-ease), translate 360ms var(--ded-attend-spring), visibility 0s linear 360ms;
  }
  .ded-attend-drawer.is-open { opacity: 1; translate: 0 0; visibility: visible; transition: opacity 200ms var(--ded-attend-ease), translate 420ms var(--ded-attend-spring), visibility 0s; }
  .ded-attend-drawer > header { display: flex; justify-content: space-between; gap: 10px; }
  .ded-attend-drawer h3 { font-size: 18px; font-weight: 720; letter-spacing: -0.02em; }
  .ded-attend-x { display: grid; place-items: center; width: 30px; height: 30px; border-radius: 8px; flex: none; }
  .ded-attend-x:hover { background: var(--ded-attend-line); }
  .ded-attend-x svg { width: 16px; height: 16px; fill: none; stroke: currentColor; stroke-width: 2; stroke-linecap: round; }
  .ded-attend-dhero { display: flex; align-items: baseline; gap: 10px; flex-wrap: wrap; }
  .ded-attend-dhero b { font-size: 34px; font-weight: 720; letter-spacing: -0.04em; font-variant-numeric: tabular-nums; }
  .ded-attend-dhero span { font-size: 11px; font-weight: 700; letter-spacing: 0.06em; text-transform: uppercase; padding: 3px 8px; border-radius: 99px; background: var(--ded-attend-line); }
  .ded-attend-dhero span[data-s="pa"] { background: color-mix(in oklch, var(--ded-attend-alert) 26%, transparent); color: color-mix(in oklch, var(--ded-attend-alert), white 30%); }
  .ded-attend-dhero span[data-s="severe"] { background: var(--ded-attend-alert); color: var(--ded-attend-bg); }
  .ded-attend-weeks { display: grid; grid-template-columns: repeat(38, minmax(0, 1fr)); align-items: end; gap: 2px; height: 52px; padding-bottom: 2px; border-bottom: 1px solid var(--ded-attend-line2); }
  .ded-attend-weeks i { display: block; height: calc(var(--v) * 10%); min-height: 2px; border-radius: 2px 2px 0 0; background: var(--ded-attend-cool); opacity: 0.35; transform-origin: bottom; animation: ded-attend-grow 520ms var(--ded-attend-ease) both; animation-delay: calc(var(--i) * 10ms); }
  .ded-attend-weeks i[data-in] { opacity: 1; }
  .ded-attend-weeks i[data-low] { background: var(--ded-attend-alert); }
  .ded-attend-reasons { display: grid; gap: 8px; }
  .ded-attend-reasons li { display: grid; gap: 1px; padding: 8px 10px; border-radius: 10px; background: var(--ded-attend-line); font-size: 12px; }
  .ded-attend-reasons li b { font-size: 12.5px; }
  .ded-attend-reasons li span { color: var(--ded-attend-muted); }
  .ded-attend-dacts { display: flex; flex-wrap: wrap; gap: 8px; }
  .ded-attend-btn {
    min-height: 34px; padding: 7px 12px; border-radius: 10px; font-size: 12.5px; font-weight: 650; box-shadow: inset 0 0 0 1px var(--ded-attend-line2);
    transition: background-color 140ms, scale 200ms var(--ded-attend-spring);
  }
  .ded-attend-btn:hover { background: var(--ded-attend-line); }
  .ded-attend-btn:active { scale: 0.96; }
  .ded-attend-primary { background: var(--ded-attend-accent); color: var(--ded-attend-bg); box-shadow: none; }
  .ded-attend-primary:hover { background: color-mix(in oklch, var(--ded-attend-accent), white 15%); }
  .ded-attend-btn[aria-pressed="true"] { background: color-mix(in oklch, var(--ded-attend-alert) 24%, transparent); box-shadow: inset 0 0 0 1px var(--ded-attend-alert); }
  .ded-attend-log { display: grid; align-content: start; gap: 6px; font-size: 12px; color: var(--ded-attend-muted); }
  .ded-attend-log li { display: flex; justify-content: space-between; gap: 10px; padding-top: 6px; border-top: 1px solid var(--ded-attend-line); transition: opacity 300ms, translate 400ms var(--ded-attend-spring); }
  @starting-style { .ded-attend-log li { opacity: 0; translate: 0 -6px; } }
