  $('[data-k="pa"]').innerHTML = pa.length + `<small>${(pa.length / vis.length * 100).toFixed(1)}%</small>`;
  $('[data-k="pan"]').innerHTML = `of ${vis.length} pupils at or below <b>${S.thr.toFixed(1)}%</b>`;
  $('[data-k="sev"]').innerHTML = sev.length + `<small>${(sev.length / vis.length * 100).toFixed(1)}%</small>`;
  $('[data-k="sevn"]').textContent = 'attending half of sessions or less';
  $('[data-k="un"]').innerHTML = (abs ? un / abs * 100 : 0).toFixed(1) + '<small>%</small>';
  $('[data-k="unn"]').textContent = `${un.toLocaleString('en-GB')} of ${abs.toLocaleString('en-GB')} missed sessions`;
  $('[data-k="tabn"]').textContent = pa.length;
  $('[data-k="swarmsub"]').textContent = `${TERMS[S.term]} · ${R.length} weeks · ${vis.length} pupils · each dot is one pupil`;
  $('[data-k="alertn"]').textContent = `${pa.length} pupil${pa.length === 1 ? '' : 's'}`;
  paintAlerts(pa);
  if (S.tab === 'pupils') paintPupils();
  if (S.tab === 'years') paintYears();
}
const chips = (p, max) => p.s.rs.slice(0, max).map(r => `<span class="ded-attend-chip" data-r="${r}">${RLABEL[r]}</span>`).join('');
function paintAlerts(pa) {
  const list = pa.slice().sort((a, b) => a.s.pct - b.s.pct);
  const ol = $('.ded-attend-alist');
  const CAP = 60;
  ol.innerHTML = list.length ? list.slice(0, CAP).map((p, i) => `<li style="--i:${Math.min(i, 14)}"><button type="button" data-p="${p.id}"${S.sel === p ? ' aria-current="true"' : ''}>
    <span class="ded-attend-an">${p.name}<small>${p.form}</small></span><span class="ded-attend-ap">${pct1(p.s.pct)}</span>
    <span class="ded-attend-chips">${chips(p, 2) || '<span class="ded-attend-chip">No pattern flagged</span>'}</span></button></li>`).join('')
    + (list.length > CAP ? `<li class="ded-attend-none">${list.length - CAP} more in the pupil list</li>` : '')
    : `<li class="ded-attend-none">No pupil in the selected years is at or below ${S.thr.toFixed(1)}% this ${S.term === 'all' ? 'year' : 'term'}.</li>`;
}
const ptbody = $('.ded-attend-ptable tbody');
function paintPupils() {
  let list = visible();
  if (S.onlyLow) list = list.filter(isPA);
  const k = S.sort, dir = S.dir;
  const v = p => k === 'name' ? p.name : k === 'y' ? p.y * 1000 + p.s.pct : k === 'abs' ? p.s.abs : k === 'un' ? p.s.un : p.s.pct;
  list.sort((a, b) => { const x = v(a), y = v(b); return (typeof x === 'string' ? x.localeCompare(y) : x - y) * dir || a.id - b.id; });
  $('[data-k="ptitle"]').textContent = S.onlyLow ? `${list.length} pupils at or below ${S.thr.toFixed(1)}% · ${TERMS[S.term]}` : `All ${list.length} pupils · ${TERMS[S.term]}`;
  ptbody.innerHTML = list.map(p => `<tr data-p="${p.id}" tabindex="-1" aria-selected="${S.sel === p}"><td><b>${p.name}</b><small>${p.form}</small></td><td>Y${p.y}</td>
    <td class="ded-attend-n${isPA(p) ? ' ded-attend-low' : ''}">${pct1(p.s.pct)}</td><td class="ded-attend-n">${p.s.abs}</td><td class="ded-attend-n">${p.s.un}</td><td>${chips(p, 3)}</td></tr>`).join('');
  const f = ptbody.querySelector('tr'); if (f) f.tabIndex = 0;
  $$('.ded-attend-ptable th').forEach(th => { const b = th.querySelector('button'); if (b) th.setAttribute('aria-sort', b.dataset.sort === k ? (dir > 0 ? 'ascending' : 'descending') : 'none'); });
}
function paintYears() {
  const rows = YEARS.map(y => {
    const list = pupils.filter(p => p.y === y);
    let pres = 0, poss = 0; list.forEach(p => { pres += p.s.pres; poss += p.s.poss; });
    const pa = list.filter(isPA).length, sev = list.filter(p => p.s.pct <= 50).length;
    return { y, n: list.length, att: pres / poss * 100, pa, rate: pa / list.length * 100, sev };
  });
  const max = Math.max(40, ...rows.map(r => r.rate));
  const tot = rows.reduce((s, r) => ({ n: s.n + r.n, pa: s.pa + r.pa, sev: s.sev + r.sev }), { n: 0, pa: 0, sev: 0 });
  let pres = 0, poss = 0; pupils.forEach(p => { pres += p.s.pres; poss += p.s.poss; });
  $('.ded-attend-ytable tbody').innerHTML = rows.map((r, i) => `<tr><td><b>Year ${r.y}</b></td><td class="ded-attend-n">${r.n}</td><td class="ded-attend-n">${pct1(r.att)}</td><td class="ded-attend-n">${r.pa}</td>
    <td class="ded-attend-ratec"><span class="ded-attend-rate" title="${r.rate.toFixed(1)}% persistently absent"><i style="width:${(r.rate / max * 100).toFixed(1)}%;animation-delay:${i * 60}ms"></i><u style="left:${(LA_PA / max * 100).toFixed(1)}%"></u></span><b>${r.rate.toFixed(1)}%</b></td>
    <td class="ded-attend-n">${r.sev}</td><td><button type="button" data-showy="${r.y}">Show on swarm</button></td></tr>`).join('');
  let tf = $('.ded-attend-ytable tfoot');
  if (!tf) { tf = document.createElement('tfoot'); $('.ded-attend-ytable').appendChild(tf); }
  tf.innerHTML = `<tr><td>School</td><td class="ded-attend-n">${tot.n}</td><td class="ded-attend-n">${pct1(pres / poss * 100)}</td><td class="ded-attend-n">${tot.pa}</td><td>${(tot.pa / tot.n * 100).toFixed(1)}%</td><td class="ded-attend-n">${tot.sev}</td><td></td></tr>`;
}

/* ---------------- weekly trend (SVG) ---------------- */
const tWrap = $('.ded-attend-trend'), tsv = tWrap.querySelector('svg'), ttip = $('.ded-attend-ttip');
let tgeo = null, trendDrawn = false;
function paintTrend() {
  const Wd = tWrap.clientWidth, Hd = tWrap.clientHeight;
  if (Wd < 40 || Hd < 40) return;
  tsv.setAttribute('viewBox', `0 0 ${Wd} ${Hd}`); tsv.innerHTML = '';
  const m = { l: 36, r: 10, t: 8, b: 18 };
  const ys = YEARS.filter(y => S.years.has(y));
  const per = ys.map(y => R.map(w => { let a = 0, n = 0; pupils.forEach(p => { if (p.y === y) { a += p.att[w]; n += 10; } }); return a / n * 100; }));
  const school = R.map((w, i) => { let a = 0, n = 0; ys.forEach((y, k) => { const c = SIZE[y]; a += per[k][i] * c; n += c; }); return a / n; });
  const all = per.flat().concat(school, [LA_ATT]);
  const y0 = Math.floor(Math.min(...all) - 0.5), y1 = Math.ceil(Math.max(...all) + 0.3);
  const x = i => m.l + (R.length < 2 ? 0 : i / (R.length - 1)) * (Wd - m.l - m.r), y = v => Hd - m.b - (v - y0) / (y1 - y0) * (Hd - m.t - m.b);
  tgeo = { x, y, m, Wd, Hd, per, school, ys };
  const g = mk('g', { class: 'ded-attend-g' }, tsv);
  const stepY = (y1 - y0) > 8 ? 2 : 1;
  for (let v = y0; v <= y1; v += stepY) { mk('line', { x1: m.l, x2: Wd - m.r, y1: y(v), y2: y(v) }, g); mk('text', { x: m.l - 6, y: y(v) + 3.5, 'text-anchor': 'end' }, g).textContent = v + '%'; }
  const every = Math.max(1, Math.ceil(R.length / Math.max(2, Math.floor((Wd - m.l) / 70))));
  R.forEach((w, i) => { if (i % every === 0) mk('text', { x: x(i), y: Hd - 4, 'text-anchor': i === 0 ? 'start' : 'middle' }, tsv).textContent = fmtD(WK[w].d); });
  mk('line', { class: 'ded-attend-la', x1: m.l, x2: Wd - m.r, y1: y(LA_ATT), y2: y(LA_ATT) }, tsv);
  const path = arr => arr.map((v, i) => (i ? 'L' : 'M') + x(i).toFixed(1) + ' ' + y(v).toFixed(1)).join(' ');
  const cls = trendDrawn || reduce ? '' : ' ded-attend-draw';
  per.forEach(a => mk('path', { class: 'ded-attend-yl' + cls, d: path(a), pathLength: 1 }, tsv));
  mk('path', { class: 'ded-attend-sl' + cls, d: path(school), pathLength: 1 }, tsv);
  trendDrawn = true;
  tgeo.hair = mk('line', { class: 'ded-attend-hair', y1: m.t, y2: Hd - m.b }, tsv);
  tgeo.dot = mk('circle', { class: 'ded-attend-hdot', r: 4 }, tsv);
}
tsv.addEventListener('pointermove', ev => {
  if (!tgeo) return;
  const r = tsv.getBoundingClientRect(), n = R.length;
  const i = Math.max(0, Math.min(n - 1, Math.round((ev.clientX - r.left - tgeo.m.l) / (tgeo.Wd - tgeo.m.l - tgeo.m.r) * (n - 1))));
  const xx = tgeo.x(i);
  tgeo.hair.setAttribute('x1', xx); tgeo.hair.setAttribute('x2', xx);
  tgeo.dot.setAttribute('cx', xx); tgeo.dot.setAttribute('cy', tgeo.y(tgeo.school[i]));
  ttip.innerHTML = `<b>w/c ${fmtD(WK[R[i]].d)}</b><span><i>Whole school</i><strong>${pct1(tgeo.school[i])}</strong></span>` + tgeo.ys.map((yy, k) => `<span><i>Year ${yy}</i><strong>${pct1(tgeo.per[k][i])}</strong></span>`).join('');
  const tw = ttip.offsetWidth, th = ttip.offsetHeight;
  ttip.style.setProperty('--ded-attend-tx', (xx + 12 + tw > tgeo.Wd ? xx - 12 - tw : xx + 12) + 'px');
  ttip.style.setProperty('--ded-attend-ty', Math.max(-20, tgeo.Hd / 2 - th / 2) + 'px');
  ttip.classList.add('is-on');
});
tsv.addEventListener('pointerleave', () => ttip.classList.remove('is-on'));

/* ---------------- pupil drawer ---------------- */
const drawer = $('.ded-attend-drawer');
let opener = null;
function paintDrawer() {
  const p = S.sel; if (!p) return;
  const s = p.s, st = s.pct <= 50 ? 'severe' : isPA(p) ? 'pa' : 'ok';
  $('[data-k="dyr"]').textContent = `Year ${p.y} · tutor group ${p.form} · ${TERMS[S.term]}`;
  $('[data-k="dname"]').textContent = p.name;
  $('[data-k="dpct"]').textContent = pct1(s.pct);
  const b = $('[data-k="dbadge"]'); b.dataset.s = st; b.textContent = st === 'severe' ? 'Severe absence' : st === 'pa' ? 'Persistent absence' : 'Above threshold';
  const inR = new Set(R);
  $('.ded-attend-weeks').innerHTML = WK.map((w, i) => `<i style="--v:${p.att[i]};--i:${i}"${inR.has(i) ? ' data-in' : ''}${p.att[i] < 9 ? ' data-low' : ''} title="w/c ${fmtD(w.d)}: ${p.att[i]} of 10 sessions"></i>`).join('');
  $('.ded-attend-reasons').innerHTML = s.rs.length ? s.rs.map(r => `<li><b>${RLABEL[r]}</b><span>${rText(r, s)}</span></li>`).join('') : `<li><b>No pattern flagged</b><span>${s.abs} sessions missed, ${s.un} of them unauthorised</span></li>`;
  const ref = $('[data-act="refer"]');
  ref.setAttribute('aria-pressed', p.referred); ref.textContent = p.referred ? 'Referred to attendance officer' : 'Refer to attendance officer';
  $('.ded-attend-log').innerHTML = p.log.length ? p.log.map(l => `<li><b>${l.msg}</b><time>${l.t}</time></li>`).join('') : '<li><span>No contact logged yet</span></li>';
}
function openPupil(p, from) {
  S.sel = p; opener = from || null;
  drawer.inert = false; drawer.classList.add('is-open');
  paintDrawer(); draw();
  $$('.ded-attend-alist button[data-p]').forEach(b => b.dataset.p == p.id ? b.setAttribute('aria-current', 'true') : b.removeAttribute('aria-current'));
  $$('.ded-attend-ptable tbody tr').forEach(tr => tr.setAttribute('aria-selected', String(tr.dataset.p == p.id)));
  $('.ded-attend-x').focus({ preventScroll: true });
}
function closePupil() {
  if (!S.sel) return;
  S.sel = null; drawer.classList.remove('is-open'); drawer.inert = true; draw();
  $$('.ded-attend-alist button[aria-current]').forEach(b => b.removeAttribute('aria-current'));
  $$('.ded-attend-ptable tbody tr[aria-selected="true"]').forEach(tr => tr.setAttribute('aria-selected', 'false'));
  if (opener && opener.isConnected) opener.focus({ preventScroll: true });
}
$('.ded-attend-x').addEventListener('click', closePupil);
const stamp = () => { const d = new Date(); return String(d.getHours()).padStart(2, '0') + ':' + String(d.getMinutes()).padStart(2, '0'); };
$('[data-act="call"]').addEventListener('click', () => {
  const p = S.sel; if (!p) return;
  p.log.unshift({ msg: 'Call home logged', t: 'Today ' + stamp() });
  paintDrawer(); toast(`Call home logged for ${p.name}`);
});
$('[data-act="refer"]').addEventListener('click', () => {
  const p = S.sel; if (!p) return;
  p.referred = !p.referred;
  p.log.unshift({ msg: p.referred ? 'Referred to attendance officer' : 'Referral withdrawn', t: 'Today ' + stamp() });
  paintDrawer(); toast(p.referred ? `${p.name} referred to the attendance officer` : `Referral for ${p.name} withdrawn`);
});

/* ---------------- controls ---------------- */
$('.ded-attend-alist').addEventListener('click', ev => { const b = ev.target.closest('button[data-p]'); if (!b) return; const p = pupils[+b.dataset.p]; S.sel === p ? closePupil() : openPupil(p, b); });
ptbody.addEventListener('click', ev => { const tr = ev.target.closest('tr[data-p]'); if (!tr) return; const p = pupils[+tr.dataset.p]; S.sel === p ? closePupil() : openPupil(p, tr); });
ptbody.addEventListener('keydown', ev => {
  const tr = ev.target.closest('tr[data-p]'); if (!tr) return;
  if (ev.key === 'Enter' || ev.key === ' ') { ev.preventDefault(); openPupil(pupils[+tr.dataset.p], tr); }
  const sib = ev.key === 'ArrowDown' ? tr.nextElementSibling : ev.key === 'ArrowUp' ? tr.previousElementSibling : null;
  if (sib) { ev.preventDefault(); tr.tabIndex = -1; sib.tabIndex = 0; sib.focus(); }
});
$('.ded-attend-ptable thead').addEventListener('click', ev => {
  const b = ev.target.closest('button[data-sort]'); if (!b) return;
  const k = b.dataset.sort;
  if (S.sort === k) S.dir = -S.dir; else { S.sort = k; S.dir = k === 'abs' || k === 'un' ? -1 : 1; }
  paintPupils();
});
$('.ded-attend-switch input').addEventListener('change', ev => { S.onlyLow = ev.target.checked; paintPupils(); });
$('.ded-attend-ytable').addEventListener('click', ev => {
  const b = ev.target.closest('button[data-showy]'); if (!b) return;
  S.years = new Set([+b.dataset.showy]); syncYears(); setTab('overview'); relayout();
  toast(`Showing Year ${b.dataset.showy} on the swarm`);
});
$('.ded-attend-more').addEventListener('click', () => setTab('pupils'));

function syncYears() {
  $$('.ded-attend-years button').forEach(b => {
    const on = S.years.has(+b.dataset.y);
    b.setAttribute('aria-pressed', on);
    const last = on && S.years.size === 1;
    if (last) { b.setAttribute('aria-disabled', 'true'); b.title = 'At least one year group stays on the swarm'; }
    else { b.removeAttribute('aria-disabled'); b.title = on ? `Hide Year ${b.dataset.y}` : `Show Year ${b.dataset.y}`; }
  });
}
$('.ded-attend-years').addEventListener('click', ev => {
  const b = ev.target.closest('button[data-y]'); if (!b || b.getAttribute('aria-disabled') === 'true') return;
  const y = +b.dataset.y;
  S.years.has(y) ? S.years.delete(y) : S.years.add(y);
  syncYears(); relayout();
});
function relayout() {
  if (S.sel && !S.years.has(S.sel.y)) closePupil();
  if (size()) layout(false);
  placeHandle(); paintNumbers(); paintTrend();
}

const tabs = $$('.ded-attend-tabs [role="tab"]');
function setTab(t) {
  S.tab = t;
  tabs.forEach(b => { const on = b.dataset.tab === t; b.setAttribute('aria-selected', on); b.tabIndex = on ? 0 : -1; });
  const idx = ['overview', 'pupils', 'years'].indexOf(t);
  $$('.ded-attend-view').forEach((v, i) => { v.hidden = i !== idx; });
  if (t === 'pupils') paintPupils();
  if (t === 'years') paintYears();
  if (t === 'overview') { if (size()) { layout(false); } paintTrend(); placeHandle(); }
}
$('.ded-attend-tabs').addEventListener('click', ev => { const b = ev.target.closest('[role="tab"]'); if (b && b.getAttribute('aria-selected') !== 'true') setTab(b.dataset.tab); });
$('.ded-attend-tabs').addEventListener('keydown', ev => {
  const i = tabs.indexOf(document.activeElement); if (i < 0) return;
  const d = ev.key === 'ArrowRight' ? 1 : ev.key === 'ArrowLeft' ? -1 : 0; if (!d) return;
  ev.preventDefault(); const b = tabs[(i + d + tabs.length) % tabs.length]; b.focus(); setTab(b.dataset.tab);
});
const terms = $$('.ded-attend-terms button');
const pickTerm = b => {
  terms.forEach(x => { const on = x === b; x.setAttribute('aria-checked', on); x.tabIndex = on ? 0 : -1; });
  S.term = b.dataset.term; computeStats(); relayout();
  if (S.sel) paintDrawer();
};
$('.ded-attend-terms').addEventListener('click', ev => { const b = ev.target.closest('button[data-term]'); if (b && b.getAttribute('aria-checked') !== 'true') pickTerm(b); });
$('.ded-attend-terms').addEventListener('keydown', ev => {
  const i = terms.indexOf(document.activeElement); if (i < 0) return;
  const d = ev.key === 'ArrowRight' || ev.key === 'ArrowDown' ? 1 : ev.key === 'ArrowLeft' || ev.key === 'ArrowUp' ? -1 : 0; if (!d) return;
  ev.preventDefault(); const b = terms[(i + d + terms.length) % terms.length]; b.focus(); pickTerm(b);
});
root.addEventListener('keydown', ev => { if (ev.key === 'Escape' && S.sel) { ev.preventDefault(); closePupil(); } });

/* ---------------- mount ---------------- */
readColors();
computeStats();
syncYears();
let mounted = false;
const ro = new ResizeObserver(es => {
  if (!root.isConnected) return void ro.disconnect();
  es.forEach(e => {
    if (e.target === wrap) {
      if (!size()) return;
      if (!mounted) { mounted = true; layout(true); } else layout(false);
      placeHandle();
    } else paintTrend();
  });
});
ro.observe(wrap); ro.observe(tWrap);
new IntersectionObserver(es => { onScreen = es[es.length - 1].isIntersecting; }).observe(root);
paintNumbers();

css:
@keyframes ded-grades-in { from { opacity: 0; translate: 0 8px; } }
@keyframes ded-grades-rise { from { opacity: 0; translate: 0 18px; } }
@keyframes ded-grades-grow { from { scale: 0 1; } }
@keyframes ded-grades-menu { from { opacity: 0; translate: 0 -6px; scale: 0.98; } }

.ded-grades {
  /* re-theme with these five */
  --ded-grades-bg: oklch(0.185 0.014 165);
  --ded-grades-ink: oklch(0.95 0.012 120);
  --ded-grades-accent: oklch(0.89 0.17 122);
  --ded-grades-lo: oklch(0.63 0.16 20);
  --ded-grades-hi: oklch(0.8 0.13 165);
  /* grade ramp, mixed in oklch so the hue walks rose → amber → lime → green */
  --ded-grades-gU: color-mix(in oklch, var(--ded-grades-ink) 20%, var(--ded-grades-bg));
  --ded-grades-g3: var(--ded-grades-lo);
  --ded-grades-g4: color-mix(in oklch, var(--ded-grades-hi) 16.7%, var(--ded-grades-lo));
  --ded-grades-g5: color-mix(in oklch, var(--ded-grades-hi) 33.3%, var(--ded-grades-lo));
  --ded-grades-g6: color-mix(in oklch, var(--ded-grades-hi) 50%, var(--ded-grades-lo));
  --ded-grades-g7: color-mix(in oklch, var(--ded-grades-hi) 66.7%, var(--ded-grades-lo));
  --ded-grades-g8: color-mix(in oklch, var(--ded-grades-hi) 83.3%, var(--ded-grades-lo));
  --ded-grades-g9: var(--ded-grades-hi);
  --ded-grades-panel: color-mix(in oklch, var(--ded-grades-bg), var(--ded-grades-ink) 4.5%);
  --ded-grades-panel2: color-mix(in oklch, var(--ded-grades-bg), var(--ded-grades-ink) 9%);
  --ded-grades-line: color-mix(in oklch, var(--ded-grades-ink) 9%, transparent);
  --ded-grades-line2: color-mix(in oklch, var(--ded-grades-ink) 18%, transparent);
  --ded-grades-muted: color-mix(in oklch, var(--ded-grades-ink) 60%, var(--ded-grades-bg));
  --ded-grades-faint: color-mix(in oklch, var(--ded-grades-ink) 38%, var(--ded-grades-bg));
  --ded-grades-ease: cubic-bezier(0.2, 0.85, 0.25, 1);
  --ded-grades-spring: linear(0, 0.05, 0.19 7%, 0.62 17%, 0.96 26%, 1.07 33%, 1.06 40%, 1.01 51%, 0.995 63%, 1);
  --ded-grades-mono: ui-monospace, Menlo, Consolas, monospace;

  width: 100%;
  height: var(--ded-grades-h, 680px);
  container-type: inline-size;
  position: relative;
  overflow: hidden;
  box-sizing: border-box;
  border-radius: 16px;
  background: var(--ded-grades-bg);
  color: var(--ded-grades-ink);
  font: 400 13px/1.45 system-ui, -apple-system, "Segoe UI", Roboto, sans-serif;
  color-scheme: dark;
  accent-color: var(--ded-grades-accent);

  & *, & *::before, & *::after { box-sizing: border-box; }
  & button { font: inherit; color: inherit; background: none; border: 0; padding: 0; margin: 0; cursor: pointer; text-align: inherit; }
  & :focus-visible { outline: 2px solid var(--ded-grades-accent); outline-offset: 2px; border-radius: 6px; }
  & h2, & h3 { margin: 0; text-wrap: balance; }
  & p { margin: 0; text-wrap: pretty; }
  & ol, & ul { margin: 0; padding: 0; list-style: none; }
  & svg { display: block; }
  & [hidden] { display: none !important; }
  & .ded-grades-eyebrow { font-size: 10.5px; font-weight: 650; letter-spacing: 0.12em; text-transform: uppercase; color: var(--ded-grades-muted); }

  .ded-grades-app { display: grid; height: 100%; grid-template-columns: 76px minmax(0, 1fr); grid-template-areas: "rail main"; }

  /* ---------- rail ---------- */
  .ded-grades-rail { grid-area: rail; display: flex; flex-direction: column; align-items: center; gap: 6px; padding: 14px 8px; border-right: 1px solid var(--ded-grades-line); }
  .ded-grades-logo { display: grid; place-items: center; width: 40px; height: 40px; margin-bottom: 10px; border-radius: 12px; background: var(--ded-grades-accent); }
  .ded-grades-logo svg { width: 22px; height: 22px; fill: none; stroke: var(--ded-grades-bg); stroke-width: 2.2; stroke-linecap: round; stroke-linejoin: round; }
  .ded-grades-rail button {
