const blines = S.b.map(() => mk('line', { class: 'ded-grades-bline' }, linesG));
let geo = null, drawn = false;
function ridgeGeo() {
  const W = svg.clientWidth, H = svg.clientHeight;
  if (W < 60 || H < 60) return null;
  const m = { l: Math.min(70, W * 0.16), r: 10, t: 4, b: 20 };
