      <span class="ded-grades-gap" style="--ded-grades-gc:var(--ded-grades-g${S.key})"><span class="ded-grades-track"><i style="width:${(gap / S.within * 100).toFixed(1)}%"></i></span><span>${gap} mark${gap === 1 ? '' : 's'} below grade ${S.key}</span></span>
