  }).join('') : `<li class="ded-grades-empty">No one is within ${S.within} marks of grade ${S.key} with these boundaries.</li>`;
  paintGroup();
}
function paintGroup() {
  const n = S.group.size, btn = $('[data-act="export"]');
  const classes = new Set(ALL.filter(s => S.group.has(s.id)).map(s => s.c.code));
  $('[data-k="group"]').textContent = n ? `Intervention group: ${n} student${n === 1 ? '' : 's'} across ${classes.size} class${classes.size === 1 ? '' : 'es'}` : 'Intervention group is empty';
  btn.disabled = !n; btn.title = n ? 'Email each class teacher the names from their class' : 'Add at least one student to the group first';
}
$('.ded-grades-blist').addEventListener('click', ev => {
  const b = ev.target.closest('button[data-s]'); if (!b) return;
  const id = +b.dataset.s, on = !S.group.has(id);
