  const classes = new Set(list.map(s => s.c.teacher));
  toast(`Sent ${list.length} name${list.length === 1 ? '' : 's'} to ${classes.size} class teacher${classes.size === 1 ? '' : 's'}`);
});
const within = $('.ded-grades-within input');
within.addEventListener('input', () => { const v = parseInt(within.value, 10); if (v >= 1 && v <= 15) { S.within = v; paintBorder(); } });

/* ---------------- re-grade everything ---------------- */
function regrade() {
