@keyframes ded-funnel-in { from { opacity: 0; translate: 0 8px; } }
@keyframes ded-funnel-draw { from { stroke-dashoffset: 1; } to { stroke-dashoffset: 0; } }
@keyframes ded-funnel-bar { from { scale: 1 0; } }
@keyframes ded-funnel-fade { from { opacity: 0; } }
@keyframes ded-funnel-callout { from { opacity: 0; translate: 0 6px; } }

.ded-funnel {
  /* re-theme with these four */
  --ded-funnel-paper: oklch(0.985 0.008 170);
  --ded-funnel-ink: oklch(0.28 0.035 205);
  --ded-funnel-accent: oklch(0.65 0.17 32);
  --ded-funnel-c1: oklch(0.57 0.1 200);
  /* derived */
  --ded-funnel-c0: var(--ded-funnel-accent);
  --ded-funnel-c2: oklch(0.74 0.14 82);
  --ded-funnel-card: color-mix(in oklch, var(--ded-funnel-paper), white 75%);
  --ded-funnel-sunk: color-mix(in oklch, var(--ded-funnel-paper), var(--ded-funnel-ink) 4.5%);
  --ded-funnel-line: color-mix(in oklch, var(--ded-funnel-ink) 11%, transparent);
  --ded-funnel-line2: color-mix(in oklch, var(--ded-funnel-ink) 22%, transparent);
  --ded-funnel-muted: color-mix(in oklch, var(--ded-funnel-ink) 64%, var(--ded-funnel-paper));
  --ded-funnel-faint: color-mix(in oklch, var(--ded-funnel-ink) 42%, var(--ded-funnel-paper));
  --ded-funnel-ease: cubic-bezier(0.2, 0.8, 0.2, 1);
  --ded-funnel-spring: linear(0, 0.05, 0.2 7%, 0.63 17%, 0.96 26%, 1.07 33%, 1.06 40%, 1.01 51%, 0.995 63%, 1);
  --ded-funnel-mono: ui-monospace, Menlo, Consolas, monospace;

  width: 100%;
  height: var(--ded-funnel-h, 680px);
  container-type: inline-size;
  position: relative;
  overflow: hidden;
  box-sizing: border-box;
  display: grid;
  grid-template-rows: auto auto minmax(0, 1fr);
  border-radius: 16px;
  background: var(--ded-funnel-paper);
  color: var(--ded-funnel-ink);
  font: 400 13px/1.45 system-ui, -apple-system, "Segoe UI", Roboto, sans-serif;
  accent-color: var(--ded-funnel-accent);
  box-shadow: inset 0 0 0 1px var(--ded-funnel-line);

  & *, & *::before, & *::after { box-sizing: border-box; }
  & button { font: inherit; color: inherit; background: none; border: 0; padding: 0; margin: 0; cursor: pointer; text-align: inherit; }
  & button[aria-disabled="true"] { cursor: not-allowed; }
  & :focus-visible { outline: 2px solid var(--ded-funnel-accent); outline-offset: 2px; border-radius: 6px; }
  & h2, & h3, & h4 { margin: 0; text-wrap: balance; }
  & p { margin: 0; text-wrap: pretty; }
  & ul, & ol, & dl, & dd { margin: 0; padding: 0; list-style: none; }
  & svg { display: block; }
  & [hidden] { display: none !important; }
  & .ded-funnel-eyebrow { font-size: 10.5px; font-weight: 650; letter-spacing: 0.11em; text-transform: uppercase; color: var(--ded-funnel-muted); }

  /* ---------- header ---------- */
  .ded-funnel-top { display: flex; align-items: center; gap: 12px 22px; flex-wrap: wrap; padding: 14px 18px 12px; }
  .ded-funnel-brand { display: flex; align-items: center; gap: 10px; padding-right: 22px; border-right: 1px solid var(--ded-funnel-line); }
  .ded-funnel-brand svg { width: 32px; height: 32px; padding: 6px; border-radius: 50%; background: var(--ded-funnel-ink); fill: var(--ded-funnel-accent); stroke: var(--ded-funnel-accent); stroke-width: 1.4; stroke-linejoin: round; }
  .ded-funnel-brand span { display: grid; line-height: 1.2; }
  .ded-funnel-brand b { font-size: 13.5px; font-weight: 720; letter-spacing: -0.01em; }
  .ded-funnel-brand small { font-size: 11px; color: var(--ded-funnel-muted); }
  .ded-funnel-course { min-width: 0; margin-right: auto; }
  .ded-funnel-course h2 { font-size: clamp(16px, 0.9rem + 0.6cqi, 21px); font-weight: 740; letter-spacing: -0.025em; line-height: 1.15; }
  .ded-funnel-tabs { display: flex; gap: 2px; padding: 3px; border-radius: 99px; background: var(--ded-funnel-sunk); box-shadow: inset 0 0 0 1px var(--ded-funnel-line); }
  .ded-funnel-tabs button { padding: 6px 15px; border-radius: 99px; font-weight: 650; color: var(--ded-funnel-muted); transition: background-color 180ms, color 180ms, box-shadow 180ms; }
  .ded-funnel-tabs button:hover { color: var(--ded-funnel-ink); }
  .ded-funnel-tabs button[aria-selected="true"] { background: var(--ded-funnel-ink); color: var(--ded-funnel-paper); }

  .ded-funnel-filters { display: flex; flex-wrap: wrap; align-items: center; gap: 8px 14px; padding: 0 18px 12px; border-bottom: 1px solid var(--ded-funnel-line); }
  .ded-funnel-flabel { font-size: 10.5px; font-weight: 650; letter-spacing: 0.1em; text-transform: uppercase; color: var(--ded-funnel-muted); margin-right: 2px; }
  .ded-funnel-cohorts { display: flex; flex-wrap: wrap; align-items: center; gap: 6px; margin-right: auto; }
  .ded-funnel-cohorts button {
    display: inline-flex; align-items: center; gap: 7px; padding: 5px 11px 5px 9px; border-radius: 99px; font-size: 12.5px; font-weight: 600;
    background: var(--ded-funnel-card); box-shadow: inset 0 0 0 1px var(--ded-funnel-line2); transition: background-color 160ms, box-shadow 160ms, opacity 160ms;
  }
  .ded-funnel-cohorts button i { width: 10px; height: 10px; border-radius: 50%; box-shadow: inset 0 0 0 2px var(--ded-funnel-cc); transition: background-color 160ms; }
  .ded-funnel-cohorts button[aria-pressed="true"] { background: color-mix(in oklch, var(--ded-funnel-cc) 14%, var(--ded-funnel-card)); box-shadow: inset 0 0 0 1px color-mix(in oklch, var(--ded-funnel-cc) 60%, transparent); }
  .ded-funnel-cohorts button[aria-pressed="true"] i { background: var(--ded-funnel-cc); }
  .ded-funnel-cohorts button[aria-pressed="false"] { color: var(--ded-funnel-muted); }
  .ded-funnel-cohorts button[aria-disabled="true"] { opacity: 0.75; }
  .ded-funnel-seg { display: inline-flex; padding: 3px; gap: 2px; border-radius: 10px; background: var(--ded-funnel-sunk); box-shadow: inset 0 0 0 1px var(--ded-funnel-line); }
  .ded-funnel-seg button { padding: 4px 10px; border-radius: 7px; font-size: 12px; font-weight: 600; color: var(--ded-funnel-muted); transition: background-color 160ms, color 160ms; }
  .ded-funnel-seg button:hover { color: var(--ded-funnel-ink); }
  .ded-funnel-seg button[aria-checked="true"] { background: var(--ded-funnel-card); color: var(--ded-funnel-ink); box-shadow: 0 1px 2px var(--ded-funnel-line2); }

  /* ---------- body ---------- */
  .ded-funnel-body { min-height: 0; display: grid; grid-template-columns: minmax(0, 1fr) clamp(260px, 27cqi, 310px); gap: 12px; padding: 12px 18px 16px; }
  .ded-funnel-views { min-height: 0; display: grid; }
  .ded-funnel-view { min-height: 0; display: grid; }
  .ded-funnel-ret { grid-template-rows: minmax(0, 1.65fr) minmax(0, 1fr); gap: 12px; }
  .ded-funnel-card { min-height: 0; display: grid; grid-template-rows: auto minmax(0, 1fr); gap: 8px; padding: 12px 14px; border-radius: 14px; background: var(--ded-funnel-card); box-shadow: inset 0 0 0 1px var(--ded-funnel-line), 0 1px 2px var(--ded-funnel-line); }
  .ded-funnel-card > header { display: flex; flex-wrap: wrap; align-items: flex-start; justify-content: space-between; gap: 6px 14px; }
  .ded-funnel-card h3 { font-size: 13.5px; font-weight: 720; letter-spacing: -0.01em; }
  .ded-funnel-card > header p { font-size: 11.5px; color: var(--ded-funnel-muted); font-variant-numeric: tabular-nums; }
  .ded-funnel-key { display: flex; flex-wrap: wrap; gap: 4px 12px; font-size: 11.5px; color: var(--ded-funnel-muted); font-variant-numeric: tabular-nums; }
  .ded-funnel-key li { display: flex; align-items: center; gap: 6px; }
  .ded-funnel-key i { width: 14px; height: 0; border-top: 2.4px solid var(--ded-funnel-cc); }
  .ded-funnel-key b { color: var(--ded-funnel-ink); font-weight: 650; }

  .ded-funnel-surv, .ded-funnel-fun { position: relative; min-height: 120px; }
  .ded-funnel-surv svg, .ded-funnel-fun svg { position: absolute; inset: 0; width: 100%; height: 100%; overflow: visible; }
  .ded-funnel-surv svg { cursor: crosshair; touch-action: pan-y; }
  .ded-funnel-card text { fill: var(--ded-funnel-faint); font: 10px var(--ded-funnel-mono); font-variant-numeric: tabular-nums; }
  .ded-funnel-grid line { stroke: var(--ded-funnel-line); }
  .ded-funnel-mod rect { fill: var(--ded-funnel-sunk); }
  .ded-funnel-card .ded-funnel-modl { fill: var(--ded-funnel-muted); font: 600 10px system-ui, sans-serif; letter-spacing: 0.04em; }
  .ded-funnel-line { fill: none; stroke: var(--ded-funnel-cc); stroke-width: 2.2; stroke-linejoin: round; transition: d 550ms var(--ded-funnel-ease); }
  .ded-funnel-area { fill: color-mix(in oklch, var(--ded-funnel-cc) 9%, transparent); transition: d 550ms var(--ded-funnel-ease); }
  .ded-funnel-enter { stroke-dasharray: 1; animation: ded-funnel-draw 1300ms var(--ded-funnel-ease) both; animation-delay: calc(200ms + var(--i) * 140ms); }
  .ded-funnel-enter-a { animation: ded-funnel-fade 900ms ease-out both 700ms; }
  .ded-funnel-sel { fill: color-mix(in oklch, var(--ded-funnel-accent) 10%, transparent); stroke: color-mix(in oklch, var(--ded-funnel-accent) 50%, transparent); stroke-dasharray: 3 3; transition: x 300ms var(--ded-funnel-ease); }
  .ded-funnel-hair { stroke: var(--ded-funnel-ink); stroke-opacity: 0.45; opacity: 0; pointer-events: none; }
  .ded-funnel-surv:hover .ded-funnel-hair { opacity: 1; }
  .ded-funnel-flag { fill: var(--ded-funnel-accent); }
  .ded-funnel-co { animation: ded-funnel-callout 500ms var(--ded-funnel-ease) both; animation-delay: calc(1300ms + var(--i) * 120ms); }
  .ded-funnel-surv.is-live .ded-funnel-co { animation-duration: 360ms; animation-delay: calc(250ms + var(--i) * 70ms); }
  .ded-funnel-co line { stroke: var(--ded-funnel-ink); stroke-width: 1; }
  .ded-funnel-co rect { fill: var(--ded-funnel-ink); }
  .ded-funnel-card .ded-funnel-co text { fill: var(--ded-funnel-paper); font: 600 10.5px system-ui, sans-serif; }
  .ded-funnel-hit { fill: transparent; }

  .ded-funnel-fbar { fill: var(--ded-funnel-ink); transform-box: fill-box; transform-origin: bottom; animation: ded-funnel-bar 700ms var(--ded-funnel-ease) both; animation-delay: calc(300ms + var(--i) * 80ms); transition: y 450ms var(--ded-funnel-ease), height 450ms var(--ded-funnel-ease); }
  .ded-funnel-fbar[data-last] { fill: var(--ded-funnel-accent); }
  .ded-funnel-fcon { fill: color-mix(in oklch, var(--ded-funnel-ink) 8%, transparent); transition: d 450ms var(--ded-funnel-ease); animation: ded-funnel-fade 600ms ease-out both 700ms; }
  .ded-funnel-card .ded-funnel-fn { fill: var(--ded-funnel-ink); font: 700 12.5px system-ui, sans-serif; font-variant-numeric: tabular-nums; }
  .ded-funnel-card .ded-funnel-fl { fill: var(--ded-funnel-muted); font: 500 10.5px system-ui, sans-serif; }
  .ded-funnel-card .ded-funnel-fc { fill: var(--ded-funnel-accent); font: 650 10.5px var(--ded-funnel-mono); }

  .ded-funnel-tip {
    position: absolute; z-index: 4; left: 0; top: 0; min-width: 170px; padding: 8px 10px; border-radius: 10px; pointer-events: none;
    background: var(--ded-funnel-ink); color: var(--ded-funnel-paper); font-size: 11.5px; line-height: 1.45; font-variant-numeric: tabular-nums;
    opacity: 0; translate: var(--ded-funnel-tx, 0) var(--ded-funnel-ty, 0); transition: opacity 120ms;
    box-shadow: 0 12px 26px -12px color-mix(in oklch, var(--ded-funnel-ink) 80%, transparent);
  }
  .ded-funnel-tip.is-on { opacity: 1; }
  .ded-funnel-tip b { display: block; font-size: 12px; margin-bottom: 2px; }
  .ded-funnel-tip span { display: flex; align-items: center; gap: 8px; }
  .ded-funnel-tip span i { width: 8px; height: 8px; border-radius: 50%; background: var(--ded-funnel-cc); }
  .ded-funnel-tip span em { font-style: normal; opacity: 0.75; margin-right: auto; }

  /* table */
  .ded-funnel-scroll { min-height: 0; overflow: auto; margin: 0 -14px -12px; scrollbar-width: thin; scrollbar-color: var(--ded-funnel-line2) transparent; }
  .ded-funnel-table { width: 100%; border-collapse: separate; border-spacing: 0; font-variant-numeric: tabular-nums; }
  .ded-funnel-table th { position: sticky; top: 0; z-index: 1; padding: 0; background: var(--ded-funnel-card); text-align: left; border-bottom: 1px solid var(--ded-funnel-line2); }
  .ded-funnel-table th button { display: block; width: 100%; padding: 9px 12px; font-size: 10.5px; font-weight: 650; letter-spacing: 0.07em; text-transform: uppercase; color: var(--ded-funnel-muted); text-align: inherit; white-space: nowrap; }
  .ded-funnel-table th[aria-sort="ascending"] button, .ded-funnel-table th[aria-sort="descending"] button { color: var(--ded-funnel-ink); }
  .ded-funnel-table th[aria-sort="ascending"] button::after { content: " ↑"; }
  .ded-funnel-table th[aria-sort="descending"] button::after { content: " ↓"; }
  .ded-funnel-table .ded-funnel-n { text-align: right; }
  .ded-funnel-table td { padding: 8px 12px; border-bottom: 1px solid var(--ded-funnel-line); white-space: nowrap; }
  .ded-funnel-table td small { display: block; color: var(--ded-funnel-muted); font-size: 11px; }
  .ded-funnel-table tbody tr { cursor: pointer; transition: background-color 120ms; }
  .ded-funnel-table tbody tr:hover { background: var(--ded-funnel-sunk); }
  .ded-funnel-table tbody tr[aria-selected="true"] { background: color-mix(in oklch, var(--ded-funnel-accent) 10%, var(--ded-funnel-card)); box-shadow: inset 3px 0 0 var(--ded-funnel-accent); }
  .ded-funnel-dropc { display: inline-flex; align-items: center; justify-content: flex-end; gap: 8px; }
  .ded-funnel-dropc i { width: calc(var(--v) * 3px); max-width: 60px; height: 6px; border-radius: 4px; background: var(--ded-funnel-accent); opacity: calc(0.35 + var(--v) / 25); }
  .ded-funnel-flagm { display: inline-block; width: 7px; height: 7px; margin-left: 6px; border-radius: 2px; background: var(--ded-funnel-accent); rotate: 45deg; }

  /* detail */
  .ded-funnel-detail { grid-template-rows: auto minmax(0, 1fr) auto; }
  .ded-funnel-detail h3 { font-size: 15px; line-height: 1.25; }
  .ded-funnel-step { display: flex; gap: 4px; }
  .ded-funnel-step button { display: grid; place-items: center; width: 28px; height: 28px; border-radius: 8px; box-shadow: inset 0 0 0 1px var(--ded-funnel-line2); transition: background-color 140ms; }
  .ded-funnel-step button:hover:not(:disabled) { background: var(--ded-funnel-sunk); }
  .ded-funnel-step button:disabled { opacity: 0.35; cursor: not-allowed; }
  .ded-funnel-step svg { width: 15px; height: 15px; fill: none; stroke: currentColor; stroke-width: 2; stroke-linecap: round; stroke-linejoin: round; }
  .ded-funnel-dbody { min-height: 0; overflow: auto; display: grid; align-content: start; gap: 12px; scrollbar-width: thin; scrollbar-color: var(--ded-funnel-line2) transparent; }
  .ded-funnel-dbody > * { animation: ded-funnel-in 380ms var(--ded-funnel-ease) both; }
  .ded-funnel-dbody > :nth-child(2) { animation-delay: 50ms; } .ded-funnel-dbody > :nth-child(3) { animation-delay: 100ms; } .ded-funnel-dbody > :nth-child(4) { animation-delay: 150ms; }
  .ded-funnel-dstats { display: grid; grid-template-columns: repeat(2, minmax(0, 1fr)); gap: 6px; }
  .ded-funnel-dstats div { padding: 8px 10px; border-radius: 10px; background: var(--ded-funnel-sunk); }
