      const tc = fRefs.c[i - 1]; tc.setAttribute('x', slot * i); tc.setAttribute('y', Math.max(y(v), y(vals[i - 1])) / 2 + (H - m.b) / 2);
      tc.textContent = (v / vals[i - 1] * 100).toFixed(0) + '%';
    }
  });
  $('[data-k="funsub"]').textContent = `${(a.passed / a.enrolled * 100).toFixed(1)}% of enrolled learners passed the final assessment`;
}
fSvg.addEventListener('pointermove', ev => {
  if (!fg) return;
  const r = fSvg.getBoundingClientRect(), i = clamp(Math.floor((ev.clientX - r.left) / fg.slot), 0, STAGES.length - 1), v = fg.vals[i];
  fTip.innerHTML = `<b>${STAGES[i]}</b><span><em>Learners</em>${fmt(v)}</span><span><em>Of enrolled</em>${(v / fg.vals[0] * 100).toFixed(1)}%</span>${i ? `<span><em>Of previous stage</em>${(v / fg.vals[i - 1] * 100).toFixed(1)}%</span>` : ''}`;
  placeTip(fTip, fBox, fg.slot * (i + 0.5) + fg.bw / 2, ev.clientY - r.top);
});
fSvg.addEventListener('pointerleave', () => fTip.classList.remove('is-on'));

/* ---------------- lessons table ---------------- */
const tbody = $('.ded-funnel-table tbody');
function lessonRows() {
  const a = agg(selC());
  return L.map((ls, l) => ({ ls, l, reach: a.act[l], drop: a.act[l] ? (a.act[l] - a.act[l + 1]) / a.act[l] * 100 : 0, len: ls.len, watch: ls.watch, quiz: ls.quiz, i: l }));
}
function paintTable() {
  const rows = lessonRows(), k = S.sort, dir = S.dir;
  rows.sort((p, q) => (p[k] - q[k]) * dir || p.l - q.l);
  tbody.innerHTML = rows.map(r => `<tr data-l="${r.l}" tabindex="${r.l === S.sel ? 0 : -1}" aria-selected="${r.l === S.sel}">
    <td><b>L${r.l + 1} · ${r.ls.t}</b>${S.flags.has(r.l) ? '<span class="ded-funnel-flagm" title="Flagged for redesign"></span>' : ''}<small>${MODS[r.ls.mod]}</small></td>
    <td class="ded-funnel-n">${r.len} min</td><td class="ded-funnel-n">${fmt(r.reach)}</td>
    <td class="ded-funnel-n"><span class="ded-funnel-dropc"><i style="--v:${r.drop.toFixed(1)}"></i>${r.drop.toFixed(1)}%</span></td>
    <td class="ded-funnel-n">${r.watch}%</td><td class="ded-funnel-n">${r.quiz}%</td></tr>`).join('');
  if (!tbody.querySelector('[tabindex="0"]') && tbody.firstElementChild) tbody.firstElementChild.tabIndex = 0;
  $$('.ded-funnel-table th').forEach(th => { const b = th.querySelector('button'); th.setAttribute('aria-sort', b.dataset.sort === k ? (dir > 0 ? 'ascending' : 'descending') : 'none'); });
}
$('.ded-funnel-table thead').addEventListener('click', ev => {
  const b = ev.target.closest('button[data-sort]'); if (!b) return;
  const k = b.dataset.sort;
  if (S.sort === k) S.dir = -S.dir; else { S.sort = k; S.dir = k === 'i' ? 1 : -1; }
  paintTable();
});
tbody.addEventListener('click', ev => { const tr = ev.target.closest('tr[data-l]'); if (tr && +tr.dataset.l !== S.sel) select(+tr.dataset.l); });
tbody.addEventListener('keydown', ev => {
  const tr = ev.target.closest('tr[data-l]'); if (!tr) return;
  if (ev.key === 'Enter' || ev.key === ' ') { ev.preventDefault(); select(+tr.dataset.l); }
  const sib = ev.key === 'ArrowDown' ? tr.nextElementSibling : ev.key === 'ArrowUp' ? tr.previousElementSibling : null;
  if (sib) { ev.preventDefault(); tr.tabIndex = -1; sib.tabIndex = 0; sib.focus(); }
});

/* ---------------- lesson detail ---------------- */
function paintDetail() {
  const l = S.sel, ls = L[l], a = agg(selC());
  const reach = a.act[l], left = reach - a.act[l + 1], drop = reach ? left / reach * 100 : 0;
  $('[data-k="dmod"]').textContent = `M${ls.mod + 1} · ${MODS_SHORT[ls.mod]} · lesson ${l + 1} of 24`;
  $('[data-k="dname"]').textContent = ls.t;
  $('.ded-funnel-dstats').innerHTML = [
    ['Reached', fmt(reach), `${(reach / a.started * 100).toFixed(0)}% of starters`],
    ['Dropped here', drop.toFixed(1) + '%', `${fmt(left)} learners`],
    ['Video', ls.len + ' min', `median ${ls.watch}% watched`],
    ['Quiz pass', ls.quiz + '%', 'first attempt']
  ].map(([k, v, s]) => `<div><dt>${k}</dt><dd>${v}<small>${s}</small></dd></div>`).join('');
  const pk = ls.exit.indexOf(100);
  $('.ded-funnel-hist').innerHTML = ls.exit.map((v, i) => `<i style="--v:${v};--i:${i}"${i === pk ? ' data-peak' : ''} title="${i * 10}–${i * 10 + 10}% through: ${v === 100 ? 'most common exit point' : v + '% of peak'}"></i>`).join('');
  $('.ded-funnel-bycohort ul').innerHTML = selC().map(c => {
    const o = agg([c]), d = o.act[l] ? (o.act[l] - o.act[l + 1]) / o.act[l] * 100 : 0;
    return `<li style="--ded-funnel-cc: var(--ded-funnel-c${c})"><span>${COH[c].slice(0, 3)}</span><span class="ded-funnel-tr"><i style="width:${clamp(d * 3.5, 2, 100).toFixed(1)}%"></i></span><span>${d.toFixed(1)}%</span></li>`;
  }).join('');
  $('.ded-funnel-quote').innerHTML = `“${ls.quote[0]}”<cite>${ls.quote[1]}</cite>`;
  const fb = $('[data-act="flag"]'), on = S.flags.has(l);
  fb.setAttribute('aria-pressed', on); fb.textContent = on ? 'Flagged for redesign' : 'Flag for redesign';
  $('[data-k="flags"]').textContent = S.flags.size ? `${S.flags.size} lesson${S.flags.size === 1 ? '' : 's'} flagged` : 'No lessons flagged';
  const [pv, nx] = $$('.ded-funnel-step button');
  pv.disabled = l === 0; pv.title = l === 0 ? 'This is the first lesson' : 'Lesson ' + l;
  nx.disabled = l === 23; nx.title = l === 23 ? 'This is the last lesson' : 'Lesson ' + (l + 2);
}
function select(l) {
  S.sel = clamp(l, 0, 23);
  if (sg) selRect.style.x = sg.x(S.sel) + 'px';
  $$('tr[data-l]', tbody).forEach(tr => { const on = +tr.dataset.l === S.sel; tr.setAttribute('aria-selected', on); tr.tabIndex = on ? 0 : -1; });
  paintDetail();
}
$('.ded-funnel-step').addEventListener('click', ev => { const b = ev.target.closest('button[data-step]'); if (b && !b.disabled) select(S.sel + +b.dataset.step); });
$('[data-act="flag"]').addEventListener('click', () => {
  const l = S.sel, on = !S.flags.has(l);
  on ? S.flags.add(l) : S.flags.delete(l);
  paintDetail(); drawSurv(); if (S.tab === 'les') paintTable();
  toast(on ? `L${l + 1} “${L[l].t}” flagged for the design team` : `Flag removed from L${l + 1}`);
});

/* ---------------- filters + tabs ---------------- */
function syncCohorts() {
  $$('.ded-funnel-cohorts button').forEach(b => {
    const c = +b.dataset.c, on = S.coh.has(c);
    b.setAttribute('aria-pressed', on);
    if (on && S.coh.size === 1) { b.setAttribute('aria-disabled', 'true'); b.title = 'At least one cohort stays selected'; }
    else { b.removeAttribute('aria-disabled'); b.title = (on ? 'Hide ' : 'Show ') + COH[c]; }
  });
}
function refresh() { drawSurv(); drawFunnel(); paintDetail(); if (S.tab === 'les') paintTable(); }
$('.ded-funnel-cohorts').addEventListener('click', ev => {
  const b = ev.target.closest('button[data-c]'); if (!b || b.getAttribute('aria-disabled') === 'true') return;
  const c = +b.dataset.c; S.coh.has(c) ? S.coh.delete(c) : S.coh.add(c);
  syncCohorts(); refresh();
});
function radios(group, attr, apply) {
  const btns = $$(`button[${attr}]`, group);
  const pick = b => { btns.forEach(x => { const on = x === b; x.setAttribute('aria-checked', on); x.tabIndex = on ? 0 : -1; }); apply(b.getAttribute(attr)); };
  group.addEventListener('click', ev => { const b = ev.target.closest(`button[${attr}]`); if (b && b.getAttribute('aria-checked') !== 'true') pick(b); });
  group.addEventListener('keydown', ev => {
    const i = btns.indexOf(document.activeElement); if (i < 0) return;
    const d = ev.key === 'ArrowRight' || ev.key === 'ArrowDown' ? 1 : ev.key === 'ArrowLeft' || ev.key === 'ArrowUp' ? -1 : 0; if (!d) return;
    ev.preventDefault(); const b = btns[(i + d + btns.length) % btns.length]; b.focus(); pick(b);
  });
}
const segs = $$('.ded-funnel-filters .ded-funnel-seg');
radios(segs[0], 'data-track', v => { S.track = v; refresh(); });
radios(segs[1], 'data-metric', v => { S.metric = v; drawSurv(); });
const tabs = $$('.ded-funnel-tabs [role="tab"]');
function setTab(t) {
  S.tab = t;
  tabs.forEach(b => { const on = b.dataset.tab === t; b.setAttribute('aria-selected', on); b.tabIndex = on ? 0 : -1; });
  $('.ded-funnel-ret').hidden = t !== 'ret'; $('.ded-funnel-les').hidden = t !== 'les';
  if (t === 'les') paintTable(); else { drawSurv(); drawFunnel(); }
}
$('.ded-funnel-tabs').addEventListener('click', ev => { const b = ev.target.closest('[role="tab"]'); if (b && b.getAttribute('aria-selected') !== 'true') setTab(b.dataset.tab); });
$('.ded-funnel-tabs').addEventListener('keydown', ev => {
  const i = tabs.indexOf(document.activeElement); if (i < 0) return;
  const d = ev.key === 'ArrowRight' ? 1 : ev.key === 'ArrowLeft' ? -1 : 0; if (!d) return;
  ev.preventDefault(); const b = tabs[(i + d + tabs.length) % tabs.length]; b.focus(); setTab(b.dataset.tab);
});

/* ---------------- mount ---------------- */
syncCohorts(); paintDetail();
let rafId = 0;
const ro = new ResizeObserver(() => {
  cancelAnimationFrame(rafId);
  rafId = requestAnimationFrame(() => {
    if (!root.isConnected) return void ro.disconnect();
    if (S.tab === 'ret') { drawSurv(); drawFunnel(); }
  });
});
ro.observe(sBox); ro.observe(fBox);

css:
@property --ded-risk-s { syntax: '<number>'; inherits: true; initial-value: 0; }
@keyframes ded-risk-in { from { opacity: 0; translate: 0 8px; } }
@keyframes ded-risk-bar { from { scale: 1 0; } }

.ded-risk {
  /* re-theme with these four */
  --ded-risk-bg: oklch(0.205 0.018 25);
  --ded-risk-ink: oklch(0.95 0.012 60);
  --ded-risk-accent: oklch(0.77 0.13 40);
  --ded-risk-high: oklch(0.66 0.19 25);
  /* signals: a categorical set, one hue each */
  --ded-risk-f0: oklch(0.8 0.12 75);
  --ded-risk-f1: oklch(0.7 0.16 15);
  --ded-risk-f2: oklch(0.75 0.1 220);
  --ded-risk-f3: oklch(0.77 0.11 155);
  --ded-risk-f4: oklch(0.74 0.11 305);
  /* derived */
  --ded-risk-med: color-mix(in oklch, var(--ded-risk-f0), var(--ded-risk-high) 25%);
  --ded-risk-panel: color-mix(in oklch, var(--ded-risk-bg), var(--ded-risk-ink) 4.5%);
  --ded-risk-panel2: color-mix(in oklch, var(--ded-risk-bg), var(--ded-risk-ink) 9%);
  --ded-risk-line: color-mix(in oklch, var(--ded-risk-ink) 9%, transparent);
  --ded-risk-line2: color-mix(in oklch, var(--ded-risk-ink) 18%, transparent);
  --ded-risk-muted: color-mix(in oklch, var(--ded-risk-ink) 60%, var(--ded-risk-bg));
  --ded-risk-faint: color-mix(in oklch, var(--ded-risk-ink) 38%, var(--ded-risk-bg));
  --ded-risk-ease: cubic-bezier(0.2, 0.85, 0.25, 1);
  --ded-risk-spring: linear(0, 0.05, 0.2 7%, 0.63 17%, 0.97 26%, 1.07 33%, 1.06 40%, 1.01 51%, 0.995 63%, 1);
  --ded-risk-mono: ui-monospace, Menlo, Consolas, monospace;

  width: 100%;
  height: var(--ded-risk-h, 680px);
  container-type: inline-size;
  position: relative;
  overflow: hidden;
  box-sizing: border-box;
  border-radius: 16px;
  background: var(--ded-risk-bg);
  color: var(--ded-risk-ink);
  font: 400 13px/1.45 system-ui, -apple-system, "Segoe UI", Roboto, sans-serif;
  color-scheme: dark;
  accent-color: var(--ded-risk-accent);

  & *, & *::before, & *::after { box-sizing: border-box; }
  & button { font: inherit; color: inherit; background: none; border: 0; padding: 0; margin: 0; cursor: pointer; text-align: inherit; }
  & :focus-visible { outline: 2px solid var(--ded-risk-accent); outline-offset: 2px; border-radius: 6px; }
  & h2, & h3, & h4 { margin: 0; text-wrap: balance; }
  & p { margin: 0; text-wrap: pretty; }
  & ol, & ul { margin: 0; padding: 0; list-style: none; }
  & svg { display: block; }
  & [hidden] { display: none !important; }
  & .ded-risk-eyebrow { font-size: 10.5px; font-weight: 650; letter-spacing: 0.11em; text-transform: uppercase; color: var(--ded-risk-muted); }

  .ded-risk-app { display: grid; height: 100%; grid-template-columns: 268px minmax(0, 1fr); }

  /* ---------- model side ---------- */
  .ded-risk-side { min-height: 0; overflow: auto; display: flex; flex-direction: column; gap: 18px; padding: 16px 16px; border-right: 1px solid var(--ded-risk-line); background: color-mix(in oklch, var(--ded-risk-bg), black 12%); scrollbar-width: thin; scrollbar-color: var(--ded-risk-line2) transparent; }
  .ded-risk-brand { display: flex; align-items: center; gap: 10px; }
  .ded-risk-brand svg { flex: none; width: 34px; height: 34px; padding: 6px; border-radius: 10px; background: var(--ded-risk-accent); fill: none; stroke: var(--ded-risk-bg); stroke-width: 1.9; stroke-linecap: round; stroke-linejoin: round; }
  .ded-risk-brand span { display: grid; line-height: 1.2; }
  .ded-risk-brand b { font-size: 14px; font-weight: 720; letter-spacing: -0.01em; }
  .ded-risk-brand small { font-size: 11px; color: var(--ded-risk-muted); }
  .ded-risk-weights { display: grid; gap: 10px; }
  .ded-risk-weights > header { display: flex; justify-content: space-between; align-items: baseline; }
  .ded-risk-weights h3 { font-size: 13px; font-weight: 700; }
  .ded-risk-weights > header span { font: 600 11px var(--ded-risk-mono); color: var(--ded-risk-muted); }
  .ded-risk-weights > p { font-size: 11.5px; color: var(--ded-risk-muted); }
  .ded-risk-sliders { display: grid; gap: 12px; }
  .ded-risk-sl { display: grid; grid-template-columns: minmax(0, 1fr) auto; gap: 4px 8px; align-items: center; }
  .ded-risk-sl label { display: flex; align-items: center; gap: 7px; font-size: 12.5px; font-weight: 600; }
  .ded-risk-sl label i { width: 9px; height: 9px; border-radius: 3px; background: var(--ded-risk-fc); }
  .ded-risk-sl output { font: 650 12px var(--ded-risk-mono); font-variant-numeric: tabular-nums; min-width: 3ch; text-align: right; }
  .ded-risk-sl input { grid-column: 1 / -1; width: 100%; margin: 0; accent-color: var(--ded-risk-fc); height: 18px; }
  .ded-risk-sl small { grid-column: 1 / -1; font-size: 11px; color: var(--ded-risk-faint); margin-top: -2px; }
  .ded-risk-presets { display: grid; gap: 4px; }
  .ded-risk-presets button { padding: 7px 10px; border-radius: 9px; font-size: 12.5px; font-weight: 600; color: var(--ded-risk-muted); box-shadow: inset 0 0 0 1px var(--ded-risk-line); transition: background-color 150ms, color 150ms, box-shadow 150ms; }
  .ded-risk-presets button:hover { color: var(--ded-risk-ink); background: var(--ded-risk-line); }
  .ded-risk-presets button[aria-checked="true"] { color: var(--ded-risk-ink); background: var(--ded-risk-panel2); box-shadow: inset 0 0 0 1px var(--ded-risk-accent); }

  /* ---------- main ---------- */
  .ded-risk-main { min-width: 0; min-height: 0; display: grid; grid-template-rows: auto auto minmax(0, 1fr); gap: 12px; padding: 16px 16px 14px; scrollbar-width: thin; scrollbar-color: var(--ded-risk-line2) transparent; }
  .ded-risk-head { display: flex; flex-wrap: wrap; align-items: flex-end; justify-content: space-between; gap: 10px 16px; }
  .ded-risk-head h2 { font-size: clamp(18px, 1rem + 0.6cqi, 23px); font-weight: 740; letter-spacing: -0.03em; line-height: 1.15; }
  .ded-risk-progs, .ded-risk-bands { display: inline-flex; flex-wrap: wrap; gap: 2px; padding: 3px; border-radius: 10px; background: var(--ded-risk-panel); box-shadow: inset 0 0 0 1px var(--ded-risk-line); }
  .ded-risk-progs button, .ded-risk-bands button { padding: 5px 10px; border-radius: 7px; font-size: 12.5px; font-weight: 600; color: var(--ded-risk-muted); transition: background-color 150ms, color 150ms; }
  .ded-risk-progs button:hover, .ded-risk-bands button:hover { color: var(--ded-risk-ink); }
  .ded-risk-progs button[aria-checked="true"], .ded-risk-bands button[aria-checked="true"] { background: var(--ded-risk-ink); color: var(--ded-risk-bg); }

  .ded-risk-top { display: grid; grid-template-columns: minmax(0, 0.95fr) minmax(0, 1.3fr); gap: 12px; }
  .ded-risk-kpis { display: grid; grid-template-columns: repeat(2, minmax(0, 1fr)); gap: 8px; }
  .ded-risk-kpi { display: grid; align-content: start; gap: 1px; padding: 10px 12px; border-radius: 12px; background: var(--ded-risk-panel); box-shadow: inset 0 0 0 1px var(--ded-risk-line); animation: ded-risk-in 500ms var(--ded-risk-ease) both; animation-delay: calc(var(--i) * 55ms); }
  .ded-risk-kpi > span { font-size: 10.5px; font-weight: 650; letter-spacing: 0.09em; text-transform: uppercase; color: var(--ded-risk-muted); }
  .ded-risk-kpi b { font-size: clamp(20px, 0.8rem + 1.2cqi, 26px); font-weight: 720; letter-spacing: -0.03em; line-height: 1.12; font-variant-numeric: tabular-nums; }
  .ded-risk-kpi b[data-tone="high"] { color: color-mix(in oklch, var(--ded-risk-high), white 18%); }
  .ded-risk-kpi b[data-tone="med"] { color: var(--ded-risk-med); }
  .ded-risk-kpi small { font-size: 11px; color: var(--ded-risk-muted); font-variant-numeric: tabular-nums; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
  .ded-risk-histc { display: grid; grid-template-rows: auto minmax(0, 1fr); gap: 4px; padding: 10px 12px 8px; border-radius: 12px; background: var(--ded-risk-panel); box-shadow: inset 0 0 0 1px var(--ded-risk-line); }
  .ded-risk-histc header { display: flex; justify-content: space-between; align-items: baseline; gap: 8px; flex-wrap: wrap; }
  .ded-risk-histc h3 { font-size: 12.5px; font-weight: 700; }
  .ded-risk-histc header span { font-size: 11px; color: var(--ded-risk-muted); font-variant-numeric: tabular-nums; }
  .ded-risk-hist { position: relative; min-height: 104px; }
  .ded-risk-hist svg { position: absolute; inset: 0; width: 100%; height: 100%; overflow: visible; }
  .ded-risk-hist text { fill: var(--ded-risk-faint); font: 10px var(--ded-risk-mono); font-variant-numeric: tabular-nums; }
  .ded-risk-hist .ded-risk-g line { stroke: var(--ded-risk-line); }
  .ded-risk-hb { fill: var(--ded-risk-faint); cursor: pointer; transform-box: fill-box; transform-origin: bottom; animation: ded-risk-bar 600ms var(--ded-risk-ease) both; animation-delay: calc(200ms + var(--i) * 22ms); transition: y 420ms var(--ded-risk-ease), height 420ms var(--ded-risk-ease), fill 300ms, opacity 200ms; }
  .ded-risk-hb[data-b="med"] { fill: var(--ded-risk-med); }
  .ded-risk-hb[data-b="high"] { fill: var(--ded-risk-high); }
  .ded-risk-hb:hover { opacity: 0.8; }
  .ded-risk-hist svg:has(.ded-risk-hb[data-on]) .ded-risk-hb:not([data-on]) { opacity: 0.35; }
  .ded-risk-thr { stroke: var(--ded-risk-ink); stroke-opacity: 0.45; stroke-dasharray: 3 3; }
  .ded-risk-hist .ded-risk-thrl { fill: var(--ded-risk-muted); font: 600 10px system-ui, sans-serif; }
  .ded-risk-tip { position: absolute; z-index: 5; left: 0; top: 0; min-width: 150px; padding: 7px 9px; border-radius: 9px; pointer-events: none; background: var(--ded-risk-ink); color: var(--ded-risk-bg); font-size: 11.5px; font-variant-numeric: tabular-nums; opacity: 0; translate: var(--ded-risk-tx, 0) var(--ded-risk-ty, 0); transition: opacity 120ms; }
  .ded-risk-tip.is-on { opacity: 1; }
  .ded-risk-tip b { display: block; }

  /* ranked list on a shared subgrid */
  .ded-risk-listp {
    min-height: 0; display: grid; grid-template-rows: auto auto minmax(0, 1fr);
    grid-template-columns: 30px minmax(150px, 1fr) minmax(0, 1.9fr) 52px 112px; column-gap: 12px;
    padding: 10px 12px 4px; border-radius: 14px; background: var(--ded-risk-panel); box-shadow: inset 0 0 0 1px var(--ded-risk-line);
  }
  .ded-risk-listp > header { grid-column: 1 / -1; display: flex; flex-wrap: wrap; align-items: center; gap: 8px 14px; padding-bottom: 8px; }
  .ded-risk-switch { display: flex; align-items: center; gap: 8px; font-size: 12px; font-weight: 600; cursor: pointer; }
  .ded-risk-switch input { appearance: none; position: relative; width: 30px; height: 18px; margin: 0; border-radius: 99px; background: var(--ded-risk-line2); cursor: pointer; transition: background-color 180ms; }
  .ded-risk-switch input::after { content: ""; position: absolute; top: 2px; left: 2px; width: 14px; height: 14px; border-radius: 50%; background: var(--ded-risk-ink); transition: translate 280ms var(--ded-risk-spring); }
  .ded-risk-switch input:checked { background: var(--ded-risk-accent); }
  .ded-risk-switch input:checked::after { translate: 12px 0; }
  .ded-risk-flegend { display: flex; flex-wrap: wrap; gap: 3px 10px; margin-left: auto; font-size: 11px; color: var(--ded-risk-muted); }
  .ded-risk-flegend li { display: flex; align-items: center; gap: 5px; }
  .ded-risk-flegend i { width: 8px; height: 8px; border-radius: 2px; background: var(--ded-risk-fc); }
