  const m = { l: 28, r: 6, t: 14, b: 16 }, ymax = Math.max(10, Math.ceil(Math.max(...cnt) / 10) * 10);
  const x = v => m.l + v / 100 * (Wd - m.l - m.r), y = v => Hd - m.b - v / ymax * (Hd - m.t - m.b);
  hg = { cnt, x, m, Wd };
  hGrid.innerHTML = '';
