  [0, 25, 50, 75, 100].forEach(v => { mk('text', { x: x(v), y: Hd - 3, 'text-anchor': v === 0 ? 'start' : v === 100 ? 'end' : 'middle' }, hGrid).textContent = v; });
  const bw = (x(5) - x(0)) - 2;
  bars.forEach((b, i) => {
    b.setAttribute('x', x(i * 5) + 1); b.setAttribute('width', bw);
    b.style.y = y(cnt[i]) + 'px'; b.style.height = Math.max(0, Hd - m.b - y(cnt[i])) + 'px';
    const on = (S.band === 'high' && b.dataset.b === 'high') || (S.band === 'med' && b.dataset.b === 'med');
    on ? b.setAttribute('data-on', '') : b.removeAttribute('data-on');
  });
  thrG.innerHTML = '';
  [[MED, 'Medium'], [HIGH, 'High']].forEach(([v, l]) => { mk('line', { class: 'ded-risk-thr', x1: x(v), x2: x(v), y1: m.t - 6, y2: Hd - m.b }, thrG); mk('text', { class: 'ded-risk-thrl', x: x(v) + 4, y: m.t - 2 }, thrG).textContent = l; });
  $('[data-k="histsub"]').textContent = `${pool.length} students · ${S.prog === 'all' ? 'all programmes' : PROG[S.prog]}`;
}
hSvg.addEventListener('pointermove', ev => {
  if (!hg) return;
  const r = hSvg.getBoundingClientRect(), px = ev.clientX - r.left, i = clamp(Math.floor((px - hg.m.l) / (hg.Wd - hg.m.l - hg.m.r) * 20), 0, 19);
  const b = band(i * 5 + 2.5);
  hTip.innerHTML = `<b>${i * 5}–${i * 5 + 5} points</b>${hg.cnt[i]} student${hg.cnt[i] === 1 ? '' : 's'} · ${b === 'high' ? 'high risk' : b === 'med' ? 'medium risk' : 'not flagged'}`;
  const tw = hTip.offsetWidth;
