/* ---------------- ranked list with FLIP ---------------- */
const listEl = $('.ded-risk-list');
const rowEls = new Map();
const emptyLi = document.createElement('li'); emptyLi.className = 'ded-risk-empty';
function makeRow(s) {
  const li = document.createElement('li'); li.dataset.id = s.id;
  li.innerHTML = `<button type="button" class="ded-risk-row" aria-expanded="false"><span class="ded-risk-rank"></span>
    <span class="ded-risk-who"><span class="ded-risk-av" aria-hidden="true">${s.ini}</span><span><b>${s.name}</b><small>${PROG[s.prog]} · ${s.tutor}</small></span></span>
    <span class="ded-risk-track" aria-hidden="true">${F.map((f, i) => `<i style="--ded-risk-fc: var(--ded-risk-f${i})"></i>`).join('')}</span>
    <span class="ded-risk-score"></span><span class="ded-risk-contact"></span></button>`;
