  btn.style.setProperty('--ded-risk-band', b === 'high' ? 'var(--ded-risk-high)' : 'var(--ded-risk-med)');
  li.querySelector('.ded-risk-rank').textContent = idx + 1;
  li.querySelectorAll('.ded-risk-track i').forEach((el, i) => el.style.setProperty('--w', c[i].toFixed(2) + '%'));
  li.querySelector('.ded-risk-score').textContent = Math.round(sc);
  const ct = li.querySelector('.ded-risk-contact'); ct.textContent = contactText(s); s.last == null ? ct.setAttribute('data-none', '') : ct.removeAttribute('data-none');
  const top = c.map((v, i) => [v, i]).sort((a, b) => b[0] - a[0]).slice(0, 2).map(([, i]) => F[i].name.toLowerCase());
  btn.setAttribute('aria-label', `${idx + 1}. ${s.name}, ${PROG[s.prog]}, score ${Math.round(sc)}, ${b === 'high' ? 'high' : 'medium'} risk, mainly ${top.join(' and ')}. ${contactText(s)}.`);
