}
function listed() {
  return ST.map(s => ({ s, sc: score(s) })).filter(({ s, sc }) => !s.resolved && inProg(s) && sc >= MED && (S.band === 'flag' || band(sc) === S.band) && (!S.uncontacted || s.last == null)).sort((a, b) => b.sc - a.sc || a.s.id - b.s.id);
}
function renderList(animate) {
  const list = listed(), first = new Map();
  if (animate && !reduce) rowEls.forEach((li, id) => { if (li.isConnected) first.set(id, li.getBoundingClientRect().top); });
  const keep = new Set(list.map(o => o.s.id));
  rowEls.forEach((li, id) => { if (!keep.has(id)) li.remove(); });
  if (emptyLi.isConnected && list.length) emptyLi.remove();
  list.forEach(({ s, sc }, idx) => {
    let li = rowEls.get(s.id);
    if (!li) { li = makeRow(s); rowEls.set(s.id, li); }
    updateRow(li, s, idx, sc);
    if (listEl.children[idx] !== li) listEl.insertBefore(li, listEl.children[idx] || null);
  });
  if (!list.length) { emptyLi.textContent = S.uncontacted ? 'Every flagged student in this view has been contacted.' : 'No students are flagged in this view.'; listEl.appendChild(emptyLi); }
  if (animate && !reduce) list.forEach(({ s }) => {
    const li = rowEls.get(s.id), f = first.get(s.id), now = li.getBoundingClientRect().top;
    if (f == null) li.animate([{ opacity: 0, transform: 'translateX(-10px)' }, { opacity: 1, transform: 'none' }], { duration: 340, easing: EASE });
    else if (Math.abs(f - now) > 0.5) li.animate([{ transform: `translateY(${f - now}px)` }, { transform: 'none' }], { duration: 520, easing: EASE });
