listEl.addEventListener('keydown', ev => {
  const b = ev.target.closest('.ded-risk-row'); if (!b) return;
  const li = b.parentElement, sib = ev.key === 'ArrowDown' ? li.nextElementSibling : ev.key === 'ArrowUp' ? li.previousElementSibling : null;
