/* ---------------- drawer ---------------- */
const drawer = $('.ded-risk-drawer');
let opener = null;
function paintDrawer() {
  const s = S.open; if (!s) return;
  const c = contrib(s), sc = score(s), b = band(sc);
  drawer.style.setProperty('--ded-risk-band', b === 'high' ? 'var(--ded-risk-high)' : b === 'med' ? 'var(--ded-risk-med)' : 'var(--ded-risk-faint)');
