  $('[data-k="dname"]').textContent = s.name;
  $('[data-k="dmeta"]').textContent = `${s.sid} · ${PROG[s.prog]} · tutor ${s.tutor}`;
  $('.ded-risk-factors').innerHTML = c.map((v, i) => [v, i]).sort((a, b) => b[0] - a[0]).map(([v, i]) => `<li style="--ded-risk-fc: var(--ded-risk-f${i}); --w: ${(s.sig[i] * 100).toFixed(0)}%"><b><i></i>${F[i].name}</b><em>+${v.toFixed(1)}</em><span>${evidence(s, i)} · weight ${W[i]}%</span><u></u></li>`).join('');
  const meet = $('[data-act="meet"]'); meet.setAttribute('aria-pressed', s.meet); meet.textContent = s.meet ? 'Tutor meeting booked' : 'Book tutor meeting';
  $('.ded-risk-timeline').innerHTML = s.tl.map(e => `<li><span>${e.msg}<time>${e.t}</time></span></li>`).join('');
