css:
@property --ded-workload-t { syntax: '<number>'; inherits: false; initial-value: 0; }
@keyframes ded-workload-in { from { opacity: 0; translate: 0 8px; } }
@keyframes ded-workload-cell { from { opacity: 0; scale: 0.6; } }
@keyframes ded-workload-grow { from { scale: 1 0; } }
@keyframes ded-workload-progress { from { scale: 0 1; } to { scale: 1 1; } }

.ded-workload {
  /* re-theme with these four */
  --ded-workload-paper: oklch(0.966 0.016 80);
  --ded-workload-ink: oklch(0.27 0.03 50);
  --ded-workload-accent: oklch(0.5 0.16 262);
  --ded-workload-hot: oklch(0.58 0.18 33);
  /* derived */
  --ded-workload-card: color-mix(in oklch, var(--ded-workload-paper), white 62%);
  --ded-workload-sunk: color-mix(in oklch, var(--ded-workload-paper), var(--ded-workload-ink) 5%);
  --ded-workload-line: color-mix(in oklch, var(--ded-workload-ink) 11%, transparent);
  --ded-workload-line2: color-mix(in oklch, var(--ded-workload-ink) 22%, transparent);
  --ded-workload-muted: color-mix(in oklch, var(--ded-workload-ink) 62%, var(--ded-workload-paper));
  --ded-workload-faint: color-mix(in oklch, var(--ded-workload-ink) 40%, var(--ded-workload-paper));
  --ded-workload-lo: color-mix(in oklch, var(--ded-workload-paper), white 45%);
  --ded-workload-mid: oklch(0.86 0.1 78);
  --ded-workload-k0: color-mix(in oklch, var(--ded-workload-ink) 78%, var(--ded-workload-paper));
  --ded-workload-k1: color-mix(in oklch, var(--ded-workload-ink) 46%, var(--ded-workload-paper));
  --ded-workload-k2: color-mix(in oklch, var(--ded-workload-ink) 24%, var(--ded-workload-paper));
  --ded-workload-k3: var(--ded-workload-accent);
  --ded-workload-k4: oklch(0.78 0.13 72);
  --ded-workload-ease: cubic-bezier(0.2, 0.8, 0.2, 1);
  --ded-workload-spring: linear(0, 0.05, 0.2 7%, 0.63 17%, 0.96 26%, 1.07 33%, 1.06 40%, 1.01 51%, 0.995 63%, 1);
  --ded-workload-mono: ui-monospace, Menlo, Consolas, monospace;

  width: 100%;
  height: var(--ded-workload-h, 680px);
  container-type: inline-size;
  position: relative;
  overflow: hidden;
  box-sizing: border-box;
  border-radius: 16px;
  background: var(--ded-workload-paper);
  color: var(--ded-workload-ink);
  font: 400 13px/1.45 system-ui, -apple-system, "Segoe UI", Roboto, sans-serif;
  accent-color: var(--ded-workload-accent);
  box-shadow: inset 0 0 0 1px var(--ded-workload-line);

  & *, & *::before, & *::after { box-sizing: border-box; }
  & button { font: inherit; color: inherit; background: none; border: 0; padding: 0; margin: 0; cursor: pointer; text-align: inherit; }
  & button:disabled, & button[aria-disabled="true"] { cursor: not-allowed; }
  & :focus-visible { outline: 2px solid var(--ded-workload-accent); outline-offset: 2px; border-radius: 6px; }
  & h2 { margin: 0; text-wrap: balance; }
  & p { margin: 0; text-wrap: pretty; }
  & ul { margin: 0; padding: 0; list-style: none; }
  & svg { display: block; }
  & [hidden] { display: none !important; }
  & .ded-workload-eyebrow { font-size: 10.5px; font-weight: 650; letter-spacing: 0.11em; text-transform: uppercase; color: var(--ded-workload-muted); }

  .ded-workload-app { display: grid; height: 100%; grid-template-columns: 214px minmax(0, 1fr); }

  /* ---------- side ---------- */
  .ded-workload-side { min-height: 0; overflow: auto; display: flex; flex-direction: column; gap: 18px; padding: 18px 14px; background: var(--ded-workload-sunk); border-right: 1px solid var(--ded-workload-line); scrollbar-width: thin; }
  .ded-workload-brand { display: flex; align-items: center; gap: 10px; }
  .ded-workload-brand svg { flex: none; width: 34px; height: 34px; padding: 6px; border-radius: 10px; background: var(--ded-workload-accent); fill: none; stroke: var(--ded-workload-paper); stroke-width: 1.8; stroke-linecap: round; stroke-linejoin: round; }
  .ded-workload-brand span { display: grid; line-height: 1.2; }
  .ded-workload-brand b { font-size: 13.5px; font-weight: 720; letter-spacing: -0.01em; }
  .ded-workload-brand small { font-size: 11px; color: var(--ded-workload-muted); }
  .ded-workload-nav { display: grid; gap: 2px; }
  .ded-workload-nav button { display: grid; grid-template-columns: 18px minmax(0, 1fr) auto; align-items: center; gap: 10px; padding: 8px 10px; border-radius: 9px; font-weight: 600; color: var(--ded-workload-muted); transition: background-color 150ms, color 150ms; }
  .ded-workload-nav button svg { width: 18px; height: 18px; fill: none; stroke: currentColor; stroke-width: 1.7; stroke-linecap: round; stroke-linejoin: round; }
  .ded-workload-nav button:hover { background: var(--ded-workload-line); color: var(--ded-workload-ink); }
  .ded-workload-nav button[aria-current="page"] { background: var(--ded-workload-card); color: var(--ded-workload-ink); box-shadow: inset 0 0 0 1px var(--ded-workload-line), 0 1px 2px var(--ded-workload-line); }
  .ded-workload-nav em { font: 700 10.5px/17px var(--ded-workload-mono); font-style: normal; min-width: 18px; padding: 0 5px; border-radius: 99px; text-align: center; background: var(--ded-workload-accent); color: var(--ded-workload-paper); }
  .ded-workload-nav em:empty { display: none; }
  .ded-workload-limit { display: grid; gap: 6px; padding: 12px; border-radius: 12px; background: var(--ded-workload-card); box-shadow: inset 0 0 0 1px var(--ded-workload-line); }
  .ded-workload-limit label { display: flex; justify-content: space-between; font-size: 12px; font-weight: 650; }
  .ded-workload-limit output { font: 700 12px var(--ded-workload-mono); color: var(--ded-workload-hot); }
  .ded-workload-limit input { width: 100%; margin: 0; accent-color: var(--ded-workload-hot); }
  .ded-workload-limit p { font-size: 11px; color: var(--ded-workload-muted); }
  .ded-workload-acts { display: grid; gap: 6px; }
  .ded-workload-btn { position: relative; overflow: hidden; display: flex; align-items: center; justify-content: center; min-height: 36px; padding: 7px 12px; border-radius: 10px; font-size: 12.5px; font-weight: 650; box-shadow: inset 0 0 0 1px var(--ded-workload-line2); transition: background-color 150ms, opacity 150ms, scale 200ms var(--ded-workload-spring); }
  .ded-workload-btn:hover:not(:disabled):not([aria-disabled="true"]) { background: var(--ded-workload-line); }
  .ded-workload-btn:active:not(:disabled) { scale: 0.97; }
  .ded-workload-btn:disabled, .ded-workload-btn[aria-disabled="true"] { opacity: 0.45; }
  .ded-workload-primary { background: var(--ded-workload-accent); color: var(--ded-workload-paper); box-shadow: none; }
  .ded-workload-primary:hover:not(:disabled):not([aria-disabled="true"]) { background: color-mix(in oklch, var(--ded-workload-accent), black 12%) !important; }
  .ded-workload-btn span { position: relative; z-index: 1; }
  .ded-workload-btn i { position: absolute; inset: 0; background: color-mix(in oklch, white 22%, transparent); transform-origin: left; scale: 0 1; }
  .ded-workload-btn.is-busy i { animation: ded-workload-progress 700ms var(--ded-workload-ease) forwards; }
  .ded-workload-note { margin-top: auto; font-size: 11px; color: var(--ded-workload-muted); }
  .ded-workload-note b { color: var(--ded-workload-ink); font-weight: 650; }
  .ded-workload-legend { display: grid; gap: 4px; }
  .ded-workload-ramp { height: 10px; border-radius: 5px; background: linear-gradient(90deg, var(--ded-workload-lo), var(--ded-workload-mid) var(--ded-workload-lp, 60%), var(--ded-workload-hot)); box-shadow: inset 0 0 0 1px var(--ded-workload-line); }
  .ded-workload-legend div { display: flex; justify-content: space-between; font: 10.5px var(--ded-workload-mono); color: var(--ded-workload-muted); }

  /* ---------- main ---------- */
  .ded-workload-main { min-width: 0; min-height: 0; display: grid; grid-template-rows: auto auto minmax(0, 1fr); gap: 12px; padding: 16px 16px 14px; scrollbar-width: thin; }
  .ded-workload-head h2 { font-size: clamp(17px, 0.9rem + 0.6cqi, 22px); font-weight: 740; letter-spacing: -0.025em; line-height: 1.15; }
  .ded-workload-kpis { display: grid; grid-template-columns: repeat(4, minmax(0, 1fr)); gap: 8px; }
  .ded-workload-kpi { display: grid; gap: 0; padding: 8px 12px; border-radius: 12px; background: var(--ded-workload-card); box-shadow: inset 0 0 0 1px var(--ded-workload-line); animation: ded-workload-in 500ms var(--ded-workload-ease) both; animation-delay: calc(var(--i) * 55ms); }
  .ded-workload-kpi > span { font-size: 10.5px; font-weight: 650; letter-spacing: 0.09em; text-transform: uppercase; color: var(--ded-workload-muted); }
  .ded-workload-kpi b { font-size: clamp(19px, 0.8rem + 1.1cqi, 25px); font-weight: 720; letter-spacing: -0.03em; line-height: 1.15; font-variant-numeric: tabular-nums; transition: color 300ms; }
  .ded-workload-kpi b[data-hot] { color: var(--ded-workload-hot); }
  .ded-workload-kpi small { font-size: 11px; color: var(--ded-workload-muted); font-variant-numeric: tabular-nums; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
  .ded-workload-view { min-height: 0; }

  /* one grid, three bands: week header, heat rows, selected teacher — all share the week columns */
  .ded-workload-board {
    --ded-workload-namew: 158px;
    position: relative; min-height: 0; height: 100%; display: grid; align-content: start;
    grid-template-columns: var(--ded-workload-namew) repeat(14, minmax(0, 1fr)); column-gap: 3px; row-gap: 6px;
    padding: 10px 12px 10px; border-radius: 14px; background: var(--ded-workload-card); box-shadow: inset 0 0 0 1px var(--ded-workload-line);
    overflow: auto; scrollbar-width: thin;
  }
