const NW = 14, MON = ['Jan', 'Feb', 'Mar', 'Apr', 'May', 'Jun', 'Jul', 'Aug', 'Sep', 'Oct', 'Nov', 'Dec'];
const wkDate = w => { const d = new Date(2026, 8, 7 + 7 * w + (w >= 7 ? 7 : 0)); return d; };   /* half term after week 7 */
const fmtD = d => d.getDate() + ' ' + MON[d.getMonth()];
const T = [
  ['Ms Adaeze Okafor', 'Head of English', 18, 9], ['Mr Tobias Wren', 'English', 22, 5], ['Ms Priya Raman', 'English', 22, 5],
  ['Mr Callum Firth', 'English · 0.8', 17, 4], ['Dr Helena Varga', 'Head of History', 18, 9], ['Mr Josiah Mbeki', 'History', 22, 5],
  ['Ms Ruth Calloway', 'Geography', 22, 5], ['Mr Leon Duarte', 'Geography & RE', 21, 5], ['Ms Imogen Hale', 'RE', 20, 5]
