/* [teacher, class, title, scripts, minutes per script, due week (1-based), fixed] */
const A0 = [
  [0, 'Y11', 'Macbeth essay', 28, 15, 5], [0, 'Y13', 'Coursework draft', 18, 25, 8], [0, 'Y11', 'Mock Paper 1', 28, 15, 11, 1],
  [1, 'Y10', 'Poetry comparison', 30, 12, 5], [1, 'Y8', 'Gothic story', 30, 9, 5], [1, 'Y11', 'Mock Paper 2', 29, 15, 11, 1], [1, 'Y9', 'Speech writing', 30, 7, 9],
  [2, 'Y7', 'Reading check', 31, 6, 4], [2, 'Y12', 'Close reading', 22, 20, 5], [2, 'Y11', 'Mock Paper 1', 30, 15, 11, 1], [2, 'Y10', 'An Inspector Calls essay', 29, 12, 9],
  [3, 'Y8', 'Persuasive letter', 28, 8, 5], [3, 'Y9', 'Of Mice and Men essay', 27, 10, 8], [3, 'Y7', 'Myths project', 30, 7, 10],
  [4, 'Y13', 'NEA proposal', 16, 30, 5], [4, 'Y11', 'History mock', 28, 15, 11, 1], [4, 'Y9', 'Source analysis', 30, 8, 9],
  [5, 'Y10', 'Medicine through time', 31, 12, 5], [5, 'Y8', 'Tudors essay', 30, 8, 6], [5, 'Y11', 'History mock', 29, 15, 11, 1], [5, 'Y12', 'Interpretations essay', 20, 20, 9],
  [6, 'Y7', 'Map skills test', 31, 5, 3], [6, 'Y10', 'Fieldwork write-up', 30, 15, 5], [6, 'Y11', 'Geography mock', 28, 15, 11, 1], [6, 'Y13', 'Coursework draft', 14, 30, 9],
  [7, 'Y9', 'Tectonics test', 30, 6, 5], [7, 'Y8', 'Ethics essay', 30, 9, 5], [7, 'Y12', 'Case study', 18, 18, 9],
  [8, 'Y10', 'Religion and life essay', 30, 12, 5], [8, 'Y11', 'RE mock', 27, 15, 11, 1], [8, 'Y7', 'Festivals project', 30, 6, 8]
