const EVENTS = { 5: [3, "Year 7 parents' evening"], 11: [3, 'Report writing'], 12: [3, 'Report writing'] };

const S = { limit: 45, view: 'map', t: 1, sel: null };
/* marking lands 70% in the week after the due date and 30% in the week after that */
function load() {
  const L = T.map(t => Array.from({ length: NW }, (_, w) => ({ k: [t.teach, t.plan, t.duty, 0, EVENTS[w] ? EVENTS[w][0] : 0], items: [] })));
