/* ---------------- build the board once ---------------- */
const weeksEl = $('.ded-workload-weeks'), heat = $('.ded-workload-heat'), barsEl = $('.ded-workload-bars'), chipsEl = $('.ded-workload-chips'), tip = $('.ded-workload-tip'), board = $('.ded-workload-board');
weeksEl.innerHTML = '<span>Week</span>' + Array.from({ length: NW }, (_, w) => `<span title="w/c ${fmtD(wkDate(w))}">${w + 1}</span>`).join('');
heat.innerHTML = T.map(t => `<div class="ded-workload-hrow" role="row" data-t="${t.i}" aria-selected="false" tabindex="-1"><div class="ded-workload-hname" role="rowheader"><b><span class="ded-workload-full">${t.short}</span><span class="ded-workload-ini" aria-hidden="true">${t.name.split(' ').slice(1).map(x => x[0]).join('')}</span></b><small></small></div>${Array.from({ length: NW }, (_, w) => `<div class="ded-workload-cell" role="gridcell" data-w="${w}" style="--r:${t.i};--c:${w}"></div>`).join('')}</div>`).join('');
const rowsEl = $$('.ded-workload-hrow', heat);
barsEl.innerHTML = `<div class="ded-workload-axis" aria-hidden="true"></div>` + Array.from({ length: NW }, (_, w) => `<div class="ded-workload-col" data-w="${w}" style="--c:${w}">${KNAMES.map((k, j) => `<i style="--ded-workload-c: var(--ded-workload-k${j}); --c:${w}"></i>`).join('')}</div>`).join('') + `<div class="ded-workload-limline"><span></span></div>`;
chipsEl.innerHTML = `<div class="ded-workload-slot">by week</div>` + Array.from({ length: NW }, (_, w) => `<div class="ded-workload-slot" data-w="${w}"></div>`).join('');
const slots = $$('.ded-workload-slot[data-w]', chipsEl);
const BAR_MAX = 60;

/* ---------------- paint ---------------- */
function tOf(h) { return clamp((h - 30) / ((S.limit + 10) - 30), 0, 1); }
function paintHeat() {
  rowsEl.forEach((row, ti) => {
    const cells = $$('.ded-workload-cell', row);
    let peak = 0, over = 0;
    cells.forEach((c, w) => {
      const h = LD[ti][w].total; peak = Math.max(peak, h); if (h > S.limit) over++;
      c.style.setProperty('--ded-workload-tv', tOf(h).toFixed(3));
      c.textContent = Math.round(h);
      h > S.limit ? c.setAttribute('data-over', '') : c.removeAttribute('data-over');
      c.setAttribute('aria-label', `${T[ti].name}, week ${w + 1}: ${h.toFixed(1)} hours${h > S.limit ? ', over the limit' : ''}`);
    });
    row.querySelector('small').textContent = over ? `${over} over` : '';
    row.querySelector('.ded-workload-hname').title = `${T[ti].name}, ${T[ti].role}: peak ${peak.toFixed(1)} h`;
    row.setAttribute('aria-selected', String(ti === S.t));
    row.tabIndex = ti === S.t ? 0 : -1;
  });
}
function paintKpis() {
  let sum = 0, n = 0, peak = { h: 0 }, over = 0;
  LD.forEach((row, ti) => row.forEach((c, w) => { sum += c.total; n++; if (c.total > peak.h) peak = { h: c.total, ti, w }; if (c.total > S.limit) over++; }));
  const mark = A0.reduce((s, a) => s + a.hrs, 0), moved = A0.filter(a => a.due !== a.due0).length;
  const k = [
    ['Average week', (sum / n).toFixed(1) + ' h', `${T.length} teachers · ${NW} weeks`],
    ['Peak week', peak.h.toFixed(1) + ' h', `${T[peak.ti].short} · week ${peak.w + 1}`, peak.h > S.limit],
    ['Weeks over limit', over, `of ${n} teacher-weeks above ${S.limit} h`, over > 0],
