css:
@property --ded-admit-pin { syntax: '<number>'; inherits: true; initial-value: 0; }
@keyframes ded-admit-in { from { opacity: 0; translate: 0 8px; } }
@keyframes ded-admit-bar { from { scale: 1 0; } }
@keyframes ded-admit-draw { from { stroke-dashoffset: 1; } to { stroke-dashoffset: 0; } }
@keyframes ded-admit-fade { from { opacity: 0; } }

.ded-admit {
  /* re-theme with these four */
  --ded-admit-bg: oklch(0.195 0.024 205);
  --ded-admit-ink: oklch(0.95 0.015 90);
  --ded-admit-accent: oklch(0.8 0.12 82);
  --ded-admit-hot: oklch(0.67 0.17 30);
  /* derived */
  --ded-admit-cool: color-mix(in oklch, oklch(0.62 0.05 205), var(--ded-admit-bg) 10%);
  --ded-admit-panel: color-mix(in oklch, var(--ded-admit-bg), var(--ded-admit-ink) 4.5%);
  --ded-admit-panel2: color-mix(in oklch, var(--ded-admit-bg), var(--ded-admit-ink) 9%);
  --ded-admit-line: color-mix(in oklch, var(--ded-admit-ink) 9%, transparent);
  --ded-admit-line2: color-mix(in oklch, var(--ded-admit-ink) 18%, transparent);
  --ded-admit-muted: color-mix(in oklch, var(--ded-admit-ink) 60%, var(--ded-admit-bg));
  --ded-admit-faint: color-mix(in oklch, var(--ded-admit-ink) 38%, var(--ded-admit-bg));
  --ded-admit-ease: cubic-bezier(0.2, 0.85, 0.25, 1);
  --ded-admit-spring: linear(0, 0.05, 0.2 7%, 0.63 17%, 0.97 26%, 1.07 33%, 1.06 40%, 1.01 51%, 0.995 63%, 1);
  --ded-admit-mono: ui-monospace, Menlo, Consolas, monospace;
  --ded-admit-serif: ui-serif, "Iowan Old Style", Georgia, serif;

  width: 100%;
  height: var(--ded-admit-h, 680px);
  container-type: inline-size;
  position: relative;
  overflow: hidden;
  box-sizing: border-box;
  display: grid;
  grid-template-rows: auto minmax(0, 1fr);
  border-radius: 16px;
  background:
    radial-gradient(120% 70% at 85% -10%, color-mix(in oklch, var(--ded-admit-accent) 9%, transparent), transparent 60%),
    var(--ded-admit-bg);
  color: var(--ded-admit-ink);
  font: 400 13px/1.45 system-ui, -apple-system, "Segoe UI", Roboto, sans-serif;
  color-scheme: dark;
  accent-color: var(--ded-admit-accent);

  & *, & *::before, & *::after { box-sizing: border-box; }
  & button { font: inherit; color: inherit; background: none; border: 0; padding: 0; margin: 0; cursor: pointer; text-align: inherit; }
  & button:disabled { cursor: not-allowed; }
  & :focus-visible { outline: 2px solid var(--ded-admit-accent); outline-offset: 2px; border-radius: 6px; }
  & h2, & h3 { margin: 0; text-wrap: balance; }
  & p { margin: 0; text-wrap: pretty; }
  & ol, & ul { margin: 0; padding: 0; list-style: none; }
  & svg { display: block; }
  & [hidden] { display: none !important; }
  & .ded-admit-eyebrow { font-size: 10.5px; font-weight: 650; letter-spacing: 0.12em; text-transform: uppercase; color: var(--ded-admit-muted); }

  .ded-admit-top { display: flex; flex-wrap: wrap; align-items: center; gap: 10px 22px; padding: 14px 18px; border-bottom: 1px solid var(--ded-admit-line); }
  .ded-admit-brand { display: flex; align-items: center; gap: 10px; }
  .ded-admit-brand svg { width: 34px; height: 34px; padding: 6px; border-radius: 50%; box-shadow: inset 0 0 0 1.5px var(--ded-admit-accent); fill: none; stroke: var(--ded-admit-accent); stroke-width: 1.6; stroke-linecap: round; stroke-linejoin: round; }
  .ded-admit-brand span { display: grid; line-height: 1.2; }
  .ded-admit-brand b { font: 600 15px/1.1 var(--ded-admit-serif); letter-spacing: 0.01em; }
  .ded-admit-brand small { font-size: 11px; color: var(--ded-admit-muted); }
  .ded-admit-title { margin-right: auto; min-width: 0; }
  .ded-admit-title h2 { font: 600 clamp(19px, 1rem + 0.8cqi, 26px)/1.1 var(--ded-admit-serif); letter-spacing: -0.01em; }
  .ded-admit-tabs { display: flex; gap: 2px; padding: 3px; border-radius: 99px; background: var(--ded-admit-panel); box-shadow: inset 0 0 0 1px var(--ded-admit-line); }
  .ded-admit-tabs button { padding: 6px 14px; border-radius: 99px; font-weight: 600; color: var(--ded-admit-muted); transition: background-color 160ms, color 160ms; }
  .ded-admit-tabs button:hover { color: var(--ded-admit-ink); }
  .ded-admit-tabs button[aria-selected="true"] { background: var(--ded-admit-accent); color: var(--ded-admit-bg); }

  .ded-admit-body { min-height: 0; display: grid; grid-template-columns: minmax(0, 1fr) clamp(250px, 26cqi, 296px); }
  .ded-admit-main { min-height: 0; min-width: 0; display: grid; grid-template-rows: auto minmax(0, 1fr); gap: 12px; padding: 14px 16px 16px 18px; scrollbar-width: thin; }
  .ded-admit-kpis { display: grid; grid-template-columns: repeat(4, minmax(0, 1fr)); gap: 8px; }
  .ded-admit-kpi { position: relative; display: grid; gap: 0; padding: 10px 12px; border-radius: 12px; background: var(--ded-admit-panel); box-shadow: inset 0 0 0 1px var(--ded-admit-line); animation: ded-admit-in 520ms var(--ded-admit-ease) both; animation-delay: calc(var(--i) * 55ms); }
  .ded-admit-kpi > span { font-size: 10.5px; font-weight: 650; letter-spacing: 0.09em; text-transform: uppercase; color: var(--ded-admit-muted); }
  .ded-admit-kpi b { font: 600 clamp(22px, 0.9rem + 1.3cqi, 30px)/1.12 var(--ded-admit-serif); font-variant-numeric: tabular-nums lining-nums; }
  .ded-admit-kpi b small { font: 600 12px var(--ded-admit-mono); color: var(--ded-admit-muted); margin-left: 4px; }
  .ded-admit-kpi b[data-tone="hot"] { color: color-mix(in oklch, var(--ded-admit-hot), white 15%); }
  .ded-admit-kpi b[data-tone="good"] { color: var(--ded-admit-accent); }
  .ded-admit-kpi > small { font-size: 11px; color: var(--ded-admit-muted); font-variant-numeric: tabular-nums; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
  .ded-admit-kpi-pin { --ded-admit-pin: var(--ded-admit-pv, 0); transition: --ded-admit-pin 700ms var(--ded-admit-ease); }
  .ded-admit-kpi-pin::after { content: ""; position: absolute; left: 12px; right: 12px; bottom: 7px; height: 3px; border-radius: 3px; background: linear-gradient(90deg, var(--ded-admit-accent) calc(var(--ded-admit-pin) * 1%), var(--ded-admit-line) 0); }

  .ded-admit-views { min-height: 0; display: grid; }
  .ded-admit-card { min-height: 0; display: grid; grid-template-rows: auto minmax(0, 1fr); gap: 8px; padding: 12px 14px; border-radius: 14px; background: var(--ded-admit-panel); box-shadow: inset 0 0 0 1px var(--ded-admit-line); }
  .ded-admit-card > header { display: flex; flex-wrap: wrap; align-items: flex-start; justify-content: space-between; gap: 6px 14px; }
  .ded-admit-card h3 { font-size: 13.5px; font-weight: 700; }
  .ded-admit-card > header p { font-size: 11.5px; color: var(--ded-admit-muted); font-variant-numeric: tabular-nums; }
  .ded-admit-key { display: flex; flex-wrap: wrap; gap: 3px 12px; font-size: 11px; color: var(--ded-admit-muted); }
  .ded-admit-key li { display: flex; align-items: center; gap: 6px; }
  .ded-admit-key i { width: 10px; height: 10px; border-radius: 2px; background: var(--ded-admit-cool); }
  .ded-admit-key i[data-s="t"] { background: var(--ded-admit-accent); }
  .ded-admit-key i[data-s="o"] { background: var(--ded-admit-hot); }
  .ded-admit-key i[data-s="ty"] { height: 0; border-top: 2.4px solid var(--ded-admit-accent); background: none; width: 14px; }
