  dTip.innerHTML = `<b>Class of ${k}</b><span><i>Exactly ${k}</i>${pct(R.at(k), 1)}</span><span><i>${k} or more</i>${pct(clamp(ge, 0, 1), 1)}</span><span><i>Verdict</i>${k > CAP ? 'over capacity' : k >= TARGET[0] && k <= TARGET[1] ? 'on target' : k > TARGET[1] ? 'above target' : 'under target'}</span>`;
  const tw = dTip.offsetWidth, xx = dg.x(k) + dg.bw / 2;
  dTip.style.setProperty('--ded-admit-tx', (xx + 14 + tw > dg.W ? xx - 14 - tw : xx + 14) + 'px');
  dTip.style.setProperty('--ded-admit-ty', Math.max(0, dg.y(R.at(k)) - 70) + 'px');
  dTip.classList.add('is-on');
});
dSvg.addEventListener('pointerleave', () => { dTip.classList.remove('is-on'); bars.forEach(b => b.classList.remove('is-hot')); });

/* ---------------- segments table ---------------- */
function segRows() {
  const all = admitted();
  return SEG.map((s, si) => {
    const mine = all.filter(a => a.si === si), und = mine.filter(a => !a.dep);
    const dep = mine.length - und.length, sp = und.reduce((t, a) => t + pEff(a), 0);
    return { name: s.name, adm: mine.length, dep, p: und.length ? sp / und.length : 0, exp: dep + sp };
  });
}
function paintSeg() {
  const rows = segRows(), k = S.sort, dir = S.dir, tot = rows.reduce((t, r) => t + r.exp, 0);
  rows.sort((a, b) => (k === 'name' ? a.name.localeCompare(b.name) : a[k] - b[k]) * dir);
  $('.ded-admit-table tbody').innerHTML = rows.map(r => `<tr><td><b>${r.name}</b></td><td class="ded-admit-n">${r.adm}</td><td class="ded-admit-n">${r.dep}</td><td class="ded-admit-n">${pct(r.p)}</td><td class="ded-admit-n">${r.exp.toFixed(1)}</td><td><span class="ded-admit-share"><span><i style="width:${(r.exp / tot * 100).toFixed(1)}%"></i></span>${pct(r.exp / tot)}</span></td></tr>`).join('');
  const t = rows.reduce((a, r) => ({ adm: a.adm + r.adm, dep: a.dep + r.dep }), { adm: 0, dep: 0 });
  $('.ded-admit-table tfoot').innerHTML = `<tr><td>All segments</td><td class="ded-admit-n">${t.adm}</td><td class="ded-admit-n">${t.dep}</td><td class="ded-admit-n">${pct((tot - t.dep) / Math.max(1, t.adm - t.dep))}</td><td class="ded-admit-n">${tot.toFixed(1)}</td><td>100%</td></tr>`;
  $$('.ded-admit-table th').forEach(th => { const b = th.querySelector('button'); if (b) th.setAttribute('aria-sort', b.dataset.sort === k ? (dir > 0 ? 'ascending' : 'descending') : 'none'); });
}
$('.ded-admit-table thead').addEventListener('click', ev => {
  const b = ev.target.closest('button[data-sort]'); if (!b) return;
  const k = b.dataset.sort;
  if (S.sort === k) S.dir = -S.dir; else { S.sort = k; S.dir = k === 'name' ? 1 : -1; }
  paintSeg();
});

/* ---------------- deposits by week ---------------- */
const MON = ['Jan', 'Feb', 'Mar', 'Apr', 'May', 'Jun', 'Jul', 'Aug', 'Sep', 'Oct', 'Nov', 'Dec'];
const WKS = Array.from({ length: 11 }, (_, w) => new Date(2026, 7, 31 + 7 * w));
const TY = [3, 9, 18, 31, 48], LY = [2, 7, 15, 27, 41, 58, 79, 102, 128, 157, 181], NOW = 4;
const pBox = $('.ded-admit-dep'), pSvg = pBox.querySelector('svg'), pTip = pBox.querySelector('.ded-admit-tip');
let pg = null, depDrawn = false;
function paintDep() {
  const W = pBox.clientWidth, H = pBox.clientHeight;
  if (W < 60 || H < 60) return;
  pSvg.setAttribute('viewBox', `0 0 ${W} ${H}`); pSvg.innerHTML = '';
  const m = { l: 36, r: 46, t: 12, b: 22 }, ymax = 220;
  const x = w => m.l + w / 10 * (W - m.l - m.r), y = v => H - m.b - v / ymax * (H - m.t - m.b);
  const frac = w => (LY[w] - LY[NOW]) / (LY[10] - LY[NOW]);
  const proj = q => Array.from({ length: 11 - NOW }, (_, i) => TY[NOW] + (q - TY[NOW]) * frac(NOW + i));
  const pm = proj(R.mean), p10 = proj(R.p10), p90 = proj(R.p90);
  pg = { x, y, m, W, H, pm };
  const g = mk('g', { class: 'ded-admit-g' }, pSvg);
  for (let v = 0; v <= ymax; v += 50) { mk('line', { x1: m.l, x2: W - m.r, y1: y(v), y2: y(v) }, g); mk('text', { x: m.l - 6, y: y(v) + 3.5, 'text-anchor': 'end' }, g).textContent = v; }
  WKS.forEach((d, w) => { if (w % 2 === 0) mk('text', { x: x(w), y: H - 5, 'text-anchor': 'middle' }, g).textContent = d.getDate() + ' ' + MON[d.getMonth()]; });
  const line = (arr, off = 0) => arr.map((v, i) => `${i ? 'L' : 'M'}${x(i + off).toFixed(1)} ${y(v).toFixed(1)}`).join(' ');
  const cone = mk('path', { class: 'ded-admit-cone', d: line(p90, NOW) + ' ' + p10.map((v, i) => `L${x(10 - i).toFixed(1)} ${y(p10[p10.length - 1 - i]).toFixed(1)}`).join(' ') + ' Z' }, pSvg);
  mk('path', { class: 'ded-admit-ly', d: line(LY) }, pSvg);
  const pr = mk('path', { class: 'ded-admit-pr', d: line(pm, NOW) }, pSvg);
  const ty = mk('path', { class: 'ded-admit-ty', d: line(TY), pathLength: 1 }, pSvg);
  if (depDrawn) { ty.style.animation = 'none'; cone.style.animation = pr.style.animation = 'none'; }
  depDrawn = true;
  mk('line', { class: 'ded-admit-now', x1: x(NOW), x2: x(NOW), y1: m.t, y2: H - m.b }, pSvg);
  mk('text', { x: x(NOW) + 4, y: m.t + 9 }, pSvg).textContent = 'today';
  mk('line', { class: 'ded-admit-cap', x1: m.l, x2: W - m.r, y1: y(CAP), y2: y(CAP) }, pSvg);
  mk('text', { class: 'ded-admit-capl', x: W - m.r + 4, y: y(CAP) + 3.5 }, pSvg).textContent = CAP;
  mk('text', { class: 'ded-admit-bandl', x: W - m.r + 4, y: y(pm[pm.length - 1]) + 3.5 }, pSvg).textContent = pm[pm.length - 1].toFixed(0);
  pg.hair = mk('line', { class: 'ded-admit-hair', x1: -20, x2: -20, y1: m.t, y2: H - m.b }, pSvg);
  $('[data-k="depsub"]').textContent = `${TY[NOW]} deposits so far against ${LY[NOW]} at this point last cycle · projected to ${R.mean.toFixed(0)} by the deadline`;
}
pSvg.addEventListener('pointermove', ev => {
  if (!pg) return;
  const r = pSvg.getBoundingClientRect(), w = clamp(Math.round((ev.clientX - r.left - pg.m.l) / (pg.W - pg.m.l - pg.m.r) * 10), 0, 10);
  pg.hair.setAttribute('x1', pg.x(w)); pg.hair.setAttribute('x2', pg.x(w));
  const d = WKS[w];
  pTip.innerHTML = `<b>w/c ${d.getDate()} ${MON[d.getMonth()]}</b><span><i>${w <= NOW ? 'This cycle' : 'Projected'}</i>${w <= NOW ? TY[w] : pg.pm[w - NOW].toFixed(0)}</span><span><i>Last cycle</i>${LY[w]}</span>`;
  const tw = pTip.offsetWidth, xx = pg.x(w);
  pTip.style.setProperty('--ded-admit-tx', (xx + 14 + tw > pg.W ? xx - 14 - tw : xx + 14) + 'px');
  pTip.style.setProperty('--ded-admit-ty', '10px');
  pTip.classList.add('is-on');
});
pSvg.addEventListener('pointerleave', () => pTip.classList.remove('is-on'));

/* ---------------- levers ---------------- */
function paintLevers() {
  const used = S.batches.reduce((t, b) => t + b.length, 0), left = WL.length - used;
  $('[data-k="wl"]').textContent = `${left} waiting · ${used} admitted from it`;
  const ad = $('[data-act="admit"]'), rl = $('[data-act="release"]');
  ad.disabled = !left; ad.title = left ? `Offer places to the next ${Math.min(10, left)} on the ranked waitlist` : 'The waitlist is empty';
  ad.textContent = `Admit next ${Math.min(10, left) || 10}`;
  rl.disabled = !S.batches.length; rl.title = S.batches.length ? 'Withdraw the most recent batch of waitlist offers' : 'No waitlist offers have been made yet';
}
function recompute() {
  const funded = allocateAid();
  R = distribution();
  $('[data-k="aid"]').textContent = '£' + S.aid + 'k';
  $('[data-k="aidn"]').textContent = S.aid ? `${funded} awards of £2,500 offered to undecided self-funded applicants most likely to respond.` : 'Each £20k funds eight £2,500 awards to the undecided self-funded applicants most likely to respond.';
  paintKpis(); paintLevers();
  if (S.tab === 'fc') paintDist();
  if (S.tab === 'seg') paintSeg();
  if (S.tab === 'dep') paintDep();
}
const withDelta = (label, fn) => { const before = R.mean; fn(); recompute(); const d = R.mean - before; log(label, d); return d; };
$('[data-act="admit"]').addEventListener('click', () => {
  const used = S.batches.reduce((t, b) => t + b.length, 0), next = WL.slice(used, used + 10);
  if (!next.length) return;
  const d = withDelta(`${next.length} from waitlist`, () => { S.batches.push(next); });
  toast(`${next.length} waitlist offers made · expected class ${d >= 0 ? '+' : '−'}${Math.abs(d).toFixed(1)}`);
});
$('[data-act="release"]').addEventListener('click', () => {
  if (!S.batches.length) return;
  const n = S.batches[S.batches.length - 1].length;
  const d = withDelta(`Withdrew ${n} offers`, () => { S.batches.pop(); });
  toast(`Last ${n} waitlist offers withdrawn · expected class −${Math.abs(d).toFixed(1)}`);
});
const aidIn = $('input[type="range"]', $('.ded-admit-levers'));
let aidStart = null;
aidIn.addEventListener('input', () => { if (aidStart == null) aidStart = { aid: S.aid, mean: R.mean }; S.aid = +aidIn.value; aidIn.setAttribute('aria-valuetext', '£' + S.aid + ' thousand'); recompute(); });
aidIn.addEventListener('change', () => { if (aidStart && aidStart.aid !== S.aid) log(`Scholarships £${aidStart.aid}k → £${S.aid}k`, R.mean - aidStart.mean); aidStart = null; });
$$('input[data-sc]').forEach(inp => inp.addEventListener('change', () => {
  const k = inp.dataset.sc;
  withDelta(k === 'visa' ? (inp.checked ? 'Visa refusals on' : 'Visa refusals off') : (inp.checked ? 'Deadline extended' : 'Deadline restored'), () => { S[k] = inp.checked; });
}));

/* ---------------- tabs ---------------- */
const tabs = $$('.ded-admit-tabs [role="tab"]');
function setTab(t) {
  S.tab = t;
  tabs.forEach(b => { const on = b.dataset.tab === t; b.setAttribute('aria-selected', on); b.tabIndex = on ? 0 : -1; });
  $$('.ded-admit-view').forEach((v, i) => { v.hidden = ['fc', 'seg', 'dep'][i] !== t; });
  if (t === 'fc') paintDist(); if (t === 'seg') paintSeg(); if (t === 'dep') paintDep();
}
$('.ded-admit-tabs').addEventListener('click', ev => { const b = ev.target.closest('[role="tab"]'); if (b && b.getAttribute('aria-selected') !== 'true') setTab(b.dataset.tab); });
$('.ded-admit-tabs').addEventListener('keydown', ev => {
  const i = tabs.indexOf(document.activeElement); if (i < 0) return;
  const d = ev.key === 'ArrowRight' ? 1 : ev.key === 'ArrowLeft' ? -1 : 0; if (!d) return;
  ev.preventDefault(); const b = tabs[(i + d + tabs.length) % tabs.length]; b.focus(); setTab(b.dataset.tab);
});

/* ---------------- mount ---------------- */
recompute();
logEl.innerHTML = '<li><span>Model loaded: 360 admitted, 90 waitlisted</span></li>';
let raf = 0;
const ro = new ResizeObserver(() => {
  cancelAnimationFrame(raf);
  raf = requestAnimationFrame(() => {
    if (!root.isConnected) return void ro.disconnect();
    if (S.tab === 'fc') paintDist(); else if (S.tab === 'dep') paintDep();
  });
});
ro.observe(dBox); ro.observe(pBox);

css:
@property --ded-items-rel { syntax: '<number>'; inherits: true; initial-value: 0; }
@keyframes ded-items-in { from { opacity: 0; translate: 0 8px; } }
@keyframes ded-items-pop { from { opacity: 0; scale: 0.3; } }
@keyframes ded-items-draw { from { stroke-dashoffset: 1; } to { stroke-dashoffset: 0; } }
@keyframes ded-items-tick { from { clip-path: inset(0 100% 0 0); } to { clip-path: inset(0 0 0 0); } }
@keyframes ded-items-grow { from { scale: 0 1; } }

.ded-items {
  /* re-theme with these four */
  --ded-items-paper: oklch(0.987 0.006 95);
  --ded-items-ink: oklch(0.23 0.012 265);
  --ded-items-pen: oklch(0.55 0.2 27);
  --ded-items-rule: oklch(0.62 0.08 245);
  /* derived */
  --ded-items-desk: color-mix(in oklch, var(--ded-items-paper), var(--ded-items-ink) 5%);
  --ded-items-line: color-mix(in oklch, var(--ded-items-ink) 11%, transparent);
  --ded-items-line2: color-mix(in oklch, var(--ded-items-ink) 22%, transparent);
  --ded-items-muted: color-mix(in oklch, var(--ded-items-ink) 62%, var(--ded-items-paper));
  --ded-items-faint: color-mix(in oklch, var(--ded-items-ink) 40%, var(--ded-items-paper));
  --ded-items-pentint: color-mix(in oklch, var(--ded-items-pen) 10%, var(--ded-items-paper));
  --ded-items-ease: cubic-bezier(0.2, 0.8, 0.2, 1);
  --ded-items-spring: linear(0, 0.05, 0.2 7%, 0.63 17%, 0.96 26%, 1.07 33%, 1.06 40%, 1.01 51%, 0.995 63%, 1);
  --ded-items-mono: ui-monospace, Menlo, Consolas, monospace;
  --ded-items-serif: ui-serif, "Iowan Old Style", "Palatino Linotype", Georgia, serif;

  width: 100%;
  height: var(--ded-items-h, 680px);
  container-type: inline-size;
  position: relative;
  overflow: hidden;
  box-sizing: border-box;
  display: grid;
  grid-template-rows: auto auto minmax(0, 1fr);
  gap: 12px;
  padding: 0 16px 16px;
  border-radius: 16px;
  background: var(--ded-items-desk);
  color: var(--ded-items-ink);
  font: 400 13px/1.45 system-ui, -apple-system, "Segoe UI", Roboto, sans-serif;
  accent-color: var(--ded-items-pen);
  box-shadow: inset 0 0 0 1px var(--ded-items-line);

  & *, & *::before, & *::after { box-sizing: border-box; }
  & button { font: inherit; color: inherit; background: none; border: 0; padding: 0; margin: 0; cursor: pointer; text-align: inherit; }
  & button[aria-disabled="true"] { cursor: not-allowed; }
  & :focus-visible { outline: 2px solid var(--ded-items-pen); outline-offset: 2px; border-radius: 6px; }
  & h2, & h3, & h4 { margin: 0; text-wrap: balance; }
  & p { margin: 0; text-wrap: pretty; }
  & ol, & ul { margin: 0; padding: 0; list-style: none; }
  & svg { display: block; }
  & [hidden] { display: none !important; }
  & .ded-items-eyebrow { font-size: 10.5px; font-weight: 650; letter-spacing: 0.11em; text-transform: uppercase; color: var(--ded-items-muted); }

  /* ---------- header ---------- */
  .ded-items-top { display: flex; flex-wrap: wrap; align-items: center; gap: 10px 22px; margin: 0 -16px; padding: 14px 18px 12px; border-bottom: 1px solid var(--ded-items-line); background: var(--ded-items-paper); }
  .ded-items-brand { display: flex; align-items: center; gap: 10px; }
  .ded-items-brand svg { width: 34px; height: 34px; padding: 6px; border-radius: 9px; background: var(--ded-items-ink); fill: none; stroke: var(--ded-items-paper); stroke-width: 1.6; stroke-linecap: round; stroke-linejoin: round; }
  .ded-items-brand span { display: grid; line-height: 1.2; }
  .ded-items-brand b { font-size: 13.5px; font-weight: 720; }
  .ded-items-brand small { font-size: 11px; color: var(--ded-items-muted); }
  .ded-items-title { margin-right: auto; min-width: 0; }
  .ded-items-title h2 { font: 600 clamp(18px, 1rem + 0.7cqi, 24px)/1.15 var(--ded-items-serif); letter-spacing: -0.01em; }
  .ded-items-hacts { display: flex; align-items: center; gap: 10px; font-size: 12px; color: var(--ded-items-muted); }
  .ded-items-hacts span:not(:empty) { color: var(--ded-items-pen); font-weight: 650; }
  .ded-items-btn { min-height: 32px; padding: 6px 12px; border-radius: 9px; font-size: 12.5px; font-weight: 650; background: var(--ded-items-paper); box-shadow: inset 0 0 0 1px var(--ded-items-line2); transition: background-color 140ms, color 140ms, opacity 140ms, scale 200ms var(--ded-items-spring); }
  .ded-items-btn:hover:not([aria-disabled="true"]) { background: var(--ded-items-desk); }
  .ded-items-btn:active:not([aria-disabled="true"]) { scale: 0.96; }
  .ded-items-btn[aria-disabled="true"] { opacity: 0.45; }
  .ded-items-btn[aria-pressed="true"] { background: var(--ded-items-pen); color: var(--ded-items-paper); box-shadow: none; }

  /* ---------- KPIs ---------- */
  .ded-items-kpis { display: grid; grid-template-columns: repeat(4, minmax(0, 1fr)); gap: 8px; }
  .ded-items-kpi { position: relative; display: grid; gap: 0; padding: 9px 12px; border-radius: 12px; background: var(--ded-items-paper); box-shadow: inset 0 0 0 1px var(--ded-items-line); animation: ded-items-in 520ms var(--ded-items-ease) both; animation-delay: calc(var(--i) * 55ms); }
  .ded-items-kpi > span { font-size: 10.5px; font-weight: 650; letter-spacing: 0.09em; text-transform: uppercase; color: var(--ded-items-muted); }
  .ded-items-kpi b { font: 600 clamp(21px, 0.9rem + 1.2cqi, 28px)/1.12 var(--ded-items-serif); font-variant-numeric: tabular-nums lining-nums; }
  .ded-items-kpi b small { font: 600 12px var(--ded-items-mono); color: var(--ded-items-muted); margin-left: 4px; }
  .ded-items-kpi > small { font-size: 11px; color: var(--ded-items-muted); font-variant-numeric: tabular-nums; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
  .ded-items-kpi > small i { font-style: normal; font-weight: 700; color: var(--ded-items-pen); }
  .ded-items-gauge { --ded-items-rel: var(--ded-items-rv, 0); transition: --ded-items-rel 800ms var(--ded-items-ease); }
  .ded-items-gauge::after { content: ""; position: absolute; right: 12px; top: 12px; width: 38px; height: 38px; border-radius: 50%; background: radial-gradient(closest-side, var(--ded-items-paper) 76%, transparent 78%), conic-gradient(var(--ded-items-ink) calc(var(--ded-items-rel) * 360deg), var(--ded-items-line) 0); }

  /* ---------- body ---------- */
  .ded-items-body { min-height: 0; display: grid; grid-template-columns: clamp(170px, 18cqi, 214px) minmax(0, 1fr) clamp(300px, 31cqi, 360px); gap: 12px; }
  .ded-items-listp, .ded-items-scatp, .ded-items-paper { min-height: 0; border-radius: 14px; background: var(--ded-items-paper); box-shadow: inset 0 0 0 1px var(--ded-items-line), 0 1px 2px var(--ded-items-line); }
  .ded-items-listp { display: grid; grid-template-rows: auto minmax(0, 1fr); gap: 8px; padding: 10px 6px 6px; }
  .ded-items-seg { display: flex; margin: 0 4px; padding: 3px; gap: 2px; border-radius: 9px; background: var(--ded-items-desk); }
  .ded-items-seg button { flex: 1; padding: 4px 6px; border-radius: 7px; font-size: 12px; font-weight: 600; text-align: center; color: var(--ded-items-muted); transition: background-color 150ms, color 150ms; }
  .ded-items-seg button[aria-checked="true"] { background: var(--ded-items-paper); color: var(--ded-items-ink); box-shadow: 0 1px 2px var(--ded-items-line2); }
  .ded-items-list { min-height: 0; overflow: auto; display: grid; align-content: start; gap: 1px; padding: 0 2px; scrollbar-width: thin; scrollbar-color: var(--ded-items-line2) transparent; }
  .ded-items-opt {
    display: grid; grid-template-columns: 38px minmax(0, 1fr) auto; grid-template-rows: auto auto; column-gap: 6px; align-items: center;
    padding: 6px 8px; border-radius: 8px; cursor: pointer; transition: background-color 130ms;
  }
  .ded-items-opt:hover { background: var(--ded-items-desk); }
  .ded-items-opt[aria-selected="true"] { background: var(--ded-items-pentint); box-shadow: inset 2px 0 0 var(--ded-items-pen); }
  .ded-items-opt b { grid-row: 1 / 3; font: 650 12px var(--ded-items-mono); }
  .ded-items-opt span { min-width: 0; font-size: 11.5px; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
  .ded-items-opt em { font: 600 11px var(--ded-items-mono); font-style: normal; color: var(--ded-items-muted); font-variant-numeric: tabular-nums; }
  .ded-items-opt i { grid-column: 2 / 4; height: 3px; border-radius: 2px; background: linear-gradient(90deg, var(--ded-items-ink) var(--p), var(--ded-items-line) 0); transition: background 300ms; }
  .ded-items-opt[data-flag] em { color: var(--ded-items-pen); font-weight: 750; }
  .ded-items-opt[data-flag] b::after { content: ""; display: inline-block; width: 5px; height: 5px; margin-left: 3px; border-radius: 50%; background: var(--ded-items-pen); vertical-align: 2px; }
  .ded-items-opt[data-drop] span { text-decoration: line-through; color: var(--ded-items-faint); }
  .ded-items-empty { padding: 20px 8px; font-size: 12px; color: var(--ded-items-muted); }

  .ded-items-scatp { display: grid; grid-template-rows: auto minmax(0, 1fr); gap: 4px; padding: 12px 14px; }
  .ded-items-scatp h3 { font-size: 13.5px; font-weight: 700; }
  .ded-items-scatp header p { font-size: 11.5px; color: var(--ded-items-muted); }
  .ded-items-scat { position: relative; min-height: 0; }
  .ded-items-scat svg { position: absolute; inset: 0; width: 100%; height: 100%; overflow: visible; }
  .ded-items-scat text, .ded-items-trace text { fill: var(--ded-items-faint); font: 10px var(--ded-items-mono); font-variant-numeric: tabular-nums; }
  .ded-items-g line { stroke: var(--ded-items-line); }
  .ded-items-guide { stroke: var(--ded-items-pen); stroke-opacity: 0.55; stroke-dasharray: 4 4; }
  .ded-items-zero { stroke: var(--ded-items-line2); }
  .ded-items-scat .ded-items-zl { fill: var(--ded-items-pen); fill-opacity: 0.75; font: italic 11px var(--ded-items-serif); }
  .ded-items-scat .ded-items-axl { fill: var(--ded-items-muted); font: 600 10.5px system-ui, sans-serif; letter-spacing: 0.04em; }
